fn runtime_driver_error_to_session_error(err: meerkat_runtime::RuntimeDriverError) -> SessionError {
    // A session this owner may not host keeps its typed refusal (#1813).
    if let Some(hosting) = err.hosting_session_error() {
        return hosting;
    }
    SessionError::Agent(AgentError::InternalError(err.to_string()))
}

fn activation_store_error_to_session_error(error: RuntimeStoreError) -> SessionError {
    match error {
        RuntimeStoreError::WriteFenceConflict { reason } => {
            SessionError::ExternalWriteFenceConflict { reason }
        }
        RuntimeStoreError::WriteFenceBackoff { reason } => {
            SessionError::ExternalWriteFenceBackoff { reason }
        }
        RuntimeStoreError::Unsupported(detail) => SessionError::Unsupported(detail),
        other => SessionError::Agent(AgentError::InternalError(other.to_string())),
    }
}

/// Map a committed-WholeBlob read failure to the typed session error hosts
/// classify on: the audited-endpoint divergence means "this session needs the
/// sanctioned repair", everything else stays an internal agent error.
fn whole_blob_read_error_to_session_error(
    session_id: &SessionId,
    role: &str,
    error: RuntimeStoreError,
) -> SessionError {
    match error {
        RuntimeStoreError::AuditedEndpointDivergence { .. } => {
            SessionError::WholeBlobAuditedEndpointDivergence {
                id: session_id.clone(),
            }
        }
        other => SessionError::Agent(AgentError::InternalError(format!(
            "failed to load {role} for session {session_id}: {other}"
        ))),
    }
}

/// Re-read budget for observation loads racing a head-canonical writer:
/// counted attempts, never wall clock (issue #1104).
const OBSERVATION_LOAD_ATTEMPTS: usize = 8;

/// Bound on the wait for a session's turn-finalization boundary before a
/// tail settle that does not hold it: a strict read running a settle an
/// observation deferred (`settle_deferred_ended_tail_for_strict_read`), and a
/// cold attach's settle (`prepare_cold_attach_hosted`). A settle commits only
/// between runtime loop laps; this covers the short holders while a tail
/// stands: the post-commit work of a finished lap, a lap whose run the
/// standing tail refuses before its model call, and a lap whose resumed-run
/// admission answers once a stop or retire settled that run. A boundary
/// still held after it leaves the tail standing, and the caller's committed
/// read refuses as before.
const TAIL_SETTLE_BOUNDARY_BOUND: std::time::Duration = std::time::Duration::from_secs(1);

/// How the settle of an ended turn's tail takes the per-session recovery
/// gate: an observation takes only a free gate (a holder owns the tail), and
/// a strict read waits for it, bounded.
#[derive(Debug, Clone, Copy)]
enum EndedTailRecoveryGate {
    Try,
    Await(std::time::Duration),
}

/// Consecutive transcript-authority invalidations an optimistic live read
/// absorbs with a plain yield before it warns and starts backing off (#1226).
const OPTIMISTIC_READ_RETRY_WARN_AFTER: u32 = 64;

/// Upper bound on the backoff an optimistic live read sleeps between
/// retries once it has exceeded [`OPTIMISTIC_READ_RETRY_WARN_AFTER`].
const OPTIMISTIC_READ_RETRY_MAX_BACKOFF: std::time::Duration = std::time::Duration::from_millis(32);

/// How one optimistic-read retry was paced.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OptimisticReadRetryPacing {
    /// Below the warn threshold: cooperative yield only.
    Yield,
    /// At or above the threshold: slept for a bounded backoff. `warned` is
    /// true only on the retry that emitted the single WARN.
    Backoff {
        delay: std::time::Duration,
        warned: bool,
    },
}

/// Retry pacing for the generation-checked optimistic live-read loops.
///
/// The loops must keep retrying: a view whose transcript authority changed
/// between the two observations is not a consistent view, and returning it
/// would break the ABA/authority contract. What this bounds is the cost and
/// the silence: every retry yields, retries past the threshold back off (so
/// a continuously invalidated read cannot spin hot), and the first retry past
/// the threshold logs one WARN naming the session and the retry count.
struct OptimisticReadRetry<'a> {
    session_id: &'a SessionId,
    operation: &'static str,
    retries: u32,
    warned: bool,
}

impl<'a> OptimisticReadRetry<'a> {
    fn new(session_id: &'a SessionId, operation: &'static str) -> Self {
        Self {
            session_id,
            operation,
            retries: 0,
            warned: false,
        }
    }

    /// Account for one invalidated iteration and decide its pacing.
    fn record_retry(&mut self) -> OptimisticReadRetryPacing {
        self.retries = self.retries.saturating_add(1);
        if self.retries < OPTIMISTIC_READ_RETRY_WARN_AFTER {
            return OptimisticReadRetryPacing::Yield;
        }
        let warned = !self.warned;
        if warned {
            self.warned = true;
            tracing::warn!(
                session_id = %self.session_id,
                operation = self.operation,
                retries = self.retries,
                "optimistic live session read keeps losing to concurrent transcript-authority \
                 changes; backing off between retries"
            );
        }
        let exponent = (self.retries - OPTIMISTIC_READ_RETRY_WARN_AFTER).min(5);
        let delay = std::time::Duration::from_millis(1_u64 << exponent)
            .min(OPTIMISTIC_READ_RETRY_MAX_BACKOFF);
        OptimisticReadRetryPacing::Backoff { delay, warned }
    }

    /// Account for one invalidated iteration and pace the next one.
    async fn retry(&mut self) {
        match self.record_retry() {
            OptimisticReadRetryPacing::Yield => tokio::task::yield_now().await,
            OptimisticReadRetryPacing::Backoff { delay, .. } => tokio::time::sleep(delay).await,
        }
    }

    /// Record the eventual success of a read that had to warn.
    fn finish(&self) {
        if self.warned {
            tracing::info!(
                session_id = %self.session_id,
                operation = self.operation,
                retries = self.retries,
                "optimistic live session read converged after backing off"
            );
        }
    }
}

