    #[cfg(feature = "live")]
    async fn append_realtime_transcript_event_with_machine_origin(
        &self,
        machine: &MeerkatMachine,
        id: &SessionId,
        event: meerkat_core::RealtimeTranscriptEvent,
        channel_id: Option<meerkat_core::LiveChannelId>,
    ) -> Result<meerkat_core::RealtimeTranscriptApplyOutcome, SessionError> {
        let mutation_guard = match channel_id.as_ref() {
            Some(channel_id) => {
                self.realtime_transcript_mutation_guard_for_channel(id, channel_id)
                    .await?
            }
            None => self.realtime_transcript_mutation_guard(id).await?,
        };
        let outcome = self
            .append_realtime_transcript_event_guarded_with_origin(id, event, channel_id)
            .await?;
        let committed_projection = if outcome.materialized_messages.is_empty() {
            None
        } else {
            Some(self.committed_realtime_projection_guarded(id).await?)
        };
        drop(mutation_guard);
        if let Some((committed, token)) = committed_projection {
            machine
                .enqueue_committed_live_transcript_boundary(id, &committed, &token)
                .await
                .map_err(runtime_driver_error_to_session_error)?;
        }
        Ok(outcome)
    }

    #[cfg(feature = "live")]
    async fn committed_realtime_projection_guarded(
        &self,
        id: &SessionId,
    ) -> Result<(BoundSessionCommit, String), SessionError> {
        let session = self.inner.export_session(id).await?;
        let authority = self
            .observe_persisted_session_authority(id)
            .await?
            .ok_or_else(|| {
                SessionError::Agent(AgentError::InternalError(format!(
                    "realtime transcript commit returned no store authority for session {id}"
                )))
            })?;
        let token = match &authority {
            RuntimeSessionAuthority::WholeBlob(authority) => authority.blob_sha256().to_string(),
            RuntimeSessionAuthority::HeadCanonical(authority) => {
                authority.committed_head_token().to_string()
            }
        };
        let committed = BoundSessionCommit::sealed(Arc::new(session)).map_err(|error| {
            SessionError::Agent(AgentError::InternalError(format!(
                "failed to seal committed realtime transcript projection for session {id}: {error}"
            )))
        })?;
        Ok((committed, token))
    }

    async fn append_realtime_transcript_event_guarded(
        &self,
        id: &SessionId,
        event: meerkat_core::RealtimeTranscriptEvent,
    ) -> Result<meerkat_core::RealtimeTranscriptApplyOutcome, SessionError> {
        self.append_realtime_transcript_event_guarded_with_origin(id, event, None)
            .await
    }

    async fn append_realtime_transcript_event_guarded_with_origin(
        &self,
        id: &SessionId,
        event: meerkat_core::RealtimeTranscriptEvent,
        channel_id: Option<meerkat_core::LiveChannelId>,
    ) -> Result<meerkat_core::RealtimeTranscriptApplyOutcome, SessionError> {
        let mut current = self.inner.export_session(id).await?;
        if let Some(user_content) = current.preflight_realtime_user_content_event(&event) {
            if matches!(
                user_content,
                meerkat_core::RealtimeUserContentApplyOutcome::AlreadyCommitted(_)
            ) {
                let prepared = self
                    .prepare_realtime_user_content_blob(&event)
                    .await?
                    .ok_or_else(|| {
                        realtime_user_content_blob_error(
                            "already-committed realtime user content was not a canonical image",
                            "missing image ingress",
                        )
                    })?;
                self.ensure_prepared_realtime_user_content_blob(&prepared)
                    .await?;
            }
            return Ok(user_content_outcome(user_content));
        }

        let prepared = self.prepare_realtime_user_content_blob(&event).await?;
        if let Some(outcome) = self
            .reconcile_pending_realtime_user_content_blob(id, &mut current, prepared.as_ref())
            .await?
        {
            return Ok(outcome);
        }

        // Reconciliation may have committed an older pending anchor. Re-run
        // admission against that new durable state before any current-request
        // blob write; the current key may now be an exact replay or conflict.
        if let Some(user_content) = current.preflight_realtime_user_content_event(&event) {
            if matches!(
                user_content,
                meerkat_core::RealtimeUserContentApplyOutcome::AlreadyCommitted(_)
            ) {
                let prepared = prepared.as_ref().ok_or_else(|| {
                    realtime_user_content_blob_error(
                        "reconciled realtime user content was not a canonical image",
                        "missing image ingress",
                    )
                })?;
                self.ensure_prepared_realtime_user_content_blob(prepared)
                    .await?;
            }
            return Ok(user_content_outcome(user_content));
        }

        let Some(prepared) = prepared else {
            let outcome = match channel_id {
                Some(channel) => {
                    self.inner
                        .append_realtime_transcript_event_for_channel(id, event, channel)
                        .await?
                }
                None => {
                    self.inner
                        .append_realtime_transcript_event(id, event)
                        .await?
                }
            };
            if let Err(error) = self.persist_full_session(id).await {
                let _ = self.discard_live_session_unfenced(id).await;
                return Err(error);
            }
            return Ok(outcome);
        };

        use meerkat_core::generated::session_document::RealtimeUserContentBlobStageDisposition;
        if let Some(observation_id) = event.context_observation_id() {
            current.append_realtime_transcript_event(
                meerkat_core::RealtimeTranscriptEvent::ContextObservationBound {
                    channel_id: observation_id.channel_id().clone(),
                    item_id: prepared.pending.item_id.clone(),
                    observation_id: observation_id.clone(),
                },
            );
        }
        let stage = current
            .stage_pending_realtime_user_content_blob(prepared.pending.clone())
            .map_err(|error| {
                realtime_user_content_blob_error(
                    "failed to authorize realtime user-content blob staging",
                    error,
                )
            })?;
        if stage != RealtimeUserContentBlobStageDisposition::StageNew {
            return Err(realtime_user_content_blob_error(
                "realtime user-content blob staging did not acquire an empty slot",
                format!("unexpected stage disposition {stage:?}"),
            ));
        }
        // Crash point A: the bounded metadata-only anchor becomes durable
        // before put. A failed/uncertain persist performs no blob write.
        self.persist_realtime_transcript_snapshot(id, &current)
            .await?;

        // Crash point B: put/repair is atomic, directory-synced, and read back
        // under the decoded-size bound while the durable anchor remains.
        self.ensure_prepared_realtime_user_content_blob(&prepared)
            .await?;

        let outcome = self
            .commit_pending_realtime_user_content_blob(id, &mut current, &prepared)
            .await?;
        // A receipt is still withheld until a final post-commit verification.
        // If an external actor removed/corrupted the object concurrently, an
        // inline retry can repair it through the AlreadyCommitted path.
        self.ensure_prepared_realtime_user_content_blob(&prepared)
            .await?;
        Ok(outcome)
    }

    /// Persist canonical provider-final live user input before releasing the
    /// SessionDocument-sealed commit evidence to runtime authority.
    #[cfg(feature = "live")]
    pub async fn commit_live_user_transcript_final_with_machine(
        &self,
        machine: &MeerkatMachine,
        id: &SessionId,
        provisional: meerkat_core::ProvisionalLiveHandoff,
        final_event: Option<meerkat_core::RealtimeTranscriptEvent>,
    ) -> Result<meerkat_core::FinalLiveUserTranscriptCommitEvidence, SessionError> {
        let mutation_guard = self.realtime_transcript_mutation_guard(id).await?;
        let evidence = self
            .commit_live_user_transcript_final_guarded(id, provisional, final_event)
            .await?;
        let (committed, token) = self.committed_realtime_projection_guarded(id).await?;
        drop(mutation_guard);
        machine
            .enqueue_committed_live_transcript_boundary(id, &committed, &token)
            .await
            .map_err(runtime_driver_error_to_session_error)?;
        Ok(evidence)
    }

    /// [`Self::commit_live_user_transcript_final_with_machine`] that waits at
    /// most `bound` for the source session's turn-finalization boundary.
    ///
    /// A live delegation arrives while the member that owns the canonical
    /// session may be mid-turn. That turn holds the turn-finalization gate
    /// for its whole duration, and the canonical commit of the spoken input
    /// must wait behind it (the transcript cannot be extended under a
    /// running turn). Waiting without a bound stalled the caller for the
    /// length of the member's turn with nothing to say to the user; this
    /// entry point reports `SourceBusy` at the bound instead, having
    /// committed nothing, so the caller can narrate and retry. Once the
    /// boundary is won the commit runs to completion under it; the bound
    /// never cancels a commit in progress.
    #[cfg(feature = "live")]
    pub async fn commit_live_user_transcript_final_with_machine_at_turn_boundary(
        &self,
        machine: &MeerkatMachine,
        id: &SessionId,
        provisional: meerkat_core::ProvisionalLiveHandoff,
        final_event: Option<meerkat_core::RealtimeTranscriptEvent>,
        bound: std::time::Duration,
    ) -> Result<meerkat_core::LiveFinalTranscriptCommitAtTurnBoundary, SessionError> {
        let started = std::time::Instant::now();
        let Ok(turn_finalization_guard) =
            tokio::time::timeout(bound, self.acquire_runtime_turn_finalization_guard(id)).await
        else {
            return Ok(
                meerkat_core::LiveFinalTranscriptCommitAtTurnBoundary::SourceBusy {
                    waited: started.elapsed(),
                },
            );
        };
        let mutation_guard = self
            .realtime_transcript_mutation_guard_with_turn_boundary(id, turn_finalization_guard)
            .await?;
        let evidence = self
            .commit_live_user_transcript_final_guarded(id, provisional, final_event)
            .await?;
        let (committed, token) = self.committed_realtime_projection_guarded(id).await?;
        drop(mutation_guard);
        machine
            .enqueue_committed_live_transcript_boundary(id, &committed, &token)
            .await
            .map_err(runtime_driver_error_to_session_error)?;
        Ok(meerkat_core::LiveFinalTranscriptCommitAtTurnBoundary::Committed(evidence))
    }

    /// [`Self::commit_live_user_transcript_final_with_machine_at_turn_boundary`]
    /// for a client delegation that re-presents user rows the live transcript
    /// already committed (the provider finished those turns before the
    /// delegation arrived). The rows are verified in the session actor and
    /// none is appended; the reconciled evidence is released like a commit.
    #[cfg(feature = "live")]
    pub async fn commit_live_user_transcript_represented_with_machine_at_turn_boundary(
        &self,
        machine: &MeerkatMachine,
        id: &SessionId,
        provisional: meerkat_core::ProvisionalLiveHandoff,
        final_event: meerkat_core::RealtimeTranscriptEvent,
        represented: Vec<meerkat_core::RepresentedLiveUserRow>,
        bound: std::time::Duration,
    ) -> Result<meerkat_core::LiveFinalTranscriptCommitAtTurnBoundary, SessionError> {
        let started = std::time::Instant::now();
        let Ok(turn_finalization_guard) =
            tokio::time::timeout(bound, self.acquire_runtime_turn_finalization_guard(id)).await
        else {
            return Ok(
                meerkat_core::LiveFinalTranscriptCommitAtTurnBoundary::SourceBusy {
                    waited: started.elapsed(),
                },
            );
        };
        let mutation_guard = self
            .realtime_transcript_mutation_guard_with_turn_boundary(id, turn_finalization_guard)
            .await?;
        let evidence = self
            .inner
            .commit_live_user_transcript_represented(id, provisional, final_event, represented)
            .await?;
        let (committed, token) = self.committed_realtime_projection_guarded(id).await?;
        drop(mutation_guard);
        machine
            .enqueue_committed_live_transcript_boundary(id, &committed, &token)
            .await
            .map_err(runtime_driver_error_to_session_error)?;
        Ok(meerkat_core::LiveFinalTranscriptCommitAtTurnBoundary::Committed(evidence))
    }

