    #[allow(clippy::too_many_arguments)]
    #[cfg(feature = "live")]
    pub async fn observe_live_assistant_playback_terminal_with_machine(
        &self,
        machine: &MeerkatMachine,
        id: &SessionId,
        channel_id: meerkat_core::LiveChannelId,
        interaction_id: meerkat_core::InteractionId,
        response_id: String,
        item_id: String,
        content_index: u32,
        evidence: meerkat_core::LiveAssistantPlaybackEvidence,
        stop_reason: meerkat_core::StopReason,
        usage: meerkat_core::TurnUsage,
    ) -> Result<crate::LiveAssistantPlaybackObservationResult, SessionError> {
        let mutation_guard = self
            .realtime_transcript_mutation_guard_for_channel(id, &channel_id)
            .await?;
        let outcome = self
            .inner
            .observe_live_assistant_playback_terminal(
                id,
                channel_id,
                interaction_id,
                response_id,
                item_id,
                content_index,
                evidence,
                stop_reason,
                usage,
            )
            .await?;
        if let Err(error) = self.persist_full_session(id).await {
            let _ = self.discard_live_session_unfenced(id).await;
            return Err(error);
        }
        let committed_projection = if matches!(&outcome,
            crate::LiveAssistantPlaybackObservationResult::Resolved(receipt)
                if receipt.continues_provider_group()
        ) {
            Some(self.committed_realtime_projection_guarded(id).await?)
        } else {
            None
        };
        drop(mutation_guard);
        if let Some((committed, token)) = committed_projection {
            machine
                .enqueue_committed_live_transcript_boundary(id, &committed, &token)
                .await
                .map_err(runtime_driver_error_to_session_error)?;
        }
        if let crate::LiveAssistantPlaybackObservationResult::Resolved(receipt) = &outcome
            && receipt.continues_provider_group()
            && let Err(error) = machine
                .advance_live_assistant_playback_segment(receipt)
                .await
        {
            // A release a closed channel's deferred settlement replays commits
            // its speech above; the closed channel has no next segment to
            // advance to, so that is not a refusal of the release.
            if machine
                .live_channel_is_active_for_session(id, receipt.channel_id())
                .await
            {
                return Err(SessionError::Agent(
                    meerkat_core::error::AgentError::InternalError(error.to_string()),
                ));
            }
            tracing::debug!(
                session_id = %id,
                channel_id = %receipt.channel_id(),
                %error,
                "a playback release committed after its channel closed advances no segment"
            );
        }
        Ok(outcome)
    }

