        async fn commit_prepared_session_boundary(
            &self,
            runtime_id: &LogicalRuntimeId,
            request: meerkat_runtime::PreparedRuntimeSessionCommit,
        ) -> Result<
            meerkat_runtime::store::PreparedRuntimeSessionCommitResult,
            meerkat_runtime::store::RuntimeStoreError,
        > {
            let ordinal = self
                .snapshot_commit_count
                .fetch_add(1, Ordering::AcqRel)
                .saturating_add(1);
            if self.pause_session_boundary_commit.load(Ordering::Acquire) {
                let released = self.release_session_boundary_commit.notified();
                tokio::pin!(released);
                released.as_mut().enable();
                self.entered_session_boundary_commit.notify_waiters();
                released.await;
            }
            if self.fail_snapshot_commits.load(Ordering::Acquire) {
                return Err(meerkat_runtime::store::RuntimeStoreError::WriteFailed(
                    "synthetic runtime snapshot commit failure".to_string(),
                ));
            }
            if self
                .fail_snapshot_commit_ordinal
                .compare_exchange(ordinal, usize::MAX, Ordering::AcqRel, Ordering::Acquire)
                .is_ok()
            {
                return Err(meerkat_runtime::store::RuntimeStoreError::WriteFailed(
                    format!("synthetic runtime snapshot commit failure at ordinal {ordinal}"),
                ));
            }
            if let Some(interloper) = self
                .replace_snapshot_interlopers
                .lock()
                .await
                .remove(runtime_id)
            {
                self.inner
                    .commit_session_snapshot(
                        runtime_id,
                        SerializedSessionSnapshot {
                            session_snapshot: interloper.into(),
                        },
                    )
                    .await?;
            }
            let result = self
                .inner
                .commit_prepared_session_boundary(runtime_id, request)
                .await?;
            if self
                .fail_after_session_boundary_commit
                .swap(false, Ordering::AcqRel)
            {
                return Err(meerkat_runtime::store::RuntimeStoreError::WriteFailed(
                    "synthetic WholeBlob post-commit reporting failure".to_string(),
                ));
            }
            if self
                .pause_after_session_boundary_commit
                .load(Ordering::Acquire)
            {
                let released = self.release_after_session_boundary_commit.notified();
                tokio::pin!(released);
                released.as_mut().enable();
                self.entered_after_session_boundary_commit.notify_waiters();
                released.await;
            }
            Ok(result)
        }

        async fn commit_session_snapshot(
            &self,
            runtime_id: &LogicalRuntimeId,
            session_delta: meerkat_runtime::store::SerializedSessionSnapshot,
        ) -> Result<(), meerkat_runtime::store::RuntimeStoreError> {
            let ordinal = self
                .snapshot_commit_count
                .fetch_add(1, Ordering::AcqRel)
                .saturating_add(1);
            if self.fail_snapshot_commits.load(Ordering::Acquire) {
                return Err(meerkat_runtime::store::RuntimeStoreError::WriteFailed(
                    "synthetic runtime snapshot commit failure".to_string(),
                ));
            }
            if self
                .fail_snapshot_commit_ordinal
                .compare_exchange(ordinal, usize::MAX, Ordering::AcqRel, Ordering::Acquire)
                .is_ok()
            {
                return Err(meerkat_runtime::store::RuntimeStoreError::WriteFailed(
                    format!("synthetic runtime snapshot commit failure at ordinal {ordinal}"),
                ));
            }
            if let Some(interloper) = self
                .replace_snapshot_interlopers
                .lock()
                .await
                .remove(runtime_id)
            {
                self.inner
                    .commit_session_snapshot(
                        runtime_id,
                        SerializedSessionSnapshot {
                            session_snapshot: (interloper).into(),
                        },
                    )
                    .await?;
            }
            self.inner
                .commit_session_snapshot(runtime_id, session_delta)
                .await
        }

        async fn commit_prepared_whole_blob_rewrite_boundary(
            &self,
            runtime_id: &LogicalRuntimeId,
            boundary: meerkat_runtime::store::PreparedWholeBlobRewriteStoreParts,
        ) -> Result<
            meerkat_runtime::store::WholeBlobStoreAuthority,
            meerkat_runtime::store::RuntimeStoreError,
        > {
            if self.pause_rewrite_commit.swap(false, Ordering::AcqRel) {
                self.entered_rewrite_commit.notify_one();
                self.release_rewrite_commit.notified().await;
            }
            let ordinal = self
                .snapshot_commit_count
                .fetch_add(1, Ordering::AcqRel)
                .saturating_add(1);
            if self.fail_snapshot_commits.load(Ordering::Acquire) {
                return Err(meerkat_runtime::store::RuntimeStoreError::WriteFailed(
                    "synthetic runtime snapshot commit failure".to_string(),
                ));
            }
            if self
                .fail_snapshot_commit_ordinal
                .compare_exchange(ordinal, usize::MAX, Ordering::AcqRel, Ordering::Acquire)
                .is_ok()
            {
                return Err(meerkat_runtime::store::RuntimeStoreError::WriteFailed(
                    format!("synthetic runtime snapshot commit failure at ordinal {ordinal}"),
                ));
            }
            if let Some(interloper) = self
                .replace_snapshot_interlopers
                .lock()
                .await
                .remove(runtime_id)
            {
                self.inner
                    .commit_session_snapshot(
                        runtime_id,
                        SerializedSessionSnapshot {
                            session_snapshot: (interloper).into(),
                        },
                    )
                    .await?;
            }
            self.inner
                .commit_prepared_whole_blob_rewrite_boundary(runtime_id, boundary)
                .await
        }

