    async fn machine_commit_runtime_output<B: SessionAgentBuilder + 'static>(
        service: &PersistentSessionService<B>,
        runtime_store: &dyn RuntimeStore,
        session_id: &SessionId,
        output: &CoreApplyOutput,
    ) -> Result<(), String> {
        let runtime_id = PersistentSessionService::<B>::runtime_id_for_session(session_id);
        let committed = output.committed().cloned();
        let provisional = committed
            .as_ref()
            .and_then(BoundSessionCommit::provisional_promotion_receipt)
            .cloned();
        let receipt = output.receipt.clone().into_sequenced(0);
        let prepared = match provisional.as_ref() {
            Some(checkpoint) => match runtime_store.session_persistence_profile() {
                RuntimeSessionPersistenceProfile::WholeBlobV1 => {
                    let promotion =
                        meerkat_runtime::store::PreparedWholeBlobProvisionalPromotion::prepare(
                            checkpoint.clone(),
                            &receipt.run_id,
                        )
                        .expect("prepare WholeBlob provisional promotion");
                    meerkat_runtime::store::PreparedRuntimeSessionCommit::promote_whole_blob_success(
                        promotion,
                        receipt,
                        Vec::new(),
                        session_id.clone(),
                    )
                    .expect("bind WholeBlob terminal receipt to checkpoint facts")
                }
                RuntimeSessionPersistenceProfile::HeadCanonicalV1 => {
                    let promotion =
                        meerkat_runtime::store::PreparedHeadCanonicalProvisionalPromotion::prepare(
                            checkpoint.clone(),
                            &receipt.run_id,
                        )
                        .expect("prepare HeadCanonical provisional promotion");
                    meerkat_runtime::store::PreparedRuntimeSessionCommit::promote_head_canonical_success(
                        promotion,
                        receipt,
                        Vec::new(),
                        session_id.clone(),
                    )
                    .expect("bind HeadCanonical terminal receipt to checkpoint facts")
                }
                profile => {
                    return Err(format!(
                        "test runtime store uses unsupported session persistence profile {profile:?}"
                    ));
                }
            },
            None => meerkat_runtime::store::PreparedRuntimeSessionCommit::success(
                committed.clone(),
                receipt,
                Vec::new(),
                Some(session_id.clone()),
            ),
        };
        let result = runtime_store
            .commit_prepared_session_boundary(&runtime_id, prepared)
            .await
            .expect("machine-owned runtime output commit should succeed");
        if provisional.is_some() {
            let authority = result
                .authority()
                .expect("provisional promotion must return committed authority");
            let (revision, token) = match authority {
                RuntimeSessionAuthority::WholeBlob(authority) => {
                    (authority.store_revision(), authority.blob_sha256())
                }
                RuntimeSessionAuthority::HeadCanonical(authority) => {
                    (authority.store_revision(), authority.committed_head_token())
                }
            };
            service
                .acknowledge_provisional_runtime_session_boundary_under_runtime_turn_boundary(
                    session_id, revision, token,
                )
                .await
                .expect("acknowledge exact provisional promotion");
        } else if let Some(committed) = committed {
            match runtime_store.session_persistence_profile() {
                RuntimeSessionPersistenceProfile::WholeBlobV1 => {
                    let authority = result
                        .authority()
                        .and_then(RuntimeSessionAuthority::whole_blob)
                        .expect("whole-blob commit must return authority");
                    let artifact = committed
                        .whole_blob_artifact()
                        .expect("whole-blob runtime output boundary should encode");
                    assert_eq!(
                        authority.blob_sha256(),
                        artifact.row_sha256_token(),
                        "store authority must bind the exact prepared artifact"
                    );
                    service
                        .acknowledge_whole_blob_runtime_session_boundary_under_runtime_turn_boundary(
                            session_id,
                            authority.store_revision(),
                            authority.blob_sha256(),
                        )
                        .await
                        .expect("acknowledge exact WholeBlob authority");
                }
                RuntimeSessionPersistenceProfile::HeadCanonicalV1 => {
                    let authority = result
                        .authority()
                        .and_then(RuntimeSessionAuthority::head_canonical)
                        .expect("head-canonical commit must return authority");
                    service
                        .acknowledge_head_canonical_runtime_session_boundary_under_runtime_turn_boundary(
                            session_id,
                            authority.committed_head_token(),
                        )
                        .await
                        .expect("acknowledge exact HeadCanonical boundary");
                }
                profile => {
                    return Err(format!(
                        "test runtime store uses unsupported session persistence profile {profile:?}"
                    ));
                }
            }
        }
        Ok(())
    }

    /// Item 4: the audited-endpoint repair refuses while EITHER liveness
    /// witness says an actor owns the session (checkpointer or a live registry
    /// entry), and runs once the actor is discarded.
    #[tokio::test]
    async fn whole_blob_repair_refuses_while_a_live_actor_owns_the_session() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            CapturingBuildBuilder::new(),
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );
        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create WholeBlob live actor");
        let session_id = created.session_id;
        assert!(
            service
                .live_session_actor_witness(&session_id)
                .await
                .is_some_and(|witness| witness.is_live()),
            "a freshly created session has a live registry witness"
        );
        let refused = service
            .repair_whole_blob_audited_endpoint(&session_id, false, false)
            .await
            .expect_err("repair must refuse while the actor is live");
        assert!(
            refused.to_string().contains("still has a live actor"),
            "unexpected refusal: {refused}"
        );
        service
            .discard_live_session(&session_id)
            .await
            .expect("discard the live actor");
        let report = service
            .repair_whole_blob_audited_endpoint(&session_id, false, false)
            .await
            .expect("diagnose runs once no actor owns the session");
        assert_eq!(
            report.action,
            meerkat_runtime::store::whole_blob_repair::WholeBlobRepairAction::NoRepairNeeded,
            "a healthy committed document needs no repair"
        );
    }

    #[tokio::test]
    async fn whole_blob_promotion_then_compaction_refreshes_next_run_checkpoint_base() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            CapturingBuildBuilder::new(),
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );
        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create WholeBlob live actor");
        let session_id = created.session_id;
        let runtime_id =
            PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&session_id);
        let checkpointer = service
            .live_checkpointers
            .lock()
            .await
            .get(&session_id)
            .cloned()
            .and_then(|checkpointer| checkpointer.upgrade())
            .expect("live WholeBlob actor must retain its exact checkpointer");
        let committed_base = runtime_store
            .load_committed_whole_blob_snapshot(&runtime_id)
            .await
            .expect("load generation-zero authority")
            .expect("generation-zero authority must exist");

        let mut provisional_session = committed_base.session().clone();
        provisional_session.push(Message::User(UserMessage::text(
            "verbose context one".to_string(),
        )));
        provisional_session.push(Message::User(UserMessage::text(
            "verbose context two".to_string(),
        )));
        let (_rewrite, intent) = provisional_session
            .stage_validated_compaction_for_test(
                vec![Message::User(UserMessage::compaction_summary(
                    "compacted context",
                ))],
                2,
            )
            .expect("core should construct an exact typed compaction fixture");

        let promotion_run = RunId::new();
        let checkpoint = meerkat_core::SessionCheckpointer::checkpoint_run(
            checkpointer.as_ref(),
            &mut provisional_session,
            &promotion_run,
            None,
        )
        .await
        .expect("write provisional WholeBlob candidate")
        .expect("WholeBlob checkpoint must return a store-issued receipt");
        let terminal_receipt = meerkat_core::lifecycle::RunBoundaryReceipt {
            run_id: promotion_run.clone(),
            boundary: RunApplyBoundary::RunStart,
            contributing_input_ids: Vec::new(),
            conversation_digest: Some(checkpoint.conversation_digest().to_string()),
            message_count: usize::try_from(checkpoint.message_count())
                .expect("checkpoint count fits usize"),
            sequence: 1,
            owner_contributions: Vec::new(),
        };
        let promotion = meerkat_runtime::store::PreparedWholeBlobProvisionalPromotion::prepare(
            checkpoint,
            &promotion_run,
        )
        .expect("prepare exact metadata-only promotion");
        let promoted = runtime_store
            .commit_prepared_session_boundary(
                &runtime_id,
                meerkat_runtime::store::PreparedRuntimeSessionCommit::promote_whole_blob_success(
                    promotion,
                    terminal_receipt,
                    Vec::new(),
                    session_id.clone(),
                )
                .expect("bind final receipt to provisional facts"),
            )
            .await
            .expect("promote exact provisional candidate");
        let promoted_authority = promoted
            .authority()
            .and_then(RuntimeSessionAuthority::whole_blob)
            .expect("promotion must return WholeBlob authority")
            .clone();
        service
            .acknowledge_provisional_runtime_session_boundary_under_runtime_turn_boundary(
                &session_id,
                promoted_authority.store_revision(),
                promoted_authority.blob_sha256(),
            )
            .await
            .expect("advance actor base after metadata-only promotion");

        let mut cleaned_session = provisional_session;
        assert_eq!(
            cleaned_session
                .complete_compaction_projection_intent(&intent.projection)
                .expect("remove finalized compaction intent"),
            Some(intent.clone()),
        );
        runtime_store
            .mark_compaction_projection_finalized(&runtime_id, &intent.projection)
            .await
            .expect("finalize the store-owned compaction outbox");
        let cleaned_snapshot = runtime_store
            .load_committed_whole_blob_snapshot(&runtime_id)
            .await
            .expect("load store-cleaned compaction checkpoint")
            .expect("store-cleaned compaction checkpoint must exist");
        service
            .checkpoint_committed_runtime_session_snapshot(
                &session_id,
                cleaned_snapshot.bytes_arc(),
            )
            .await
            .expect("compaction postcommit refresh must advance the actor base");
        let cleaned_authority = cleaned_snapshot.authority().clone();
        assert_eq!(
            checkpointer
                .whole_blob_base_authority
                .lock()
                .expect("actor base authority lock")
                .as_ref(),
            Some(&cleaned_authority),
            "compaction checkpoint acknowledgement must install the exact cleaned authority"
        );

        let mut next_run_session = cleaned_session;
        next_run_session.push(Message::User(UserMessage::text(
            "next run after compaction".to_string(),
        )));
        let next_receipt = meerkat_core::SessionCheckpointer::checkpoint_run(
            checkpointer.as_ref(),
            &mut next_run_session,
            &RunId::new(),
            None,
        )
        .await
        .expect("next run must accept the refreshed actor base")
        .expect("next run must write a provisional successor");
        let next_authority = next_receipt
            .whole_blob()
            .expect("WholeBlob checkpoint must retain its profile");
        assert_eq!(
            next_authority.base_store_revision(),
            cleaned_authority.store_revision()
        );
        assert_eq!(
            next_authority.base_blob_sha256(),
            cleaned_authority.blob_sha256()
        );
    }

    /// A WholeBlob run whose final boundary compacts saves its end as a
    /// cursor-less re-base, so the committed base and the tail are one
    /// document. The process crashes before the boundary commit. The
    /// restarted session service recovers that tail as an interrupted run's
    /// closing save: the committed document is the compacted one with every
    /// row the run wrote, exactly once, plus one interruption notice, and the
    /// tail is consumed. Unrun until the candidate's validation.
    #[tokio::test]
    async fn a_closing_rebase_after_a_final_compaction_recovers_after_a_restart() {
        use meerkat_core::lifecycle::core_executor::BoundSessionCommit;
        use meerkat_core::types::{AssistantBlock, BlockAssistantMessage};
        use meerkat_runtime::store::{
            PreparedRuntimeSessionCommit, PreparedWholeBlobRunRebase,
            VerifiedCommittedWholeBlobPayload, WholeBlobRunRebaseOutcome,
        };

        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        // The session's committed base, as the crashed process left it.
        let mut committed = Session::new();
        committed.push(Message::User(UserMessage::text(
            "earlier context".to_string(),
        )));
        committed.push(Message::User(UserMessage::text(
            "more earlier context".to_string(),
        )));
        let session_id = committed.id().clone();
        let runtime_id =
            PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&session_id);
        runtime_store
            .commit_prepared_session_boundary(
                &runtime_id,
                PreparedRuntimeSessionCommit::snapshot_only(
                    BoundSessionCommit::sealed(Arc::new(committed.clone())).unwrap(),
                ),
            )
            .await
            .unwrap();

        // Its run answered, then compacted at its final boundary, and saved
        // its end as a cursor-less re-base with no earlier tail.
        let run_id = RunId::new();
        let mut live = committed;
        live.push(Message::User(UserMessage::text("the question".to_string())));
        live.push(Message::BlockAssistant(BlockAssistantMessage {
            blocks: vec![AssistantBlock::Text {
                text: "the answer".to_string(),
                meta: None,
            }],
            stop_reason: Some(StopReason::EndTurn),
            identity: meerkat_core::types::TranscriptMessageIdentity::default()
                .with_run_id(run_id.clone()),
            created_at: meerkat_core::types::message_timestamp_now(),
            assistant_message_id: None,
        }));
        let parent = live.transcript_revision().unwrap();
        let commit = live
            .commit_transcript_rewrite(
                meerkat_core::TranscriptRewriteSelection::MessageRange { start: 0, end: 2 },
                vec![Message::User(UserMessage::compaction_summary(
                    "earlier context, compacted",
                ))],
                meerkat_core::TranscriptRewriteReason::new("compaction"),
                Some("closing-rebase".to_string()),
                Some(parent),
            )
            .unwrap();
        let compacted_messages = live.messages().to_vec();
        let base = runtime_store
            .load_committed_whole_blob_snapshot(&runtime_id)
            .await
            .unwrap()
            .unwrap();
        let rebase = PreparedWholeBlobRunRebase::prepare(
            VerifiedCommittedWholeBlobPayload::from_committed(&session_id, base).unwrap(),
            None,
            run_id,
            live,
            std::slice::from_ref(&commit),
        )
        .unwrap();
        assert!(matches!(
            runtime_store
                .commit_prepared_whole_blob_run_rebase(&runtime_id, rebase.store_parts())
                .await
                .unwrap(),
            WholeBlobRunRebaseOutcome::Applied { .. }
        ));

        // The restart: a new session service over the same stores.
        let restarted = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );
        let recovery = restarted
            .recover_committed_boundary(&session_id)
            .await
            .expect("the closing save recovers");
        assert_eq!(
            recovery,
            CommittedBoundaryRecovery::Recovered {
                message_count: compacted_messages.len() + 1,
            }
        );
        let recovered = runtime_store
            .load_committed_whole_blob_snapshot(&runtime_id)
            .await
            .unwrap()
            .expect("the recovered boundary");
        let messages = recovered.session().messages();
        assert_eq!(
            &messages[..compacted_messages.len()],
            compacted_messages.as_slice(),
            "nothing the run wrote is lost or duplicated"
        );
        assert!(matches!(messages.last(), Some(Message::SystemNotice(_))));
        assert!(
            runtime_store
                .load_whole_blob_provisional_tail(&runtime_id)
                .await
                .unwrap()
                .is_none(),
            "the recovery consumes the tail"
        );
    }

    fn recovered_input_persistence_record(
        runtime_id: &LogicalRuntimeId,
        mut bundle: StoredInputState,
    ) -> InputStatePersistenceRecord {
        if bundle.state.persisted_input.is_none() {
            let mut input = meerkat_runtime::PromptInput::new("recovered test input", None);
            input.header.id = bundle.state.input_id.clone();
            let input = meerkat_runtime::Input::Prompt(input);
            bundle.state.runtime_semantics.get_or_insert_with(|| {
                meerkat_runtime::ingress_types::RuntimeInputSemantics::try_from_generated_admission(
                    &input, true,
                )
                .expect("test input should receive generated runtime semantics")
            });
            bundle.state.persisted_input = Some(input);
        }
        bundle
            .seed
            .recovery_lane
            .get_or_insert(meerkat_core::types::HandlingMode::Queue);
        let mut driver = meerkat_runtime::EphemeralRuntimeDriver::new(runtime_id.clone());
        driver
            .recover_input_state_persistence_record(bundle)
            .expect("test input-state bundle should recover through generated authority")
    }

