    /// Counts forbidden SessionStore authority writes independently of
    /// RuntimeStore authority and EventStore audit publication.
    struct CountingProjectionSessionStore {
        inner: MemoryStore,
        authoritative_projection_calls: AtomicUsize,
    }

    impl CountingProjectionSessionStore {
        fn new() -> Self {
            Self {
                inner: MemoryStore::new(),
                authoritative_projection_calls: AtomicUsize::new(0),
            }
        }

        fn reset(&self) {
            self.authoritative_projection_calls
                .store(0, Ordering::Release);
        }
    }

    #[async_trait::async_trait]
    impl SessionStore for CountingProjectionSessionStore {
        async fn save(&self, session: &Session) -> Result<(), SessionStoreError> {
            self.inner.save(session).await
        }

        async fn save_transcript_rewrite(
            &self,
            session: &Session,
            commit: &meerkat_core::TranscriptRewriteCommit,
        ) -> Result<(), SessionStoreError> {
            self.inner.save_transcript_rewrite(session, commit).await
        }

        async fn save_authoritative_projection(
            &self,
            session: &Session,
        ) -> Result<(), SessionStoreError> {
            self.inner.save_authoritative_projection(session).await
        }

        async fn save_authoritative_projection_if_current_revision(
            &self,
            session: &Session,
            expected_current_revision: Option<String>,
        ) -> Result<(), SessionStoreError> {
            self.authoritative_projection_calls
                .fetch_add(1, Ordering::AcqRel);
            self.inner
                .save_authoritative_projection_if_current_revision(
                    session,
                    expected_current_revision,
                )
                .await
        }

        async fn load(&self, id: &SessionId) -> Result<Option<Session>, SessionStoreError> {
            self.inner.load(id).await
        }

        async fn list(
            &self,
            filter: meerkat_store::SessionFilter,
        ) -> Result<Vec<meerkat_core::SessionMeta>, SessionStoreError> {
            self.inner.list(filter).await
        }

        async fn delete(&self, id: &SessionId) -> Result<(), SessionStoreError> {
            self.inner.delete(id).await
        }

        async fn delete_if_current_revision(
            &self,
            id: &SessionId,
            expected_current_revision: &str,
        ) -> Result<bool, SessionStoreError> {
            self.inner
                .delete_if_current_revision(id, expected_current_revision)
                .await
        }
    }

    /// Byte-accounting RuntimeStore: sums every whole-document snapshot
    /// payload handed across the runtime-store write boundary, split by
    /// producer seam. Regression gate for the 2026-07-29 boundary-write
    /// audit: one committed turn is exactly ONE document-sized snapshot
    /// payload (the atomic boundary apply), and one persisted rewrite commit
    /// is exactly ONE document-sized rewrite snapshot — no duplicate
    /// whole-document writes hiding in the chain.
    struct CountingRuntimeStore {
        inner: InMemoryRuntimeStore,
        snapshot_commit_bytes: std::sync::atomic::AtomicU64,
        snapshot_commits: AtomicUsize,
        rewrite_snapshot_bytes: std::sync::atomic::AtomicU64,
        rewrite_successor_encode_bytes: std::sync::atomic::AtomicU64,
        rewrite_snapshot_cas_calls: AtomicUsize,
        rewrite_snapshot_commits: AtomicUsize,
        boundary_apply_bytes: std::sync::atomic::AtomicU64,
        boundary_apply_snapshots: AtomicUsize,
    }

    impl CountingRuntimeStore {
        fn new() -> Self {
            Self {
                inner: InMemoryRuntimeStore::new(),
                snapshot_commit_bytes: std::sync::atomic::AtomicU64::new(0),
                snapshot_commits: AtomicUsize::new(0),
                rewrite_snapshot_bytes: std::sync::atomic::AtomicU64::new(0),
                rewrite_successor_encode_bytes: std::sync::atomic::AtomicU64::new(0),
                rewrite_snapshot_cas_calls: AtomicUsize::new(0),
                rewrite_snapshot_commits: AtomicUsize::new(0),
                boundary_apply_bytes: std::sync::atomic::AtomicU64::new(0),
                boundary_apply_snapshots: AtomicUsize::new(0),
            }
        }

        fn reset(&self) {
            self.snapshot_commit_bytes.store(0, Ordering::Release);
            self.snapshot_commits.store(0, Ordering::Release);
            self.rewrite_snapshot_bytes.store(0, Ordering::Release);
            self.rewrite_successor_encode_bytes
                .store(0, Ordering::Release);
            self.rewrite_snapshot_cas_calls.store(0, Ordering::Release);
            self.rewrite_snapshot_commits.store(0, Ordering::Release);
            self.boundary_apply_bytes.store(0, Ordering::Release);
            self.boundary_apply_snapshots.store(0, Ordering::Release);
        }
    }

    /// The store checkpointer re-bases WholeBlob runs only over a runtime
    /// store that says it implements the run re-base. A decorator that
    /// forwards the store's other operations but not that one leaves its runs
    /// on the fallback (no round commit after a rewrite) instead of failing
    /// their next round commit.
    #[test]
    fn the_checkpointer_rebases_runs_only_over_a_store_that_supports_it() {
        let checkpointer = |runtime_store: Arc<dyn RuntimeStore>| StoreCheckpointer {
            runtime_store,
            incremental: None,
            blob_store: memory_blob_store(),
            gate: Arc::new(CheckpointerGate {
                cancelled: Mutex::new(false),
            }),
            whole_blob_base_authority: std::sync::Mutex::new(None),
            latest_run_checkpoint_receipt: Mutex::new(None),
            latest_run_transcript_retirement: std::sync::Mutex::new(None),
            live_deferred_turn_state: std::sync::OnceLock::new(),
            unattached_deferred_checkpoint_warned: std::sync::atomic::AtomicBool::new(false),
            rebased_run: std::sync::Mutex::new(None),
            latest_run_checkpoint_cursor: std::sync::Mutex::new(None),
            rebase_outcome_unknown: std::sync::Mutex::new(None),
            rewrite_audit: None,
        };

        let memory: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        assert_eq!(
            memory.session_persistence_profile(),
            RuntimeSessionPersistenceProfile::WholeBlobV1
        );
        assert!(memory.supports_whole_blob_run_rebase());
        assert!(meerkat_core::SessionCheckpointer::rebases_runs(
            &checkpointer(memory)
        ));

        let decorated: Arc<dyn RuntimeStore> = Arc::new(CountingRuntimeStore::new());
        assert_eq!(
            decorated.session_persistence_profile(),
            RuntimeSessionPersistenceProfile::WholeBlobV1
        );
        assert!(!decorated.supports_whole_blob_run_rebase());
        assert!(!meerkat_core::SessionCheckpointer::rebases_runs(
            &checkpointer(decorated)
        ));
    }

    /// The store checkpointer's run re-base through the real seam: a
    /// single-turn WholeBlob run whose one boundary compacts saves its end
    /// with no cursor and no earlier tail (`rebase_run` with no previous
    /// receipt). The receipt names the new tail at candidate sequence 1 on
    /// the new base. The process crashes before the boundary commit, and a
    /// restarted session service recovers the session's committed boundary
    /// as an interrupted run's closing save. Unrun until the candidate's
    /// validation.
    #[tokio::test]
    async fn a_checkpointer_closing_rebase_recovers_after_a_restart() {
        use meerkat_core::lifecycle::core_executor::BoundSessionCommit;
        use meerkat_core::types::{AssistantBlock, BlockAssistantMessage};
        use meerkat_runtime::store::PreparedRuntimeSessionCommit;

        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let mut committed = Session::new();
        committed.push(Message::User(UserMessage::text(
            "earlier context".to_string(),
        )));
        committed.push(Message::User(UserMessage::text(
            "more earlier context".to_string(),
        )));
        let session_id = committed.id().clone();
        let runtime_id =
            PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&session_id);
        let base_authority = runtime_store
            .commit_prepared_session_boundary(
                &runtime_id,
                PreparedRuntimeSessionCommit::snapshot_only(
                    BoundSessionCommit::sealed(Arc::new(committed.clone())).unwrap(),
                ),
            )
            .await
            .unwrap()
            .authority()
            .and_then(RuntimeSessionAuthority::whole_blob)
            .cloned()
            .expect("a WholeBlob base");
        // The live actor's checkpointer over that base.
        let checkpointer = StoreCheckpointer {
            runtime_store: Arc::clone(&runtime_store),
            incremental: None,
            blob_store: memory_blob_store(),
            gate: Arc::new(CheckpointerGate {
                cancelled: Mutex::new(false),
            }),
            whole_blob_base_authority: std::sync::Mutex::new(Some(base_authority.clone())),
            latest_run_checkpoint_receipt: Mutex::new(None),
            latest_run_transcript_retirement: std::sync::Mutex::new(None),
            live_deferred_turn_state: std::sync::OnceLock::new(),
            unattached_deferred_checkpoint_warned: std::sync::atomic::AtomicBool::new(false),
            rebased_run: std::sync::Mutex::new(None),
            latest_run_checkpoint_cursor: std::sync::Mutex::new(None),
            rebase_outcome_unknown: std::sync::Mutex::new(None),
            rewrite_audit: None,
        };
        assert!(meerkat_core::SessionCheckpointer::rebases_runs(
            &checkpointer
        ));

        // The run answered, then compacted at its final boundary: its
        // end-of-run save carries no cursor.
        let run_id = RunId::new();
        let mut session = committed;
        session.push(Message::User(UserMessage::text("the question".to_string())));
        session.push(Message::BlockAssistant(BlockAssistantMessage {
            blocks: vec![AssistantBlock::Text {
                text: "the answer".to_string(),
                meta: None,
            }],
            stop_reason: Some(StopReason::EndTurn),
            identity: meerkat_core::types::TranscriptMessageIdentity::default()
                .with_run_id(run_id.clone()),
            created_at: meerkat_core::types::message_timestamp_now(),
            assistant_message_id: None,
        }));
        let parent = session.transcript_revision().unwrap();
        session
            .commit_transcript_rewrite(
                meerkat_core::TranscriptRewriteSelection::MessageRange { start: 0, end: 2 },
                vec![Message::User(UserMessage::compaction_summary(
                    "earlier context, compacted",
                ))],
                meerkat_core::TranscriptRewriteReason::new("compaction"),
                Some("checkpointer-closing-rebase".to_string()),
                Some(parent),
            )
            .unwrap();
        assert!(session.try_run_cursor().unwrap().is_none());
        let compacted_messages = session.messages().to_vec();
        let receipt = meerkat_core::SessionCheckpointer::rebase_run(
            &checkpointer,
            &mut session,
            &run_id,
            None,
        )
        .await
        .expect("the closing save re-bases");
        let tail = receipt
            .whole_blob()
            .cloned()
            .expect("a WholeBlob provisional receipt");
        assert_eq!(tail.run_id(), &run_id);
        assert_eq!(tail.candidate_sequence(), 1);
        assert_eq!(
            tail.base_store_revision(),
            base_authority.store_revision() + 1
        );
        assert_eq!(tail.candidate_blob_sha256(), tail.base_blob_sha256());

        // The process crashes before the boundary commit; a new session
        // service over the same stores recovers.
        drop(checkpointer);
        let restarted = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );
        let recovery = restarted
            .recover_committed_boundary(&session_id)
            .await
            .expect("the closing save recovers");
        assert_eq!(
            recovery,
            CommittedBoundaryRecovery::Recovered {
                message_count: compacted_messages.len() + 1,
            }
        );
        let recovered = runtime_store
            .load_committed_whole_blob_snapshot(&runtime_id)
            .await
            .unwrap()
            .expect("the recovered boundary");
        let messages = recovered.session().messages();
        assert_eq!(
            &messages[..compacted_messages.len()],
            compacted_messages.as_slice(),
            "nothing the run wrote is lost or duplicated"
        );
        assert!(matches!(messages.last(), Some(Message::SystemNotice(_))));
        assert!(
            runtime_store
                .load_whole_blob_provisional_tail(&runtime_id)
                .await
                .unwrap()
                .is_none(),
            "the recovery consumes the tail"
        );
    }

    /// A host store whose renews always fail: the realm's first renew
    /// stops its writer, and its self-fence window closes.
    #[cfg(not(target_arch = "wasm32"))]
    #[derive(Debug)]
    struct RenewFailingHost;

    #[cfg(not(target_arch = "wasm32"))]
    #[async_trait::async_trait]
    impl meerkat_core::host_store::HostStore for RenewFailingHost {
        async fn acquire_fence(
            &self,
            _mode: meerkat_core::host_store::AcquireMode,
        ) -> Result<meerkat_core::host_store::FenceGrant, meerkat_core::host_store::HostStoreError>
        {
            Ok(meerkat_core::host_store::FenceGrant {
                token: meerkat_core::host_store::FenceToken::new(1),
                superseded_lease: std::time::Duration::ZERO,
            })
        }

        async fn renew_fence(
            &self,
            _token: meerkat_core::host_store::FenceToken,
        ) -> Result<(), meerkat_core::host_store::HostStoreError> {
            Err(meerkat_core::host_store::HostStoreError::Unavailable(
                "every renew fails in this row".to_string(),
            ))
        }

        fn fence_timing(&self) -> meerkat_core::host_store::FenceTiming {
            meerkat_core::host_store::FenceTiming::try_new(
                std::time::Duration::from_secs(1),
                std::time::Duration::from_secs(3),
            )
            .expect("a 1 s renew interval on a 3 s lease")
        }

        async fn load_head(
            &self,
            _scope: &meerkat_core::host_store::ScopeRef,
        ) -> Result<
            Option<meerkat_core::host_store::VersionedHead>,
            meerkat_core::host_store::HostStoreError,
        > {
            Ok(None)
        }

        async fn list_heads(
            &self,
            _kind: meerkat_core::host_store::ScopeKind,
            _after: Option<&meerkat_core::host_store::ScopeName>,
            _limit: usize,
        ) -> Result<meerkat_core::host_store::HeadPage, meerkat_core::host_store::HostStoreError>
        {
            Ok(meerkat_core::host_store::HeadPage {
                heads: Vec::new(),
                next: None,
            })
        }

        async fn read_rows(
            &self,
            _scope: &meerkat_core::host_store::ScopeRef,
            _from: meerkat_core::host_store::RowIndex,
            _limit: usize,
        ) -> Result<Vec<meerkat_core::host_store::Row>, meerkat_core::host_store::HostStoreError>
        {
            Ok(Vec::new())
        }

        async fn commit(
            &self,
            _batch: &meerkat_core::host_store::CommitBatch,
        ) -> Result<(), meerkat_core::host_store::HostStoreError> {
            Ok(())
        }
    }

    /// The store checkpointer reads the host store's self-fence: over a host
    /// store realm whose writer's window has closed (its renew failed),
    /// `dispatch_fence_check` refuses with the teardown class, so the run
    /// makes no model call and dispatches no tool. An open window, and a
    /// store without a lease, allow. Unrun until the candidate's validation.
    #[cfg(not(target_arch = "wasm32"))]
    #[tokio::test(start_paused = true)]
    async fn a_closed_host_store_fence_window_refuses_dispatch() {
        use meerkat_runtime::store::spi::{SpiRealm, SpiRealmConfig, SpiRuntimeStore};
        let checkpointer = |runtime_store: Arc<dyn RuntimeStore>| StoreCheckpointer {
            runtime_store,
            incremental: None,
            blob_store: memory_blob_store(),
            gate: Arc::new(CheckpointerGate {
                cancelled: Mutex::new(false),
            }),
            whole_blob_base_authority: std::sync::Mutex::new(None),
            latest_run_checkpoint_receipt: Mutex::new(None),
            latest_run_transcript_retirement: std::sync::Mutex::new(None),
            live_deferred_turn_state: std::sync::OnceLock::new(),
            unattached_deferred_checkpoint_warned: std::sync::atomic::AtomicBool::new(false),
            rebased_run: std::sync::Mutex::new(None),
            latest_run_checkpoint_cursor: std::sync::Mutex::new(None),
            rebase_outcome_unknown: std::sync::Mutex::new(None),
            rewrite_audit: None,
        };
        let realm = SpiRealm::open(Arc::new(RenewFailingHost), SpiRealmConfig::default())
            .await
            .expect("the realm opens");
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(
            SpiRuntimeStore::open(realm)
                .await
                .expect("the runtime store opens"),
        );
        let fenced = checkpointer(runtime_store);
        // Right after the acquire, the window is open.
        meerkat_core::SessionCheckpointer::dispatch_fence_check(&fenced)
            .expect("an open window allows");
        // The first renew, at 1 s, fails: the writer stops and its window
        // closes until a fresh acquire and renew succeed, which this host
        // never allows.
        tokio::time::sleep(std::time::Duration::from_millis(1500)).await;
        let refused = meerkat_core::SessionCheckpointer::dispatch_fence_check(&fenced)
            .expect_err("a closed window refuses");
        assert_teardown_required_projection_authority(refused, "self-fence window closed");
        // A store without a lease always allows.
        let unfenced = checkpointer(Arc::new(InMemoryRuntimeStore::new()));
        meerkat_core::SessionCheckpointer::dispatch_fence_check(&unfenced)
            .expect("a store without a lease allows");
    }

    struct WholeBlobAuthorityReadProbe {
        inner: InMemoryRuntimeStore,
        bounded_authority_reads: AtomicUsize,
        full_snapshot_reads: AtomicUsize,
        /// Raw body reads that bypass the decoded snapshot seam.
        raw_body_reads: AtomicUsize,
    }

    #[async_trait::async_trait]
    impl RuntimeStore for WholeBlobAuthorityReadProbe {
        fn session_authority_ops(&self) -> &dyn meerkat_runtime::store::RuntimeSessionAuthorityOps {
            self.inner.session_authority_ops()
        }

        fn session_persistence_profile(&self) -> RuntimeSessionPersistenceProfile {
            RuntimeSessionPersistenceProfile::WholeBlobV1
        }

        fn session_boundary_authority_read_cost(
            &self,
        ) -> meerkat_runtime::store::RuntimeSessionAuthorityReadCost {
            self.inner.session_boundary_authority_read_cost()
        }

        async fn commit_prepared_session_boundary(
            &self,
            runtime_id: &LogicalRuntimeId,
            request: meerkat_runtime::PreparedRuntimeSessionCommit,
        ) -> Result<
            meerkat_runtime::store::PreparedRuntimeSessionCommitResult,
            meerkat_runtime::store::RuntimeStoreError,
        > {
            self.inner
                .commit_prepared_session_boundary(runtime_id, request)
                .await
        }

        async fn commit_session_snapshot(
            &self,
            runtime_id: &LogicalRuntimeId,
            session_delta: SerializedSessionSnapshot,
        ) -> Result<(), meerkat_runtime::store::RuntimeStoreError> {
            self.inner
                .commit_session_snapshot(runtime_id, session_delta)
                .await
        }

        async fn commit_prepared_whole_blob_rewrite_boundary(
            &self,
            runtime_id: &LogicalRuntimeId,
            boundary: meerkat_runtime::store::PreparedWholeBlobRewriteStoreParts,
        ) -> Result<WholeBlobStoreAuthority, meerkat_runtime::store::RuntimeStoreError> {
            self.inner
                .commit_prepared_whole_blob_rewrite_boundary(runtime_id, boundary)
                .await
        }

        async fn atomic_apply(
            &self,
            runtime_id: &LogicalRuntimeId,
            session_delta: Option<SerializedSessionSnapshot>,
            receipt: meerkat_core::lifecycle::RunBoundaryReceipt,
            input_updates: Vec<InputStatePersistenceRecord>,
            session_store_key: Option<SessionId>,
        ) -> Result<(), meerkat_runtime::store::RuntimeStoreError> {
            self.inner
                .atomic_apply(
                    runtime_id,
                    session_delta,
                    receipt,
                    input_updates,
                    session_store_key,
                )
                .await
        }

        async fn load_input_states(
            &self,
            runtime_id: &LogicalRuntimeId,
        ) -> Result<Vec<meerkat_runtime::InputStateRow>, meerkat_runtime::store::RuntimeStoreError>
        {
            self.inner.load_input_states(runtime_id).await
        }

        async fn load_boundary_receipt(
            &self,
            runtime_id: &LogicalRuntimeId,
            run_id: &RunId,
            sequence: u64,
        ) -> Result<
            Option<meerkat_core::lifecycle::RunBoundaryReceipt>,
            meerkat_runtime::store::RuntimeStoreError,
        > {
            self.inner
                .load_boundary_receipt(runtime_id, run_id, sequence)
                .await
        }

        async fn load_session_snapshot(
            &self,
            runtime_id: &LogicalRuntimeId,
        ) -> Result<Option<Arc<Vec<u8>>>, meerkat_runtime::store::RuntimeStoreError> {
            self.raw_body_reads.fetch_add(1, Ordering::SeqCst);
            self.inner.load_session_snapshot(runtime_id).await
        }

        async fn clear_session_snapshot(
            &self,
            runtime_id: &LogicalRuntimeId,
        ) -> Result<(), meerkat_runtime::store::RuntimeStoreError> {
            self.inner.clear_session_snapshot(runtime_id).await
        }

        async fn replace_session_snapshot_if_current(
            &self,
            runtime_id: &LogicalRuntimeId,
            expected_current: &[u8],
            replacement: Vec<u8>,
        ) -> Result<bool, meerkat_runtime::store::RuntimeStoreError> {
            self.inner
                .replace_session_snapshot_if_current(runtime_id, expected_current, replacement)
                .await
        }

        async fn clear_session_snapshot_if_current(
            &self,
            runtime_id: &LogicalRuntimeId,
            expected_current: &[u8],
        ) -> Result<bool, meerkat_runtime::store::RuntimeStoreError> {
            self.inner
                .clear_session_snapshot_if_current(runtime_id, expected_current)
                .await
        }

        async fn persist_input_state(
            &self,
            runtime_id: &LogicalRuntimeId,
            state: &InputStatePersistenceRecord,
        ) -> Result<(), meerkat_runtime::store::RuntimeStoreError> {
            self.inner.persist_input_state(runtime_id, state).await
        }

        async fn load_input_state(
            &self,
            runtime_id: &LogicalRuntimeId,
            input_id: &InputId,
        ) -> Result<Option<StoredInputState>, meerkat_runtime::store::RuntimeStoreError> {
            self.inner.load_input_state(runtime_id, input_id).await
        }

        async fn load_machine_lifecycle_record(
            &self,
            runtime_id: &LogicalRuntimeId,
        ) -> Result<Option<Vec<u8>>, meerkat_runtime::store::RuntimeStoreError> {
            self.inner.load_machine_lifecycle_record(runtime_id).await
        }

        async fn commit_machine_lifecycle(
            &self,
            runtime_id: &LogicalRuntimeId,
            commit: meerkat_runtime::store::MachineLifecycleCommit,
            input_states: &[InputStatePersistenceRecord],
        ) -> Result<(), meerkat_runtime::store::RuntimeStoreError> {
            self.inner
                .commit_machine_lifecycle(runtime_id, commit, input_states)
                .await
        }

        async fn load_whole_blob_store_authority(
            &self,
            runtime_id: &LogicalRuntimeId,
        ) -> Result<Option<WholeBlobStoreAuthority>, meerkat_runtime::store::RuntimeStoreError>
        {
            self.bounded_authority_reads.fetch_add(1, Ordering::SeqCst);
            self.inner.load_whole_blob_store_authority(runtime_id).await
        }

        async fn load_committed_whole_blob_snapshot(
            &self,
            runtime_id: &LogicalRuntimeId,
        ) -> Result<Option<CommittedWholeBlobSnapshot>, meerkat_runtime::store::RuntimeStoreError>
        {
            self.full_snapshot_reads.fetch_add(1, Ordering::SeqCst);
            self.inner
                .load_committed_whole_blob_snapshot(runtime_id)
                .await
        }

        async fn list_runtimes_with_recovery_work(
            &self,
        ) -> Result<Vec<LogicalRuntimeId>, meerkat_runtime::store::RuntimeStoreError> {
            self.inner.list_runtimes_with_recovery_work().await
        }
    }

    impl WholeBlobAuthorityReadProbe {
        fn body_reads(&self) -> usize {
            self.full_snapshot_reads.load(Ordering::SeqCst)
                + self.raw_body_reads.load(Ordering::SeqCst)
        }
    }

    /// Every durable-source state: absent, committed, archived. The
    /// observation must never read the body, and the counter must catch a
    /// body read (the positive control at the end).
    #[tokio::test]
    async fn live_durable_source_observation_reads_no_body_in_any_state() {
        let probe = Arc::new(WholeBlobAuthorityReadProbe {
            inner: InMemoryRuntimeStore::new(),
            bounded_authority_reads: AtomicUsize::new(0),
            full_snapshot_reads: AtomicUsize::new(0),
            raw_body_reads: AtomicUsize::new(0),
        });
        let runtime_store: Arc<dyn RuntimeStore> = Arc::clone(&probe) as Arc<dyn RuntimeStore>;
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::new(MemoryStore::new()),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );

        let absent = SessionId::new();
        let before = probe.body_reads();
        assert_eq!(
            service
                .observe_live_durable_source(&absent)
                .await
                .expect("observe absent source"),
            crate::LiveDurableSourceObservation::Absent
        );
        assert_eq!(probe.body_reads(), before, "absent: no body read");

        let session = Session::new();
        let id = session.id().clone();
        let runtime_id = LogicalRuntimeId::for_session(&id);
        let artifact = session
            .to_persisted_artifact()
            .expect("encode test WholeBlob once");
        probe
            .inner
            .commit_session_snapshot(
                &runtime_id,
                SerializedSessionSnapshot {
                    session_snapshot: artifact.bytes_arc(),
                },
            )
            .await
            .expect("seed committed WholeBlob row");
        let revision = probe
            .inner
            .load_whole_blob_store_authority(&runtime_id)
            .await
            .expect("load seeded authority")
            .expect("seeded authority exists")
            .store_revision();
        let before = probe.body_reads();
        assert_eq!(
            service
                .observe_live_durable_source(&id)
                .await
                .expect("observe committed source"),
            crate::LiveDurableSourceObservation::Committed {
                revision: Some(revision)
            }
        );
        assert_eq!(probe.body_reads(), before, "committed: no body read");

        // The machine shares the probe's store state (the in-memory store's
        // clones share one backing map); the service keeps reading through
        // the counting probe.
        let machine = meerkat_runtime::MeerkatMachine::persistent(
            Arc::new(probe.inner.clone()) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        )
        .expect("construct runtime authority");
        machine
            .register_session(id.clone())
            .await
            .expect("register runtime");
        meerkat_runtime::RuntimeControlPlane::retire(&machine, &runtime_id)
            .await
            .expect("retire runtime");
        let before = probe.body_reads();
        assert_eq!(
            service
                .observe_live_durable_source(&id)
                .await
                .expect("observe archived source"),
            crate::LiveDurableSourceObservation::Archived
        );
        assert_eq!(probe.body_reads(), before, "archived: no body read");

        // Positive control: the full authoritative load does read the body,
        // so the counter above is not vacuous.
        let before = probe.body_reads();
        let _ = service.load_authoritative_session(&id).await;
        assert!(
            probe.body_reads() > before,
            "the counting store observes a real body read"
        );
    }

    /// Neither the turn-finalization boundary nor the recovery gate can
    /// stall the observation. Each phase proves its gate is really held with
    /// a control read that does wait on it.
    #[tokio::test]
    async fn live_durable_source_observation_ignores_turn_boundary_and_recovery_gate() {
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::new(MemoryStore::new()),
            Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        );
        let session = Session::new();
        let id = session.id().clone();
        runtime_store
            .commit_session_snapshot(
                &LogicalRuntimeId::for_session(&id),
                SerializedSessionSnapshot {
                    session_snapshot: session
                        .to_persisted_artifact()
                        .expect("encode test WholeBlob")
                        .bytes_arc(),
                },
            )
            .await
            .expect("seed committed WholeBlob row");
        let bound = std::time::Duration::from_millis(100);

        let turn_boundary = service.acquire_runtime_turn_finalization_guard(&id).await;
        assert!(
            tokio::time::timeout(bound, service.live_deferred_first_turn_pending(&id))
                .await
                .is_err(),
            "control: a boundary-taking read waits while the boundary is held"
        );
        let observed = tokio::time::timeout(bound, service.observe_live_durable_source(&id))
            .await
            .expect("observation returns within 100 ms with the turn boundary held")
            .expect("observe committed source");
        assert!(observed.is_committed());
        drop(turn_boundary);

        let recovery_gate = service.recovery_gate_for_session(&id).await;
        let recovery_guard = recovery_gate.lock_owned().await;
        assert!(
            tokio::time::timeout(
                bound,
                service.live_deferred_first_turn_pending_under_runtime_turn_boundary(&id),
            )
            .await
            .is_err(),
            "control: a recovery-gated read waits while the recovery gate is held"
        );
        let observed = tokio::time::timeout(bound, service.observe_live_durable_source(&id))
            .await
            .expect("observation returns within 100 ms with the recovery gate held")
            .expect("observe committed source");
        assert!(observed.is_committed());
        drop(recovery_guard);
    }

    /// A 20 MB member polled 50 times, as a voice console polls readiness:
    /// every poll reports the same committed revision and none reads the
    /// body, so the member's size never reaches the readiness path (#1246).
    #[tokio::test]
    async fn live_durable_source_observation_of_a_large_member_across_fifty_polls_reads_no_body() {
        const BODY_BYTES: usize = 20 * 1024 * 1024;
        let probe = Arc::new(WholeBlobAuthorityReadProbe {
            inner: InMemoryRuntimeStore::new(),
            bounded_authority_reads: AtomicUsize::new(0),
            full_snapshot_reads: AtomicUsize::new(0),
            raw_body_reads: AtomicUsize::new(0),
        });
        let runtime_store: Arc<dyn RuntimeStore> = Arc::clone(&probe) as Arc<dyn RuntimeStore>;
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::new(MemoryStore::new()),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );
        let mut session = Session::new();
        session.push(Message::User(UserMessage::text("x".repeat(BODY_BYTES))));
        let id = session.id().clone();
        let runtime_id = LogicalRuntimeId::for_session(&id);
        let artifact = session
            .to_persisted_artifact()
            .expect("encode the large WholeBlob once");
        assert!(
            artifact.bytes_arc().len() >= BODY_BYTES,
            "control: the committed body really is 20 MB"
        );
        probe
            .inner
            .commit_session_snapshot(
                &runtime_id,
                SerializedSessionSnapshot {
                    session_snapshot: artifact.bytes_arc(),
                },
            )
            .await
            .expect("seed the large committed WholeBlob row");
        let revision = probe
            .inner
            .load_whole_blob_store_authority(&runtime_id)
            .await
            .expect("load seeded authority")
            .expect("seeded authority exists")
            .store_revision();

        let before = probe.body_reads();
        for poll in 0..50 {
            let observed = service
                .observe_live_durable_source(&id)
                .await
                .expect("observe the large committed source");
            assert_eq!(
                observed,
                crate::LiveDurableSourceObservation::Committed {
                    revision: Some(revision)
                },
                "poll {poll}"
            );
        }
        assert_eq!(
            probe.body_reads(),
            before,
            "fifty polls of a 20 MB member never read its body"
        );
    }

    #[tokio::test]
    async fn whole_blob_ordinary_acknowledgement_reads_only_bounded_store_authority() {
        let session = Session::new();
        let session_id = session.id().clone();
        let runtime_id = LogicalRuntimeId::for_session(&session_id);
        let artifact = session
            .to_persisted_artifact()
            .expect("encode test WholeBlob once");
        let probe = Arc::new(WholeBlobAuthorityReadProbe {
            inner: InMemoryRuntimeStore::new(),
            bounded_authority_reads: AtomicUsize::new(0),
            full_snapshot_reads: AtomicUsize::new(0),
            raw_body_reads: AtomicUsize::new(0),
        });
        probe
            .inner
            .commit_session_snapshot(
                &runtime_id,
                SerializedSessionSnapshot {
                    session_snapshot: artifact.bytes_arc(),
                },
            )
            .await
            .expect("seed exact committed WholeBlob row");
        let authority = probe
            .inner
            .load_whole_blob_store_authority(&runtime_id)
            .await
            .expect("load seeded authority")
            .expect("seeded authority exists");
        let runtime_store: Arc<dyn RuntimeStore> = Arc::clone(&probe) as Arc<dyn RuntimeStore>;
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::new(MemoryStore::new()),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );

        service
            .acknowledge_whole_blob_runtime_session_boundary_under_runtime_turn_boundary(
                &session_id,
                authority.store_revision(),
                authority.blob_sha256(),
            )
            .await
            .expect("exact authority acknowledgement succeeds");

        assert_eq!(
            probe.bounded_authority_reads.load(Ordering::SeqCst),
            1,
            "ordinary acknowledgement must make one bounded authority read"
        );
        assert_eq!(
            probe.full_snapshot_reads.load(Ordering::SeqCst),
            0,
            "ordinary acknowledgement must not reload/hash/decode the WholeBlob body"
        );
    }

