    #[tokio::test]
    async fn test_persistent_rewrite_receipt_conflict_fails_closed_without_rollback() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );

        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create_session should succeed");
        let session_id = created.session_id;
        committed_content_turn(&service, runtime_store.as_ref(), &session_id, "hello").await;
        let parent_revision = service
            .load_authoritative_session(&session_id)
            .await
            .expect("load RuntimeStore authority before rewrite")
            .expect("session exists")
            .transcript_revision()
            .expect("parent revision");
        let rewrite = service
            .rewrite_session_transcript(
                &session_id,
                meerkat_core::SessionTranscriptRewriteRequest {
                    selection: TranscriptRewriteSelection::MessageRange { start: 1, end: 2 },
                    replacement: vec![Message::BlockAssistant(
                        meerkat_core::BlockAssistantMessage::new(
                            vec![meerkat_core::AssistantBlock::Text {
                                text: "receipt conflict target".to_string(),
                                meta: None,
                            }],
                            StopReason::EndTurn,
                        ),
                    )],
                    reason: TranscriptRewriteReason::new("compaction"),
                    actor: Some("audit-conflict-test".to_string()),
                    expected_parent_revision: Some(parent_revision),
                    running_behavior: TranscriptEditRunningBehavior::Reject,
                },
            )
            .await
            .expect("rewrite should commit without event projection");
        let committed = service
            .load_authoritative_session(&session_id)
            .await
            .expect("load committed RuntimeStore rewrite")
            .expect("committed rewrite exists");
        let commit = committed
            .validated_transcript_history_state()
            .expect("rewrite graph should decode")
            .expect("rewrite graph should exist")
            .last_commit()
            .expect("rewrite commit should exist")
            .clone();
        let receipt =
            transcript_rewrite_audit_receipt_for_commits(&committed, std::slice::from_ref(&commit))
                .expect("sealed graph should prepare the missing receipt");

        let event_store = Arc::new(RecordingEventStore::default());
        event_store
            .append_transcript_rewrite_receipt_exact(
                &session_id,
                &receipt,
                Some("forged conflicting terminal projection"),
            )
            .await
            .expect("conflicting durable occupant should be seeded");
        let event_store_trait: Arc<dyn EventStore> = event_store.clone();
        let dir = tempfile::tempdir().expect("tempdir");
        let recovery_service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        )
        .with_event_projection(
            event_store_trait,
            Arc::new(SessionProjector::new(dir.path().join(".rkat"))),
        );
        let error = recovery_service
            .read_history(&session_id, SessionHistoryQuery::default())
            .await
            .expect_err("conflicting receipt occupant must fail recovery closed");
        assert!(
            error
                .to_string()
                .contains("exact transcript rewrite receipt conflict"),
            "unexpected receipt conflict: {error}"
        );
        let repeated = recovery_service
            .load_authoritative_session(&session_id)
            .await
            .expect_err("the conflicting audit occupant must remain fail-closed");
        assert!(
            repeated
                .to_string()
                .contains("exact transcript rewrite receipt conflict"),
            "unexpected repeated receipt conflict: {repeated}"
        );
        let runtime_id =
            PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&session_id);
        let runtime = runtime_store
            .load_session_snapshot(&runtime_id)
            .await
            .expect("load retained runtime authority")
            .expect("runtime authority remains present");
        let runtime =
            Session::from_persisted_bytes(&runtime).expect("runtime authority should decode");
        assert_eq!(runtime.transcript_revision().unwrap(), rewrite.revision);
        assert_eq!(
            event_store.last_seq(&session_id).await.unwrap(),
            1,
            "conflict must neither overwrite nor duplicate the durable occupant"
        );
    }

    #[tokio::test]
    async fn test_persistent_archived_history_survives_restart_and_cache_eviction() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new_with_archived_history_capacity(
            DummyBuilder,
            1,
            1,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );
        let machine = MeerkatMachine::persistent(Arc::clone(&runtime_store), memory_blob_store())
            .expect("construct runtime authority");

        let first = service
            .create_session(create_request("first", InitialTurnPolicy::Defer))
            .await
            .expect("create first session");
        committed_content_turn(&service, runtime_store.as_ref(), &first.session_id, "first").await;
        service
            .archive_with_machine_protocol(
                &first.session_id,
                MachineSessionArchiveProtocol::from_machine(&machine),
            )
            .await
            .expect("archive first session");

        let second = service
            .create_session(create_request("second", InitialTurnPolicy::Defer))
            .await
            .expect("create second session");
        committed_content_turn(
            &service,
            runtime_store.as_ref(),
            &second.session_id,
            "second",
        )
        .await;
        service
            .archive_with_machine_protocol(
                &second.session_id,
                MachineSessionArchiveProtocol::from_machine(&machine),
            )
            .await
            .expect("archive second session");

        let restarted = PersistentSessionService::new_with_archived_history_capacity(
            DummyBuilder,
            1,
            1,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );
        let archived = restarted
            .read_history(
                &first.session_id,
                SessionHistoryQuery {
                    offset: 0,
                    limit: None,
                },
            )
            .await
            .expect("archived history should survive restart and cache eviction");
        assert_eq!(archived.session_id, first.session_id);
        assert_eq!(archived.message_count, 2);
        assert_eq!(archived.messages.len(), 2);

        let listed = restarted
            .list(SessionQuery::default())
            .await
            .expect("list sessions");
        assert!(
            listed.is_empty(),
            "archived sessions should remain hidden from list even when stored durably"
        );
    }

    #[tokio::test]
    async fn live_context_summary_snapshot_does_not_wait_for_active_turn_mutation_gates() {
        let mut builder = BlockingRunBuilder::new();
        builder.pending_context = Some("actor-only pending context".to_string());
        let service = Arc::new(PersistentSessionService::new(
            builder.clone(),
            4,
            Arc::new(MemoryStore::new()),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        ));
        let mut seed = recoverable_store_row();
        seed.push(Message::System(meerkat_core::types::SystemMessage::new(
            "committed instructions",
        )));
        seed.push(user_message("committed context"));
        let seed = service.save_normalized_session(seed).await.unwrap();
        let id = seed.id().clone();
        service.create_session(resume_request(seed)).await.unwrap();
        let (committed, committed_authority) = service
            .load_committed_runtime_session_with_authority(&id, "test source")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(committed_authority.session_id(), &id);
        let boundary = service
            .observe_live_context_committed_boundary(&id)
            .await
            .unwrap();
        assert_eq!(boundary.message_count(), committed.messages().len() as u64);
        assert_eq!(
            boundary.transcript_revision(),
            committed.transcript_revision().unwrap()
        );
        assert_eq!(
            boundary.rewrite_generation(),
            committed.transcript_rewrite_generation().unwrap()
        );

        let admission = service.reserve_runtime_turn_admission(&id).await.unwrap();
        let turn_service = Arc::clone(&service);
        let turn_id = id.clone();
        let active_turn = tokio::spawn(async move {
            let _boundary = turn_service
                .acquire_runtime_turn_finalization_guard(&turn_id)
                .await;
            turn_service
                .apply_runtime_turn_with_reserved_admission(
                    &turn_id,
                    RunId::new(),
                    runtime_content_turn_request("held turn"),
                    RunApplyBoundary::RunStart,
                    vec![InputId::new()],
                    admission,
                )
                .await
        });
        builder.wait_for_entered_runs(1).await;
        // The running actor has appended context beyond its committed base.
        // Capturing its export would wait and include uncommitted content.
        let recovery_gate = service.recovery_gate_for_session(&id).await;
        assert!(recovery_gate.try_lock().is_err());
        assert!(
            tokio::time::timeout(
                std::time::Duration::from_millis(25),
                service.export_realtime_refresh_session_snapshot(&id),
            )
            .await
            .is_err(),
            "the old refresh read must encounter the held mutation gate"
        );
        let (captured, identity) = tokio::time::timeout(
            std::time::Duration::from_secs(1),
            service.export_live_context_summary_snapshot(&id),
        )
        .await
        .expect("summary capture must not wait for the active turn")
        .unwrap();
        assert_eq!(
            serde_json::to_value(&captured).unwrap(),
            serde_json::to_value(&committed).unwrap()
        );
        assert_eq!(
            identity,
            committed.session_metadata().unwrap().llm_identity()
        );
        #[cfg(feature = "live")]
        {
            let (boundary, token) = tokio::time::timeout(
                std::time::Duration::from_secs(1),
                service.export_live_context_committed_boundary_nonblocking(&id),
            )
            .await
            .expect("mirror capture must not wait for the active turn")
            .unwrap();
            assert_eq!(
                serde_json::to_value(boundary.session().unwrap()).unwrap(),
                serde_json::to_value(&committed).unwrap()
            );
            assert_eq!(
                token,
                committed_authority.whole_blob().unwrap().blob_sha256()
            );
        }
        assert!(!active_turn.is_finished());
        builder.release_notify.add_permits(1);
        let output = active_turn.await.unwrap().unwrap();
        assert!(
            output
                .session()
                .unwrap()
                .messages()
                .iter()
                .any(|message| matches!(message, Message::System(system) if system.content == "actor-only pending context")),
            "the read must not synchronize away actor-local pending context"
        );
    }

    /// Builds a resumed live session and holds a runtime turn on it: the turn
    /// owns the turn boundary until `release_notify` gets a permit.
    async fn live_session_with_held_turn() -> (
        BlockingRunBuilder,
        Arc<PersistentSessionService<BlockingRunBuilder>>,
        SessionId,
        tokio::task::JoinHandle<Result<CoreApplyOutput, SessionError>>,
    ) {
        let builder = BlockingRunBuilder::with_durable_sync();
        let service = Arc::new(PersistentSessionService::new(
            builder.clone(),
            4,
            Arc::new(MemoryStore::new()),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        ));
        let seed = service
            .save_normalized_session(recoverable_store_row())
            .await
            .unwrap();
        let id = seed.id().clone();
        service.create_session(resume_request(seed)).await.unwrap();
        let admission = service.reserve_runtime_turn_admission(&id).await.unwrap();
        let turn_service = Arc::clone(&service);
        let turn_id = id.clone();
        let active_turn = tokio::spawn(async move {
            let _boundary = turn_service
                .acquire_runtime_turn_finalization_guard(&turn_id)
                .await;
            turn_service
                .apply_runtime_turn_with_reserved_admission(
                    &turn_id,
                    RunId::new(),
                    runtime_content_turn_request("held turn"),
                    RunApplyBoundary::RunStart,
                    vec![InputId::new()],
                    admission,
                )
                .await
        });
        builder.wait_for_entered_runs(1).await;
        (builder, service, id, active_turn)
    }

    /// With no turn in flight the non-waiting refresh snapshot is the ordinary
    /// refresh snapshot.
    #[tokio::test]
    async fn idle_non_waiting_refresh_snapshot_is_the_ordinary_snapshot() {
        let service = Arc::new(PersistentSessionService::new(
            BlockingRunBuilder::new(),
            4,
            Arc::new(MemoryStore::new()),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        ));
        let seed = service
            .save_normalized_session(recoverable_store_row())
            .await
            .unwrap();
        let id = seed.id().clone();
        service.create_session(resume_request(seed)).await.unwrap();
        let ordinary = service
            .export_realtime_refresh_session_snapshot(&id)
            .await
            .unwrap();
        let RealtimeRefreshSnapshot::Settled(settled) = service
            .export_realtime_refresh_session_snapshot_without_waiting_for_turn(&id)
            .await
            .unwrap()
        else {
            panic!("an idle session refreshes from the settled snapshot");
        };
        // Each live export stamps its own `updated_at`; everything else is equal.
        let shape = |session: &Session| {
            let mut value = serde_json::to_value(session).unwrap();
            value.as_object_mut().unwrap().remove("updated_at");
            value
        };
        assert_eq!(shape(&settled), shape(&ordinary));
    }

    /// A refresh on a member mid-turn reads the committed boundary at once and
    /// owes the durable resync; the resync is released by the turn boundary,
    /// not before it.
    #[tokio::test]
    async fn deferred_refresh_resync_runs_when_the_turn_finishes() {
        let (builder, service, id, active_turn) = live_session_with_held_turn().await;
        let committed = service
            .export_live_context_summary_snapshot(&id)
            .await
            .unwrap()
            .0;
        let RealtimeRefreshSnapshot::CommittedBoundary(boundary) = tokio::time::timeout(
            std::time::Duration::from_secs(1),
            service.export_realtime_refresh_session_snapshot_without_waiting_for_turn(&id),
        )
        .await
        .expect("the refresh snapshot must not wait for the active turn")
        .unwrap() else {
            panic!("a refresh mid-turn reads the committed boundary");
        };
        assert_eq!(
            serde_json::to_value(&boundary).unwrap(),
            serde_json::to_value(&committed).unwrap()
        );

        let channel = meerkat_core::LiveChannelId::new("refreshing-channel");
        let pending = service.defer_live_resync_to_turn_boundary(&id, &channel);
        assert_eq!(pending.session_id(), &id);
        let release_service = Arc::clone(&service);
        let mut release = tokio::spawn(async move {
            release_service
                .release_live_resync_at_turn_boundary(pending)
                .await
        });
        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(100), &mut release)
                .await
                .is_err(),
            "the resync waits for the turn boundary"
        );
        assert!(!active_turn.is_finished());
        assert_eq!(builder.durable_syncs(), 0, "nothing resynced mid-turn");

        builder.release_notify.add_permits(1);
        active_turn.await.unwrap().unwrap();
        let released = tokio::time::timeout(std::time::Duration::from_secs(5), release)
            .await
            .expect("the turn boundary releases the deferred resync")
            .unwrap()
            .unwrap();
        assert_eq!(released, LiveResyncRelease::Synchronized);
        assert_eq!(
            builder.durable_syncs(),
            1,
            "the released resync reconciled the live actor at the boundary"
        );
        service
            .export_realtime_refresh_session_snapshot(&id)
            .await
            .unwrap();
        assert_eq!(
            builder.durable_syncs(),
            1,
            "the deferred resync settled what the ordinary refresh would have; nothing is left"
        );
    }

    /// Closing the refreshing channel before the turn boundary releases the
    /// deferred resync at once, typed, without waiting out the turn.
    #[tokio::test]
    async fn deferred_refresh_resync_is_released_by_a_close_before_the_boundary() {
        let (builder, service, id, active_turn) = live_session_with_held_turn().await;
        let channel = meerkat_core::LiveChannelId::new("closing-refresh-channel");
        let pending = service.defer_live_resync_to_turn_boundary(&id, &channel);
        let release_service = Arc::clone(&service);
        let mut release = tokio::spawn(async move {
            release_service
                .release_live_resync_at_turn_boundary(pending)
                .await
        });
        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(100), &mut release)
                .await
                .is_err(),
            "the resync waits for the turn boundary"
        );

        service.release_live_projection_turn_boundary_waiters(&id, &channel);
        let released = tokio::time::timeout(std::time::Duration::from_secs(1), release)
            .await
            .expect("the close releases the deferred resync without the turn ending")
            .unwrap()
            .unwrap();
        assert_eq!(released, LiveResyncRelease::ChannelClosed);
        assert!(!active_turn.is_finished(), "the turn is still running");
        assert_eq!(
            builder.durable_syncs(),
            0,
            "a closed channel's resync never runs"
        );
        service.restore_live_projection_turn_boundary_wait(&id, &channel);

        builder.release_notify.add_permits(1);
        active_turn.await.unwrap().unwrap();
    }

    /// A member-status observation of a session mid-turn reads the watches
    /// the actor publishes, and so does the authority-arbitrating `read`: it
    /// compares against the transcript authority the session task published
    /// before the turn, never asking the busy task. The ordered observation
    /// (a command to the task, for export and commit callers that need it
    /// ordered after their own commands) still waits for the turn.
    #[tokio::test]
    async fn live_session_view_observation_does_not_wait_for_active_turn() {
        let builder = BlockingRunBuilder::new();
        let service = Arc::new(PersistentSessionService::new(
            builder.clone(),
            4,
            Arc::new(MemoryStore::new()),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        ));
        let seed = service
            .save_normalized_session(recoverable_store_row())
            .await
            .unwrap();
        let id = seed.id().clone();
        service.create_session(resume_request(seed)).await.unwrap();
        let idle_view = service
            .observe_live_session_view(&id)
            .await
            .unwrap()
            .expect("an idle live actor publishes its view");
        assert_eq!(idle_view.state.session_id, id);

        let admission = service.reserve_runtime_turn_admission(&id).await.unwrap();
        let turn_service = Arc::clone(&service);
        let turn_id = id.clone();
        let active_turn = tokio::spawn(async move {
            let _boundary = turn_service
                .acquire_runtime_turn_finalization_guard(&turn_id)
                .await;
            turn_service
                .apply_runtime_turn_with_reserved_admission(
                    &turn_id,
                    RunId::new(),
                    runtime_content_turn_request("held turn"),
                    RunApplyBoundary::RunStart,
                    vec![InputId::new()],
                    admission,
                )
                .await
        });
        builder.wait_for_entered_runs(1).await;
        let busy_read = tokio::time::timeout(
            std::time::Duration::from_secs(1),
            SessionService::read(service.as_ref(), &id),
        )
        .await
        .expect("the authority-arbitrating read must not wait for the active turn")
        .unwrap();
        assert_eq!(busy_read.state.session_id, id);
        assert!(
            tokio::time::timeout(
                std::time::Duration::from_millis(100),
                service.inner.observe_session_transcript_authority(&id),
            )
            .await
            .is_err(),
            "the ordered transcript-authority observation queues behind the running turn"
        );
        let busy_view = tokio::time::timeout(
            std::time::Duration::from_secs(1),
            service.observe_live_session_view(&id),
        )
        .await
        .expect("the status view must not wait for the active turn")
        .unwrap()
        .expect("the busy live actor still publishes its view");
        assert_eq!(busy_view.state.session_id, id);
        assert_eq!(
            busy_view.billing.total_tokens,
            idle_view.billing.total_tokens
        );
        assert!(
            service
                .observe_live_session_view(&SessionId::new())
                .await
                .unwrap()
                .is_none(),
            "no live actor is no live view"
        );

        builder.release_notify.add_permits(1);
        active_turn.await.unwrap().unwrap();
    }

    /// A resumed live session's status view is correct from the actor's
    /// birth. The summary watch was only published at turn end, durable sync
    /// and a few commands, so during the first turn after a resume (a
    /// deferred first turn, a fork child's first turn) the view reported no
    /// preview and zero tokens as if they were observations.
    #[tokio::test]
    async fn live_session_view_reports_resumed_history_during_first_turn() {
        let builder = BlockingRunBuilder::new();
        let service = Arc::new(PersistentSessionService::new(
            builder.clone(),
            4,
            Arc::new(MemoryStore::new()),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        ));
        let mut history = recoverable_store_row();
        history.push(meerkat_core::types::Message::User(
            meerkat_core::types::UserMessage::text("what is on the calendar"),
        ));
        history.push(meerkat_core::types::Message::BlockAssistant(
            meerkat_core::types::BlockAssistantMessage {
                blocks: vec![meerkat_core::types::AssistantBlock::Text {
                    text: "two meetings tomorrow".to_string(),
                    meta: None,
                }],
                stop_reason: Some(meerkat_core::types::StopReason::EndTurn),
                identity: meerkat_core::types::TranscriptMessageIdentity::default(),
                created_at: meerkat_core::types::message_timestamp_now(),
                assistant_message_id: None,
            },
        ));
        history.record_cumulative_usage(meerkat_core::types::Usage {
            input_tokens: 1200,
            output_tokens: 34,
            ..Default::default()
        });
        let seed = service.save_normalized_session(history).await.unwrap();
        let committed_tokens = seed.total_tokens();
        let committed_messages = seed.messages().len();
        assert_eq!(committed_tokens, 1234);
        let id = seed.id().clone();
        service.create_session(resume_request(seed)).await.unwrap();

        let idle_view = service
            .observe_live_session_view(&id)
            .await
            .unwrap()
            .expect("the resumed live actor publishes its view");
        assert_eq!(
            idle_view.state.last_assistant_text.as_deref(),
            Some("two meetings tomorrow"),
            "the resumed actor's view carries the committed preview before any turn"
        );
        assert_eq!(idle_view.billing.total_tokens, committed_tokens);
        assert_eq!(idle_view.state.message_count, committed_messages);

        let admission = service.reserve_runtime_turn_admission(&id).await.unwrap();
        let turn_service = Arc::clone(&service);
        let turn_id = id.clone();
        let first_turn = tokio::spawn(async move {
            let _boundary = turn_service
                .acquire_runtime_turn_finalization_guard(&turn_id)
                .await;
            turn_service
                .apply_runtime_turn_with_reserved_admission(
                    &turn_id,
                    RunId::new(),
                    runtime_content_turn_request("first turn after resume"),
                    RunApplyBoundary::RunStart,
                    vec![InputId::new()],
                    admission,
                )
                .await
        });
        builder.wait_for_entered_runs(1).await;
        let busy_view = tokio::time::timeout(
            std::time::Duration::from_secs(1),
            service.observe_live_session_view(&id),
        )
        .await
        .expect("the status view must not wait for the first turn")
        .unwrap()
        .expect("the busy resumed actor still publishes its view");
        assert_eq!(
            busy_view.state.last_assistant_text.as_deref(),
            Some("two meetings tomorrow"),
            "mid-first-turn the view reports the committed preview, not a silent none"
        );
        assert_eq!(
            busy_view.billing.total_tokens, committed_tokens,
            "mid-first-turn the view reports the committed token total, not a silent zero"
        );

        builder.release_notify.add_permits(1);
        first_turn.await.unwrap().unwrap();
    }

    #[cfg(not(target_arch = "wasm32"))]
    #[tokio::test]
    async fn realtime_open_presence_requires_a_live_actor_behind_the_registry_entry() {
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::new(MemoryStore::new()),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        );
        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .unwrap();
        let id = created.session_id;
        assert!(
            service
                .live_session_present_for_realtime_open(&id)
                .await
                .unwrap()
        );

        // The actor task exits while its registry entry remains. The registry
        // still names the session, but no actor could serve a minted channel;
        // the old actor-observing read failed such an open with "Session task
        // has exited", and this read must report absent instead.
        assert!(
            service
                .inner
                .abort_live_session_actor_task_for_test(&id)
                .await
        );
        assert!(
            meerkat_core::service::SessionService::has_live_session(service.inner.as_ref(), &id)
                .await
                .unwrap(),
            "the registry entry must survive for this test to prove anything"
        );
        assert!(
            service
                .inner
                .live_session_actor_witness(&id)
                .await
                .is_none(),
            "a closed command channel must retire the registry witness"
        );
        assert!(
            !service
                .live_session_present_for_realtime_open(&id)
                .await
                .unwrap(),
            "a registry entry without a live actor is not realtime-open presence"
        );
    }

    #[tokio::test]
    async fn live_context_committed_boundary_head_canonical_pins_head_row_to_materialized_transcript()
     {
        let directory = tempfile::Builder::new()
            .prefix(".committed-boundary-")
            .tempdir_in(".")
            .unwrap();
        let database_path = directory.path().join("runtime.sqlite3");
        let runtime_store = Arc::new(
            meerkat_runtime::SqliteRuntimeStore::new_head_canonical(&database_path).unwrap(),
        );
        let store = Arc::new(meerkat_store::SqliteSessionStore::open(&database_path).unwrap());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            store,
            runtime_store,
            memory_blob_store(),
        );
        let committed = service
            .persist_detached_head_canonical_session(
                live_context_summary_source(),
                "committed boundary fixture",
            )
            .await
            .unwrap();
        let id = committed.id().clone();
        let seeded_rows = committed.messages().len();
        assert!(seeded_rows > 2, "fixture must have rows to compact away");
        assert_head_canonical_boundary_matches_materialized_transcript(
            &service,
            &id,
            0,
            seeded_rows,
        )
        .await;

        // An adopted compaction rewrites the same session in place: the head
        // row must advance its rewrite count with the materialized generation
        // and re-digest exactly the surviving rows, or the body-free boundary
        // would admit a summary against rows that no longer exist.
        let mut compacted = committed.clone();
        let parent_revision = compacted.transcript_revision().unwrap();
        compacted
            .commit_transcript_rewrite(
                TranscriptRewriteSelection::MessageRange {
                    start: 1,
                    end: seeded_rows,
                },
                vec![Message::BlockAssistant(
                    meerkat_core::BlockAssistantMessage::new(
                        vec![meerkat_core::AssistantBlock::Text {
                            text: "compacted assistant trace".to_string(),
                            meta: None,
                        }],
                        StopReason::EndTurn,
                    ),
                )],
                TranscriptRewriteReason::new("compaction"),
                Some("test".to_string()),
                Some(parent_revision),
            )
            .unwrap();
        let compacted = service
            .persist_detached_head_canonical_session(compacted, "same-session transcript rewrite")
            .await
            .unwrap();
        assert_eq!(compacted.id(), &id);
        assert_eq!(compacted.messages().len(), 2);
        assert_head_canonical_boundary_matches_materialized_transcript(&service, &id, 1, 2).await;
    }

    /// The HeadCanonical head row is the body-free boundary the realtime open
    /// admits against; it must agree exactly with the materialized transcript
    /// it stands for, and the observed boundary must be that row verbatim.
    async fn assert_head_canonical_boundary_matches_materialized_transcript(
        service: &PersistentSessionService<DummyBuilder>,
        id: &SessionId,
        expected_generation: u64,
        expected_rows: usize,
    ) {
        let head = service
            .incremental
            .as_ref()
            .expect("head-canonical service has an incremental store")
            .load_head(id)
            .await
            .expect("load head row")
            .expect("head row exists");
        let materialized = service
            .load_committed_runtime_session_for_body(id, "committed boundary invariant")
            .await
            .unwrap()
            .expect("committed session materializes");
        assert_eq!(materialized.messages().len(), expected_rows);
        assert_eq!(head.message_count, expected_rows as u64);
        assert_eq!(
            materialized.transcript_rewrite_generation().unwrap(),
            expected_generation
        );
        assert_eq!(head.rewrite_count, expected_generation);
        assert_eq!(
            head.head_revision,
            materialized
                .transcript_prefix_digest(expected_rows)
                .unwrap()
        );
        let boundary = service
            .observe_live_context_committed_boundary(id)
            .await
            .unwrap();
        assert_eq!(boundary.message_count(), head.message_count);
        assert_eq!(boundary.transcript_revision(), head.head_revision);
        assert_eq!(boundary.rewrite_generation(), head.rewrite_count);
    }

    fn live_context_summary_source() -> Session {
        let mut session = recoverable_store_row();
        let mut metadata = session.session_metadata().unwrap();
        metadata.model = "gpt-5.5".to_string();
        metadata.provider = meerkat_core::Provider::OpenAI;
        metadata.self_hosted_server_id = Some("summary-source-server".to_string());
        metadata.provider_params = Some(
            meerkat_core::lifecycle::run_primitive::ProviderParamsOverride {
                max_output_tokens: Some(2048),
                ..Default::default()
            },
        );
        metadata.auth_binding = Some(meerkat_core::AuthBindingRef {
            realm: meerkat_core::RealmId::parse("summary-realm").unwrap(),
            binding: meerkat_core::connection::BindingId::parse("summary-binding").unwrap(),
            profile: Some(meerkat_core::connection::ProfileId::parse("summary-profile").unwrap()),
            origin: meerkat_core::connection::BindingOrigin::Configured,
        });
        session.set_session_metadata(metadata).unwrap();
        session.push(Message::System(meerkat_core::types::SystemMessage::new(
            "first instructions",
        )));
        session.push(user_message("older committed context"));
        session.push(Message::System(meerkat_core::types::SystemMessage::new(
            "later instructions",
        )));
        session.push(Message::User(UserMessage::with_blocks(vec![
            ContentBlock::Image {
                media_type: "image/png".to_string(),
                data: ImageData::Blob {
                    blob_id: meerkat_core::blob::content_blob_id("image/png", "not-stored"),
                },
            },
        ])));
        session
    }

    #[tokio::test]
    async fn live_context_summary_snapshot_pairs_exact_whole_blob_identity_without_hydration() {
        let store = Arc::new(MemoryStore::new());
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            store.clone(),
            runtime_store.clone(),
            memory_blob_store(),
        );
        let committed = service
            .save_normalized_session(live_context_summary_source())
            .await
            .unwrap();
        let id = committed.id().clone();
        let mut projection = committed.clone();
        let mut metadata = projection.session_metadata().unwrap();
        metadata.model = "different-projection-model".to_string();
        projection.set_session_metadata(metadata).unwrap();
        store.save(&projection).await.unwrap();

        let checkpointer = StoreCheckpointer {
            runtime_store: runtime_store.clone(),
            incremental: service.incremental.clone(),
            blob_store: memory_blob_store(),
            gate: Arc::new(CheckpointerGate {
                cancelled: Mutex::new(false),
            }),
            whole_blob_base_authority: std::sync::Mutex::new(
                runtime_store
                    .load_whole_blob_store_authority(&LogicalRuntimeId::for_session(&id))
                    .await
                    .unwrap(),
            ),
            latest_run_checkpoint_receipt: Mutex::new(None),
            latest_run_transcript_retirement: std::sync::Mutex::new(None),
            live_deferred_turn_state: std::sync::OnceLock::new(),
            unattached_deferred_checkpoint_warned: std::sync::atomic::AtomicBool::new(false),
            rebased_run: std::sync::Mutex::new(None),
            latest_run_checkpoint_cursor: std::sync::Mutex::new(None),
            rebase_outcome_unknown: std::sync::Mutex::new(None),
            rewrite_audit: None,
        };
        let mut provisional = committed.clone();
        provisional.push(user_message("provisional context is not committed"));
        meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut provisional,
            &RunId::new(),
            None,
        )
        .await
        .unwrap()
        .expect("store-issued provisional receipt");

        let (captured, identity) = service
            .export_live_context_summary_snapshot(&id)
            .await
            .unwrap();
        assert_eq!(
            serde_json::to_value(&captured).unwrap(),
            serde_json::to_value(&committed).unwrap()
        );
        assert_eq!(
            identity,
            committed.session_metadata().unwrap().llm_identity()
        );
        assert_ne!(
            identity,
            projection.session_metadata().unwrap().llm_identity()
        );
        assert!(
            runtime_store
                .load_whole_blob_provisional_tail(&LogicalRuntimeId::for_session(&id))
                .await
                .unwrap()
                .is_some(),
            "a summary read must not recover or discard provisional work"
        );
    }

    /// Review finding C: the pairing guarantee also holds on a cache hit. A
    /// commit that races in after the verified body was cached changes the
    /// authority, so the next export never pairs the stale cached body with
    /// either token; it takes the authoritative read of the new document.
    #[tokio::test]
    #[cfg(feature = "live")]
    async fn live_context_boundary_cache_hit_never_pairs_a_raced_commit() {
        let runtime_store = Arc::new(GatedSnapshotRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::new(MemoryStore::new()),
            runtime_store.clone(),
            memory_blob_store(),
        );
        let committed = service
            .save_normalized_session(live_context_summary_source())
            .await
            .unwrap();
        let id = committed.id().clone();
        let runtime_id = LogicalRuntimeId::for_session(&id);

        // An authoritative read fills the verified-body cache.
        let (boundary, token) = service
            .export_live_context_committed_boundary_nonblocking(&id)
            .await
            .unwrap();
        assert_eq!(
            serde_json::to_value(boundary.session().unwrap()).unwrap(),
            serde_json::to_value(&committed).unwrap()
        );
        let first_authority = runtime_store
            .load_whole_blob_store_authority(&runtime_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(token, first_authority.blob_sha256());
        assert!(
            service.cached_whole_blob_body(&id).is_some(),
            "the export cached the verified body"
        );

        // A commit races in behind the cached body.
        let mut successor = committed.clone();
        successor.push(user_message("committed behind the cached body"));
        runtime_store
            .commit_session_snapshot(
                &runtime_id,
                SerializedSessionSnapshot {
                    session_snapshot: serde_json::to_vec(&successor).unwrap().into(),
                },
            )
            .await
            .unwrap();
        let successor_authority = runtime_store
            .load_whole_blob_store_authority(&runtime_id)
            .await
            .unwrap()
            .unwrap();
        assert_ne!(successor_authority, first_authority);

        let (boundary, token) = service
            .export_live_context_committed_boundary_nonblocking(&id)
            .await
            .unwrap();
        assert_eq!(
            token,
            successor_authority.blob_sha256(),
            "the token names the document that is committed now"
        );
        assert_eq!(
            serde_json::to_value(boundary.session().unwrap()).unwrap(),
            serde_json::to_value(&successor).unwrap(),
            "and the boundary is that same document, never the stale cached body"
        );
    }

    #[tokio::test]
    #[cfg(feature = "live")]
    async fn live_context_summary_snapshot_and_boundary_keep_pairing_when_store_advances() {
        let runtime_store = Arc::new(GatedSnapshotRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::new(MemoryStore::new()),
            runtime_store.clone(),
            memory_blob_store(),
        );
        let committed = service
            .save_normalized_session(live_context_summary_source())
            .await
            .unwrap();
        let id = committed.id().clone();
        let runtime_id = LogicalRuntimeId::for_session(&id);
        let initial_authority = runtime_store
            .load_whole_blob_store_authority(&runtime_id)
            .await
            .unwrap()
            .unwrap();
        let mut successor = committed.clone();
        successor.push(user_message("committed after the sampled snapshot"));
        let mut metadata = successor.session_metadata().unwrap();
        metadata.model = "successor-identity".to_string();
        successor.set_session_metadata(metadata).unwrap();
        runtime_store.snapshot_read_interlopers.lock().await.insert(
            runtime_id.clone(),
            SerializedSessionSnapshot {
                session_snapshot: serde_json::to_vec(&successor).unwrap().into(),
            },
        );
        // A save caches nothing, so this export takes the authoritative read
        // the interloper races.
        assert!(service.cached_whole_blob_body(&id).is_none());
        let (boundary, token) = service
            .export_live_context_committed_boundary_nonblocking(&id)
            .await
            .unwrap();
        assert_eq!(
            serde_json::to_value(boundary.session().unwrap()).unwrap(),
            serde_json::to_value(&committed).unwrap()
        );
        assert_eq!(token, initial_authority.blob_sha256());
        let successor_authority = runtime_store
            .load_whole_blob_store_authority(&runtime_id)
            .await
            .unwrap()
            .unwrap();
        assert_ne!(token, successor_authority.blob_sha256());

        let mut next = successor.clone();
        let mut metadata = next.session_metadata().unwrap();
        metadata.model = "next-identity".to_string();
        next.set_session_metadata(metadata).unwrap();
        runtime_store.snapshot_read_interlopers.lock().await.insert(
            runtime_id,
            SerializedSessionSnapshot {
                session_snapshot: serde_json::to_vec(&next).unwrap().into(),
            },
        );
        // No forget here: the body cached by the export above belongs to the
        // pre-successor authority, so a fresh authority observation no longer
        // equals it and the read falls back to the authoritative snapshot.
        let (captured, identity) = service
            .export_live_context_summary_snapshot(&id)
            .await
            .unwrap();
        assert_eq!(
            serde_json::to_value(&captured).unwrap(),
            serde_json::to_value(&successor).unwrap()
        );
        assert_eq!(
            identity,
            successor.session_metadata().unwrap().llm_identity()
        );
        assert_ne!(identity, next.session_metadata().unwrap().llm_identity());
    }

