    /// A HeadCanonical pair with a committed turn-start head for a session
    /// whose transcript the compaction cycles below can rewrite, and the
    /// actor checkpointer over it.
    async fn retention_checkpoint_fixture() -> (
        tempfile::TempDir,
        PersistentSessionService<DummyBuilder>,
        StoreCheckpointer,
        Session,
    ) {
        let directory = tempfile::Builder::new()
            .prefix(".retention-checkpoint-")
            .tempdir_in(".")
            .unwrap();
        let database_path = directory.path().join("runtime.sqlite3");
        let runtime_store = Arc::new(
            meerkat_runtime::SqliteRuntimeStore::new_head_canonical(&database_path).unwrap(),
        );
        let store = Arc::new(meerkat_store::SqliteSessionStore::open(&database_path).unwrap());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            store,
            runtime_store.clone(),
            memory_blob_store(),
        );
        let committed = service
            .persist_detached_head_canonical_session(
                live_context_summary_source(),
                "turn-start head",
            )
            .await
            .unwrap();
        let checkpointer = StoreCheckpointer {
            runtime_store,
            incremental: service.incremental.clone(),
            blob_store: memory_blob_store(),
            gate: Arc::new(CheckpointerGate {
                cancelled: Mutex::new(false),
            }),
            whole_blob_base_authority: std::sync::Mutex::new(None),
            latest_run_checkpoint_receipt: Mutex::new(None),
            latest_run_transcript_retirement: std::sync::Mutex::new(None),
            live_deferred_turn_state: std::sync::OnceLock::new(),
            unattached_deferred_checkpoint_warned: std::sync::atomic::AtomicBool::new(false),
            rebased_run: std::sync::Mutex::new(None),
            latest_run_checkpoint_cursor: std::sync::Mutex::new(None),
            rebase_outcome_unknown: std::sync::Mutex::new(None),
            rewrite_audit: None,
        };
        (directory, service, checkpointer, committed)
    }

    /// One compaction of a long turn: a few rows, then, as the agent does on
    /// a clone of its session it installs afterwards, a rewrite of everything
    /// after the first row down to a summary and the retirement it applies
    /// after every compaction rewrite.
    fn compact_and_retire(
        session: &mut Session,
        compaction: usize,
        retention: meerkat_core::TranscriptHistoryRetention,
    ) {
        for row in 0..3 {
            session.push(user_message(&format!("compaction {compaction} row {row}")));
        }
        let mut compacted = session.clone();
        let end = compacted.messages().len();
        let parent_revision = compacted.transcript_revision().unwrap();
        compacted
            .commit_transcript_rewrite(
                TranscriptRewriteSelection::MessageRange { start: 1, end },
                vec![Message::BlockAssistant(
                    meerkat_core::BlockAssistantMessage::new(
                        vec![meerkat_core::AssistantBlock::Text {
                            text: format!("summary of compaction {compaction}"),
                            meta: None,
                        }],
                        StopReason::EndTurn,
                    ),
                )],
                TranscriptRewriteReason::new("compaction"),
                Some("test".to_string()),
                Some(parent_revision),
            )
            .unwrap();
        compacted.retire_transcript_history(retention).unwrap();
        *session = compacted;
    }

    fn retired_rewrites(session: &Session) -> usize {
        session
            .transcript_history_state()
            .unwrap()
            .expect("rewrite graph")
            .retired_count()
    }

    async fn physical_rewrite_count(
        service: &PersistentSessionService<DummyBuilder>,
        id: &SessionId,
    ) -> u64 {
        service
            .incremental
            .as_ref()
            .unwrap()
            .load_head(id)
            .await
            .unwrap()
            .unwrap()
            .rewrite_count
    }

    /// One long turn compacts more often than the history retention keeps
    /// (six compactions at four retained rewrites) before its intra-turn
    /// checkpoint: the agent checkpoints at the end of a run, not between its
    /// compactions. The checkpoint persists the pending rewrite suffix from
    /// the physical head the turn started on, so retirement keeps the
    /// occurrences that head does not cover yet, and catches up once a
    /// checkpoint has covered them.
    #[tokio::test]
    async fn intra_turn_checkpoint_after_more_compactions_than_retained_rewrites() {
        let (_directory, service, checkpointer, committed) = retention_checkpoint_fixture().await;
        let id = committed.id().clone();
        let retention = meerkat_core::TranscriptHistoryRetention::from_count(4).unwrap();
        let mut session = committed;
        for compaction in 0..6 {
            compact_and_retire(&mut session, compaction, retention);
        }

        let run_id = RunId::new();
        let receipt = meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut session,
            &run_id,
            None,
        )
        .await
        .expect("the intra-turn checkpoint persists every compaction of the turn")
        .expect("the checkpoint writes a provisional successor");
        assert_eq!(physical_rewrite_count(&service, &id).await, 6);
        assert_eq!(
            retired_rewrites(&session),
            0,
            "nothing the turn-start head lacked was retired"
        );

        // The head now covers all six: the next compaction retires down to
        // the retention again, and the next checkpoint still proves its
        // suffix.
        compact_and_retire(&mut session, 6, retention);
        assert_eq!(retired_rewrites(&session), 3);
        meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut session,
            &run_id,
            Some(&receipt),
        )
        .await
        .expect("the next checkpoint proves its suffix after the catch-up")
        .expect("the checkpoint writes the next provisional successor");
        assert_eq!(physical_rewrite_count(&service, &id).await, 7);
    }

    /// When a checkpoint follows every compaction, the durable head keeps up
    /// and retirement keeps the graph at the retention bound.
    #[tokio::test]
    async fn checkpoints_after_every_compaction_keep_the_retention_bound() {
        let (_directory, service, checkpointer, committed) = retention_checkpoint_fixture().await;
        let id = committed.id().clone();
        let retention = meerkat_core::TranscriptHistoryRetention::from_count(4).unwrap();
        let mut session = committed;
        let run_id = RunId::new();
        let mut previous = None;
        for compaction in 0..6 {
            compact_and_retire(&mut session, compaction, retention);
            assert_eq!(
                retired_rewrites(&session),
                (compaction + 1).saturating_sub(4)
            );
            previous = Some(
                meerkat_core::SessionCheckpointer::checkpoint_run(
                    &checkpointer,
                    &mut session,
                    &run_id,
                    previous.as_ref(),
                )
                .await
                .expect("every checkpoint proves its suffix")
                .expect("every checkpoint writes a provisional successor"),
            );
        }
        assert_eq!(physical_rewrite_count(&service, &id).await, 6);
        assert_eq!(retired_rewrites(&session), 2);
    }

    /// The anchor floor of a stored head: the oldest rewrite generation its
    /// cold materialization replays rows from.
    fn anchor_floor(head: &meerkat_core::session_store::SessionHead) -> u64 {
        head.row_lineage_anchor.as_ref().map_or(
            0,
            meerkat_core::session_store::SessionRowLineageAnchor::rewrite_count,
        )
    }

    /// The committed boundary's head and the session a cold host rebuilds
    /// from it: a host that restarted materializes the boundary from the
    /// rows the store kept.
    async fn rebuild_committed_boundary(
        directory: &std::path::Path,
        id: &SessionId,
    ) -> (meerkat_core::session_store::SessionHead, Session) {
        let restarted = reopen_retention_fixture(directory);
        let authority = restarted
            .runtime_store
            .load_session_boundary_authority(&LogicalRuntimeId::for_session(id))
            .await
            .unwrap()
            .expect("committed boundary authority");
        let head = authority
            .head_canonical()
            .expect("HeadCanonical boundary")
            .boundary_head()
            .clone();
        let session = restarted
            .load_committed_runtime_session_for_body(id, "cold boundary rebuild")
            .await
            .expect("the committed boundary rebuilds from the rows the store kept")
            .expect("committed boundary session");
        (head, session)
    }

    /// The committed boundary a cold host's recovery rebuilds while a crash
    /// tail sits on top of it: the store replays the boundary from its own
    /// anchor over the rows it kept, so this fails once a cut removed rows,
    /// or strands, the boundary needs.
    async fn boundary_rebuilt_for_recovery(
        directory: &std::path::Path,
        id: &SessionId,
    ) -> meerkat_core::session_store::SessionHead {
        let restarted = reopen_retention_fixture(directory);
        let runtime_id = LogicalRuntimeId::for_session(id);
        assert!(
            restarted
                .runtime_store
                .load_durable_tail_recovery_source(&runtime_id)
                .await
                .expect("the committed boundary rebuilds from the rows the store kept")
                .is_some(),
            "a durable tail awaits recovery"
        );
        restarted
            .runtime_store
            .load_session_boundary_authority(&runtime_id)
            .await
            .unwrap()
            .expect("committed boundary authority")
            .head_canonical()
            .expect("HeadCanonical boundary")
            .boundary_head()
            .clone()
    }

    /// One long run: more compactions than the retention keeps, a
    /// checkpoint, another compaction that retires rewrites in memory once the
    /// durable head covers them, then the run's own tool call and results and
    /// a second checkpoint. The host dies before the boundary commit. The
    /// checkpoints pruned no rewrite rows, so the committed boundary (at
    /// generation 0) still rebuilds, and recovery closes the run as
    /// interrupted from it. The recovery prunes nothing either.
    #[tokio::test]
    async fn a_run_that_retired_rewrites_between_its_checkpoints_recovers_from_its_boundary() {
        let (directory, service, checkpointer, committed) = retention_checkpoint_fixture().await;
        let id = committed.id().clone();
        let boundary_messages = committed.messages().len();
        let retention = meerkat_core::TranscriptHistoryRetention::from_count(4).unwrap();
        let mut session = committed;
        for compaction in 0..6 {
            compact_and_retire(&mut session, compaction, retention);
        }
        let run_id = RunId::new();
        let receipt = meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut session,
            &run_id,
            None,
        )
        .await
        .expect("the first checkpoint persists six compactions")
        .expect("a provisional successor");
        compact_and_retire(&mut session, 6, retention);
        assert_eq!(
            retired_rewrites(&session),
            3,
            "the durable head covers six rewrites, so memory retires three"
        );
        interrupted_after_compaction(&mut session, &run_id);
        meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut session,
            &run_id,
            Some(&receipt),
        )
        .await
        .expect("the second checkpoint")
        .expect("the next provisional successor");
        assert_eq!(physical_rewrite_count(&service, &id).await, 7);
        drop(service);

        let boundary_head = boundary_rebuilt_for_recovery(directory.path(), &id).await;
        assert_eq!(boundary_head.rewrite_count, 0);
        assert_eq!(boundary_head.message_count, boundary_messages as u64);

        let restarted = reopen_retention_fixture(directory.path());
        let recovery = restarted
            .recover_committed_boundary(&id)
            .await
            .expect("the run's crash tail is recoverable from its boundary");
        assert!(
            matches!(
                recovery,
                CommittedBoundaryRecovery::Recovered { message_count }
                    if message_count == session.messages().len() + 1
            ),
            "every durable row plus the recovery notice: {recovery:?}"
        );
        drop(restarted);
        let (recovered_head, recovered) = rebuild_committed_boundary(directory.path(), &id).await;
        assert_eq!(recovered_head.rewrite_count, 7);
        assert!(
            matches!(recovered.messages().last(), Some(Message::SystemNotice(_))),
            "the interrupted run ends with the typed recovery notice"
        );
        let graph = recovered
            .transcript_history_state()
            .unwrap()
            .expect("the recovered graph");
        assert_eq!(
            graph.retired_count(),
            0,
            "a recovery promotion carries no retention cut"
        );
    }

    /// The same run over a committed boundary that was itself compacted past
    /// the retention, so its anchor floor sits below its rewrite count. The
    /// run's checkpoints retire rewrites in memory beyond that floor; had they
    /// pruned the store to the live cut (or to anything above the boundary's
    /// anchor floor), the boundary could no longer rebuild. It does, and
    /// recovery closes the run as interrupted from it.
    #[tokio::test]
    async fn a_run_over_a_boundary_compacted_past_its_retention_recovers_from_it() {
        let (directory, service, checkpointer, committed) = retention_checkpoint_fixture().await;
        let id = committed.id().clone();
        let retention = meerkat_core::TranscriptHistoryRetention::from_count(4).unwrap();
        let mut session = committed;
        for compaction in 0..6 {
            compact_and_retire(&mut session, compaction, retention);
        }
        let mut session = service
            .persist_detached_head_canonical_session(session, "the boundary")
            .await
            .expect("an earlier run commits six compactions as the boundary");
        let incremental = service.incremental.as_ref().unwrap();
        let boundary_at_commit = incremental
            .load_head(&id)
            .await
            .unwrap()
            .expect("boundary head");
        let boundary_floor = anchor_floor(&boundary_at_commit);
        assert!(
            boundary_floor < boundary_at_commit.rewrite_count,
            "the boundary's anchor floor ({boundary_floor}) must sit below its rewrite count ({})",
            boundary_at_commit.rewrite_count
        );

        let run_id = RunId::new();
        compact_and_retire(&mut session, 6, retention);
        assert!(
            retired_rewrites(&session) as u64 > boundary_floor,
            "the run retires past the boundary's anchor floor in memory"
        );
        let receipt = meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut session,
            &run_id,
            None,
        )
        .await
        .expect("the run's first checkpoint")
        .expect("a provisional successor");
        compact_and_retire(&mut session, 7, retention);
        interrupted_after_compaction(&mut session, &run_id);
        meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut session,
            &run_id,
            Some(&receipt),
        )
        .await
        .expect("the run's second checkpoint")
        .expect("the next provisional successor");
        drop(service);

        let boundary_head = boundary_rebuilt_for_recovery(directory.path(), &id).await;
        assert_eq!(boundary_head, boundary_at_commit);

        let restarted = reopen_retention_fixture(directory.path());
        let recovery = restarted
            .recover_committed_boundary(&id)
            .await
            .expect("the run's crash tail is recoverable from its boundary");
        assert!(
            matches!(
                recovery,
                CommittedBoundaryRecovery::Recovered { message_count }
                    if message_count == session.messages().len() + 1
            ),
            "every durable row plus the recovery notice: {recovery:?}"
        );
    }

    /// The runtime boundary commit that promotes a run's provisional chain,
    /// built as the runtime driver builds it from the run's last checkpoint
    /// receipt, carrying `deferred` as the run's retention cut.
    fn promotion_commit(
        checkpoint: &meerkat_core::RunCheckpointReceipt,
        run_id: &RunId,
        id: &SessionId,
        deferred: Option<u64>,
    ) -> meerkat_runtime::store::PreparedRuntimeSessionCommit {
        let receipt = meerkat_core::lifecycle::RunBoundaryReceipt {
            run_id: run_id.clone(),
            boundary: RunApplyBoundary::Immediate,
            contributing_input_ids: Vec::new(),
            conversation_digest: Some(checkpoint.conversation_digest().to_string()),
            message_count: usize::try_from(checkpoint.message_count()).unwrap(),
            sequence: 1,
            owner_contributions: Vec::new(),
        };
        meerkat_runtime::store::PreparedRuntimeSessionCommit::promote_head_canonical_success(
            meerkat_runtime::store::PreparedHeadCanonicalProvisionalPromotion::prepare(
                checkpoint.clone(),
                run_id,
            )
            .unwrap()
            .with_deferred_transcript_retirement(deferred),
            receipt,
            Vec::new(),
            id.clone(),
        )
        .unwrap()
    }

    /// The retention cut the store holds for `head`'s session, as a cold
    /// materialization of that exact head reads it.
    async fn stored_retention_cut(
        service: &PersistentSessionService<DummyBuilder>,
        head: &meerkat_core::session_store::SessionHead,
    ) -> usize {
        service
            .incremental
            .as_ref()
            .unwrap()
            .materialize_head(head)
            .await
            .expect("the head materializes from the rows the store kept")
            .session()
            .transcript_history_state()
            .unwrap()
            .expect("a rewritten head materializes its graph")
            .retired_count()
    }

    /// A run whose checkpoints left more rewrites than the retention keeps:
    /// six compactions, a checkpoint, a seventh compaction that retires three
    /// in memory, the run's answer and its last checkpoint. Returns the run,
    /// its last checkpoint receipt, its live cut and the physical head.
    async fn run_with_a_deferred_cut(
        service: &PersistentSessionService<DummyBuilder>,
        checkpointer: &StoreCheckpointer,
        committed: Session,
    ) -> (
        RunId,
        meerkat_core::RunCheckpointReceipt,
        u64,
        meerkat_core::session_store::SessionHead,
    ) {
        let id = committed.id().clone();
        let retention = meerkat_core::TranscriptHistoryRetention::from_count(4).unwrap();
        let mut session = committed;
        for compaction in 0..6 {
            compact_and_retire(&mut session, compaction, retention);
        }
        let run_id = RunId::new();
        let first = meerkat_core::SessionCheckpointer::checkpoint_run(
            checkpointer,
            &mut session,
            &run_id,
            None,
        )
        .await
        .expect("the first checkpoint")
        .expect("a provisional successor");
        compact_and_retire(&mut session, 6, retention);
        let live_cut = retired_rewrites(&session) as u64;
        completed_after_compaction(&mut session, &run_id);
        let last = meerkat_core::SessionCheckpointer::checkpoint_run(
            checkpointer,
            &mut session,
            &run_id,
            Some(&first),
        )
        .await
        .expect("the last checkpoint")
        .expect("the next provisional successor");
        let physical = service
            .incremental
            .as_ref()
            .unwrap()
            .load_head(&id)
            .await
            .unwrap()
            .expect("physical head");
        (run_id, last, live_cut, physical)
    }

    /// The run's checkpoints prune no rewrite rows. The boundary commit that
    /// promotes the run applies the run's retention cut in its own
    /// transaction, once: a retried promotion cuts nothing more.
    #[tokio::test]
    async fn the_promotion_applies_the_runs_deferred_retention_cut_once() {
        let (_directory, service, checkpointer, committed) = retention_checkpoint_fixture().await;
        let id = committed.id().clone();
        let (run_id, last, live_cut, physical) =
            run_with_a_deferred_cut(&service, &checkpointer, committed).await;
        assert_eq!(live_cut, 3);
        assert_eq!(
            stored_retention_cut(&service, &physical).await,
            0,
            "the run's checkpoints pruned no rewrite rows"
        );
        let expected = live_cut
            .min(anchor_floor(&physical))
            .min(physical.rewrite_count - 1);
        assert!(
            expected > 0,
            "the promoted head admits a cut: live {live_cut}, anchor floor {}",
            anchor_floor(&physical)
        );

        let runtime_id = LogicalRuntimeId::for_session(&id);
        let applied = checkpointer
            .runtime_store
            .commit_prepared_session_boundary(
                &runtime_id,
                promotion_commit(&last, &run_id, &id, Some(live_cut)),
            )
            .await
            .expect("the promotion commits");
        assert_eq!(
            applied.outcome(),
            meerkat_runtime::store::PreparedRuntimeSessionCommitOutcome::Applied
        );
        assert_eq!(
            stored_retention_cut(&service, &physical).await as u64,
            expected,
            "the promotion applies the run's cut"
        );

        let retried = checkpointer
            .runtime_store
            .commit_prepared_session_boundary(
                &runtime_id,
                promotion_commit(&last, &run_id, &id, Some(live_cut)),
            )
            .await
            .expect("an exact retry converges");
        assert_eq!(
            retried.outcome(),
            meerkat_runtime::store::PreparedRuntimeSessionCommitOutcome::AlreadyAppliedExact
        );
        assert_eq!(
            stored_retention_cut(&service, &physical).await as u64,
            expected,
            "a retried promotion cuts nothing more"
        );
    }

    /// The cut a promotion carries comes from the live session, not the
    /// store. Even an over-large one stops at the promoted head's anchor
    /// floor (and below its rewrite count), so it cannot strand the new
    /// boundary.
    #[tokio::test]
    async fn an_over_large_deferred_cut_stops_at_the_promoted_heads_anchor_floor() {
        let (directory, service, checkpointer, committed) = retention_checkpoint_fixture().await;
        let id = committed.id().clone();
        let (run_id, last, _live_cut, physical) =
            run_with_a_deferred_cut(&service, &checkpointer, committed).await;
        checkpointer
            .runtime_store
            .commit_prepared_session_boundary(
                &LogicalRuntimeId::for_session(&id),
                promotion_commit(&last, &run_id, &id, Some(u64::MAX)),
            )
            .await
            .expect("the promotion commits");
        assert_eq!(
            stored_retention_cut(&service, &physical).await as u64,
            anchor_floor(&physical).min(physical.rewrite_count - 1)
        );
        drop(service);
        let (boundary_head, _boundary) = rebuild_committed_boundary(directory.path(), &id).await;
        assert_eq!(
            boundary_head, physical,
            "the promoted head is the new boundary"
        );
    }

    /// After a recovery, which cuts nothing, the next run's checkpoints still
    /// prune no rewrite rows, and the cut its promotion applies stays at the
    /// new boundary's anchor floor or below.
    #[tokio::test]
    async fn after_a_recovery_the_next_run_prunes_only_at_its_promotion() {
        let (directory, service, checkpointer, committed) = retention_checkpoint_fixture().await;
        let id = committed.id().clone();
        let retention = meerkat_core::TranscriptHistoryRetention::from_count(4).unwrap();
        let mut session = committed;
        for compaction in 0..6 {
            compact_and_retire(&mut session, compaction, retention);
        }
        let crashed_run = RunId::new();
        interrupted_after_compaction(&mut session, &crashed_run);
        meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut session,
            &crashed_run,
            None,
        )
        .await
        .expect("the crashed run's checkpoint")
        .expect("a provisional successor");
        drop(checkpointer);
        drop(service);

        let restarted = reopen_retention_fixture(directory.path());
        let recovery = restarted
            .recover_committed_boundary(&id)
            .await
            .expect("the crashed run recovers");
        assert!(
            matches!(recovery, CommittedBoundaryRecovery::Recovered { .. }),
            "{recovery:?}"
        );
        let recovered = restarted
            .load_committed_runtime_session_for_body(&id, "after recovery")
            .await
            .unwrap()
            .expect("the recovered boundary");
        let recovered_head = restarted
            .incremental
            .as_ref()
            .unwrap()
            .load_head(&id)
            .await
            .unwrap()
            .expect("the recovered head");
        assert_eq!(
            stored_retention_cut(&restarted, &recovered_head).await,
            0,
            "the recovery prunes no rewrite rows"
        );

        let checkpointer = StoreCheckpointer {
            runtime_store: restarted.runtime_store.clone(),
            incremental: restarted.incremental.clone(),
            blob_store: memory_blob_store(),
            gate: Arc::new(CheckpointerGate {
                cancelled: Mutex::new(false),
            }),
            whole_blob_base_authority: std::sync::Mutex::new(None),
            latest_run_checkpoint_receipt: Mutex::new(None),
            latest_run_transcript_retirement: std::sync::Mutex::new(None),
            live_deferred_turn_state: std::sync::OnceLock::new(),
            unattached_deferred_checkpoint_warned: std::sync::atomic::AtomicBool::new(false),
            rebased_run: std::sync::Mutex::new(None),
            latest_run_checkpoint_cursor: std::sync::Mutex::new(None),
            rebase_outcome_unknown: std::sync::Mutex::new(None),
            rewrite_audit: None,
        };
        let mut session = recovered;
        let run_id = RunId::new();
        compact_and_retire(&mut session, 6, retention);
        let live_cut = retired_rewrites(&session) as u64;
        assert!(live_cut > 0, "the next run retires in memory");
        completed_after_compaction(&mut session, &run_id);
        let last = meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut session,
            &run_id,
            None,
        )
        .await
        .expect("the next run's checkpoint")
        .expect("a provisional successor");
        let physical = restarted
            .incremental
            .as_ref()
            .unwrap()
            .load_head(&id)
            .await
            .unwrap()
            .expect("the next run's physical head");
        assert_eq!(
            stored_retention_cut(&restarted, &physical).await,
            0,
            "the next run's checkpoint prunes no rewrite rows"
        );

        checkpointer
            .runtime_store
            .commit_prepared_session_boundary(
                &LogicalRuntimeId::for_session(&id),
                promotion_commit(&last, &run_id, &id, Some(live_cut)),
            )
            .await
            .expect("the next run's promotion commits");
        let cut = stored_retention_cut(&restarted, &physical).await as u64;
        assert!(cut > 0, "the promotion applies the next run's cut");
        assert!(
            cut <= anchor_floor(&physical),
            "the cut {cut} stays at or below the new boundary's anchor floor {}",
            anchor_floor(&physical)
        );
    }

    /// Retirement goes exactly as far as the durable head and no further:
    /// with the head at four rewrites, the eighth compaction retires the
    /// first four, and the ninth, which the retention alone would let retire
    /// a fifth, keeps it until a checkpoint covers it.
    #[tokio::test]
    async fn retirement_reaches_the_durable_head_and_stops_there() {
        let (_directory, service, checkpointer, committed) = retention_checkpoint_fixture().await;
        let id = committed.id().clone();
        let retention = meerkat_core::TranscriptHistoryRetention::from_count(4).unwrap();
        let mut session = committed;
        for compaction in 0..4 {
            compact_and_retire(&mut session, compaction, retention);
        }
        let run_id = RunId::new();
        let receipt = meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut session,
            &run_id,
            None,
        )
        .await
        .expect("the checkpoint after four compactions")
        .expect("a provisional successor");
        assert_eq!(physical_rewrite_count(&service, &id).await, 4);

        for compaction in 4..8 {
            compact_and_retire(&mut session, compaction, retention);
        }
        assert_eq!(
            retired_rewrites(&session),
            4,
            "the eighth compaction retires up to the durable head"
        );
        compact_and_retire(&mut session, 8, retention);
        assert_eq!(
            retired_rewrites(&session),
            4,
            "the ninth compaction keeps what the durable head does not cover"
        );
        meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut session,
            &run_id,
            Some(&receipt),
        )
        .await
        .expect("the checkpoint proves its suffix from the durable head")
        .expect("the next provisional successor");
        assert_eq!(physical_rewrite_count(&service, &id).await, 9);
    }

    /// A committed run boundary advances the cap on the session the next run
    /// continues with: a second long run retires back toward the retention
    /// within that boundary, and its checkpoint still proves the suffix.
    #[tokio::test]
    async fn a_second_run_retires_within_the_committed_boundary_and_checkpoints() {
        let (_directory, service, checkpointer, committed) = retention_checkpoint_fixture().await;
        let id = committed.id().clone();
        let retention = meerkat_core::TranscriptHistoryRetention::from_count(4).unwrap();
        let mut session = committed;
        for compaction in 0..6 {
            compact_and_retire(&mut session, compaction, retention);
        }
        let mut session = service
            .persist_detached_head_canonical_session(session, "first run boundary")
            .await
            .expect("the first run's boundary commits every compaction of the run");
        assert_eq!(physical_rewrite_count(&service, &id).await, 6);
        assert_eq!(retired_rewrites(&session), 0);

        for compaction in 6..12 {
            compact_and_retire(&mut session, compaction, retention);
        }
        assert_eq!(
            retired_rewrites(&session),
            6,
            "the second run retires up to the committed boundary"
        );
        meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut session,
            &RunId::new(),
            None,
        )
        .await
        .expect("the second run's checkpoint proves its suffix from the boundary")
        .expect("a provisional successor");
        assert_eq!(physical_rewrite_count(&service, &id).await, 12);
        compact_and_retire(&mut session, 12, retention);
        assert_eq!(
            retired_rewrites(&session),
            9,
            "after the checkpoint the graph is back at the retention bound"
        );
    }

    /// The shape after a restart: the session is materialized from the
    /// store's committed head. A long run on it compacts more often than the
    /// retention keeps and its run-end commit still proves every compaction;
    /// after a second restart the next long run's intra-turn checkpoint
    /// proves its suffix from the reloaded head.
    #[tokio::test]
    async fn a_session_reloaded_from_the_store_keeps_what_its_head_lacks() {
        let (_directory, service, checkpointer, committed) = retention_checkpoint_fixture().await;
        let id = committed.id().clone();
        drop(committed);
        let retention = meerkat_core::TranscriptHistoryRetention::from_count(4).unwrap();

        let mut session = service
            .load_committed_runtime_session_for_body(&id, "reload after restart")
            .await
            .unwrap()
            .expect("the committed head");
        for compaction in 0..6 {
            compact_and_retire(&mut session, compaction, retention);
        }
        let session = service
            .persist_detached_head_canonical_session(session, "run boundary")
            .await
            .expect("the run-end commit proves every compaction of the run");
        assert_eq!(physical_rewrite_count(&service, &id).await, 6);
        assert_eq!(
            retired_rewrites(&session),
            0,
            "nothing the reloaded head lacked was retired"
        );
        drop(session);

        let mut session = service
            .load_committed_runtime_session_for_body(&id, "reload after the second restart")
            .await
            .unwrap()
            .expect("the committed head");
        for compaction in 6..12 {
            compact_and_retire(&mut session, compaction, retention);
        }
        assert_eq!(
            retired_rewrites(&session),
            6,
            "the reloaded session retires up to its head and no further"
        );
        meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut session,
            &RunId::new(),
            None,
        )
        .await
        .expect("the intra-turn checkpoint proves its suffix from the reloaded head")
        .expect("a provisional successor");
        assert_eq!(physical_rewrite_count(&service, &id).await, 12);
    }

    /// An assistant row as a live agent stamps it during a run.
    fn run_stamped_assistant(
        run_id: &RunId,
        blocks: Vec<meerkat_core::AssistantBlock>,
        stop_reason: StopReason,
    ) -> Message {
        let mut assistant = meerkat_core::BlockAssistantMessage::new(blocks, stop_reason);
        assistant.identity.run_id = Some(run_id.clone());
        Message::BlockAssistant(assistant)
    }

    /// The durable state a host leaves when it dies after the final
    /// checkpoint of a run that compacted and before the runtime boundary
    /// commit that promotes it: the physical head is the provisional
    /// successor carrying the rewrite, and the committed authority still
    /// names the turn-start head. `tail` writes what the run produced after
    /// its compaction.
    async fn compacted_crash_tail(
        tail: impl FnOnce(&mut Session, &RunId),
    ) -> (
        tempfile::TempDir,
        PersistentSessionService<DummyBuilder>,
        SessionId,
        Session,
    ) {
        let (directory, service, checkpointer, committed) = retention_checkpoint_fixture().await;
        let id = committed.id().clone();
        let run_id = RunId::new();
        let mut session = committed;
        compact_and_retire(
            &mut session,
            0,
            meerkat_core::TranscriptHistoryRetention::from_count(4).unwrap(),
        );
        tail(&mut session, &run_id);
        meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut session,
            &run_id,
            None,
        )
        .await
        .expect("the run-end checkpoint of a compacting run")
        .expect("a provisional successor");
        assert_eq!(physical_rewrite_count(&service, &id).await, 1);
        (directory, service, id, session)
    }

    /// A host died between the final checkpoint of a run that compacted and
    /// its runtime boundary commit. The tail is a store-proven durable
    /// descendant of the committed authority through the rewrite, so
    /// recovery commits the completed run, rewrite included, as the
    /// recovered boundary, and the session resumes.
    #[tokio::test]
    async fn a_completed_crash_tail_that_compacted_is_recovered() {
        let (_directory, service, id, physical) = compacted_crash_tail(|session, run_id| {
            session.push(run_stamped_assistant(
                run_id,
                vec![meerkat_core::AssistantBlock::Text {
                    text: "answer after the compaction".to_string(),
                    meta: None,
                }],
                StopReason::EndTurn,
            ));
        })
        .await;

        let recovery = service
            .recover_committed_boundary(&id)
            .await
            .expect("a compacting run's crash tail is recoverable");
        assert!(
            matches!(
                recovery,
                CommittedBoundaryRecovery::Recovered { message_count }
                    if message_count == physical.messages().len()
            ),
            "the completed run is the recovered boundary: {recovery:?}"
        );
        let committed = service
            .load_committed_runtime_session_for_body(&id, "after recovery")
            .await
            .unwrap()
            .expect("the recovered committed head");
        assert_eq!(
            meerkat_core::transcript_messages_digest(committed.messages()).unwrap(),
            meerkat_core::transcript_messages_digest(physical.messages()).unwrap(),
            "the recovered boundary is exactly the durable tail"
        );
        assert_eq!(
            committed
                .transcript_history_state()
                .unwrap()
                .expect("rewrite graph")
                .commit_count(),
            1,
            "the rewrite is part of the recovered boundary"
        );
    }

    /// The same crash after a compacting run stopped at a tool call whose
    /// result it had already written: recovery closes the run as interrupted,
    /// keeps every durable row and appends the typed recovery notice.
    #[tokio::test]
    async fn an_interrupted_crash_tail_that_compacted_is_closed_as_interrupted() {
        let (_directory, service, id, physical) = compacted_crash_tail(|session, run_id| {
            session.push(run_stamped_assistant(
                run_id,
                vec![meerkat_core::AssistantBlock::ToolUse {
                    id: "call-after-compaction".to_string(),
                    name: "probe".into(),
                    args: serde_json::value::RawValue::from_string("{}".to_string()).unwrap(),
                    meta: None,
                }],
                StopReason::ToolUse,
            ));
            session.push(Message::ToolResults {
                results: vec![ToolResult::new(
                    "call-after-compaction".to_string(),
                    "ok".to_string(),
                    false,
                )],
                created_at: std::time::SystemTime::now().into(),
            });
        })
        .await;

        let recovery = service
            .recover_committed_boundary(&id)
            .await
            .expect("a compacting run's interrupted crash tail is recoverable");
        assert!(
            matches!(
                recovery,
                CommittedBoundaryRecovery::Recovered { message_count }
                    if message_count == physical.messages().len() + 1
            ),
            "every durable row plus the recovery notice: {recovery:?}"
        );
        let committed = service
            .load_committed_runtime_session_for_body(&id, "after recovery")
            .await
            .unwrap()
            .expect("the recovered committed head");
        assert!(
            matches!(committed.messages().last(), Some(Message::SystemNotice(_))),
            "the interrupted run ends with the typed recovery notice"
        );
    }

    /// A session whose committed boundary already carries a compaction
    /// rewrite from an earlier run: a later run that only appended rows dies
    /// before its boundary commit, and recovery commits it as usual.
    #[tokio::test]
    async fn a_plain_crash_tail_after_an_earlier_compaction_is_recovered() {
        let (_directory, service, checkpointer, committed) = retention_checkpoint_fixture().await;
        let id = committed.id().clone();
        let mut session = committed;
        compact_and_retire(
            &mut session,
            0,
            meerkat_core::TranscriptHistoryRetention::from_count(4).unwrap(),
        );
        let mut session = service
            .persist_detached_head_canonical_session(session, "earlier compacting run")
            .await
            .expect("the earlier run commits its compaction");
        assert_eq!(physical_rewrite_count(&service, &id).await, 1);
        let run_id = RunId::new();
        session.push(run_stamped_assistant(
            &run_id,
            vec![meerkat_core::AssistantBlock::Text {
                text: "a later answer".to_string(),
                meta: None,
            }],
            StopReason::EndTurn,
        ));
        meerkat_core::SessionCheckpointer::checkpoint_run(
            &checkpointer,
            &mut session,
            &run_id,
            None,
        )
        .await
        .expect("the later run's checkpoint")
        .expect("a provisional successor");

        let recovery = service
            .recover_committed_boundary(&id)
            .await
            .expect("a plain crash tail recovers whatever the boundary's history");
        assert!(
            matches!(
                recovery,
                CommittedBoundaryRecovery::Recovered { message_count }
                    if message_count == session.messages().len()
            ),
            "{recovery:?}"
        );
    }

    /// A HeadCanonical durable fork source as a turn start leaves it: a
    /// committed snapshot (the previous turn's end) with the canonical
    /// metadata and build state a targeted fork copies, and the actor
    /// checkpointer that writes the running turn's round commits over it.
    /// With `rewrite_audit` the service projects events into a file event
    /// store and the checkpointer carries the rewrite audit sink, as a
    /// service with event projection builds it.
    async fn caller_turn_fork_source_fixture(
        rewrite_audit: bool,
    ) -> (
        tempfile::TempDir,
        PersistentSessionService<DummyBuilder>,
        StoreCheckpointer,
        Session,
    ) {
        let directory = tempfile::Builder::new()
            .prefix(".caller-turn-fork-")
            .tempdir_in(".")
            .unwrap();
        let database_path = directory.path().join("runtime.sqlite3");
        let runtime_store = Arc::new(
            meerkat_runtime::SqliteRuntimeStore::new_head_canonical(&database_path).unwrap(),
        );
        let store = Arc::new(meerkat_store::SqliteSessionStore::open(&database_path).unwrap());
        let audit = rewrite_audit.then(|| {
            let event_store: Arc<dyn EventStore> = Arc::new(
                crate::event_store::FileEventStore::new(directory.path().join("events")),
            );
            let projector = Arc::new(SessionProjector::new(directory.path().join(".rkat")));
            (event_store, projector)
        });
        let mut service = PersistentSessionService::new(
            DummyBuilder,
            4,
            store,
            runtime_store.clone(),
            memory_blob_store(),
        );
        if let Some((event_store, projector)) = audit.clone() {
            service = service.with_event_projection(event_store, projector);
        }
        let mut source = recoverable_store_row();
        source
            .set_build_state(meerkat_core::SessionBuildState {
                app_context: Some(serde_json::json!({"domain": "fork-source"})),
                ..meerkat_core::SessionBuildState::default()
            })
            .expect("seed the source build state");
        source.push(user_message("the previous turn's question"));
        source.push(Message::BlockAssistant(
            meerkat_core::BlockAssistantMessage::new(
                vec![meerkat_core::AssistantBlock::Text {
                    text: "the previous turn's answer".to_string(),
                    meta: None,
                }],
                StopReason::EndTurn,
            ),
        ));
        let committed = service
            .persist_detached_head_canonical_session(source, "previous turn end")
            .await
            .unwrap();
        let checkpointer = StoreCheckpointer {
            runtime_store,
            incremental: service.incremental.clone(),
            blob_store: memory_blob_store(),
            gate: Arc::new(CheckpointerGate {
                cancelled: Mutex::new(false),
            }),
            whole_blob_base_authority: std::sync::Mutex::new(None),
            latest_run_checkpoint_receipt: Mutex::new(None),
            latest_run_transcript_retirement: std::sync::Mutex::new(None),
            live_deferred_turn_state: std::sync::OnceLock::new(),
            unattached_deferred_checkpoint_warned: std::sync::atomic::AtomicBool::new(false),
            rebased_run: std::sync::Mutex::new(None),
            latest_run_checkpoint_cursor: std::sync::Mutex::new(None),
            rebase_outcome_unknown: std::sync::Mutex::new(None),
            rewrite_audit: audit.map(|(event_store, projector)| RewriteAuditSink {
                event_store,
                projector: Some(projector),
            }),
        };
        (directory, service, checkpointer, committed)
    }

    fn caller_turn_fork_target() -> meerkat_core::DurableSessionForkTarget {
        meerkat_core::DurableSessionForkTarget {
            member_binding: meerkat_core::MobMemberBinding {
                mob_id: "mob".to_string(),
                role: "role".to_string(),
                member: "child".to_string(),
            },
            cache_identity: None,
            source_admission: meerkat_core::DurableForkSourceAdmission::CallerTurn,
            inherited_instructions: meerkat_core::ForkInstructionPolicy::default(),
            declared_instructions: meerkat_core::ForkInstructionPolicy::default(),
        }
    }

    /// The running turn's input and its first tool round, and the round
    /// commit that writes them as the run's provisional tail.
    async fn commit_running_turn_round(
        checkpointer: &StoreCheckpointer,
        running: &mut Session,
        run_id: &RunId,
    ) {
        running.push(user_message("the running turn's input"));
        running.push(run_stamped_assistant(
            run_id,
            vec![meerkat_core::AssistantBlock::ToolUse {
                id: "call-in-turn".to_string(),
                name: "probe".into(),
                args: serde_json::value::RawValue::from_string("{}".to_string()).unwrap(),
                meta: None,
            }],
            StopReason::ToolUse,
        ));
        running.push(Message::ToolResults {
            results: vec![ToolResult::new(
                "call-in-turn".to_string(),
                "ok".to_string(),
                false,
            )],
            created_at: std::time::SystemTime::now().into(),
        });
        meerkat_core::SessionCheckpointer::checkpoint_run(checkpointer, running, run_id, None)
            .await
            .expect("the running turn's round commit")
            .expect("a provisional successor");
    }

    /// `provisional_tail_stands` answers from the store's provisional-tail
    /// record, on HeadCanonical and on WholeBlob: no tail before a running
    /// turn's round commit, a standing one after it. It writes nothing: the
    /// store's resume observation and the tail record read the same before
    /// and after it answers.
    #[tokio::test]
    async fn provisional_tail_stands_reads_the_tail_record_on_both_formats_and_writes_nothing() {
        use meerkat_core::SessionCheckpointer as _;

        // HeadCanonical: a running turn's round commit over the committed
        // snapshot.
        let (_directory, service, checkpointer, committed) =
            caller_turn_fork_source_fixture(false).await;
        let id = committed.id().clone();
        let runtime_id = PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&id);
        assert!(
            !service
                .provisional_tail_stands(&id)
                .await
                .expect("the presence read answers"),
            "[head-canonical] no tail stands before the round commit"
        );
        let run_id = RunId::new();
        let mut running = committed.clone();
        commit_running_turn_round(&checkpointer, &mut running, &run_id).await;
        let observe = service
            .runtime_store
            .load_session_resume_observation(&runtime_id)
            .await
            .expect("observe the resume authority");
        let tail = service
            .runtime_store
            .load_head_canonical_provisional_tail(&runtime_id)
            .await
            .expect("read the provisional tail");
        assert!(
            tail.is_some(),
            "[head-canonical] the round commit records its tail"
        );
        assert!(
            service
                .provisional_tail_stands(&id)
                .await
                .expect("the presence read answers"),
            "[head-canonical] the round commit's tail stands"
        );
        assert_eq!(
            (
                service
                    .runtime_store
                    .load_session_resume_observation(&runtime_id)
                    .await
                    .expect("observe the resume authority"),
                service
                    .runtime_store
                    .load_head_canonical_provisional_tail(&runtime_id)
                    .await
                    .expect("read the provisional tail"),
            ),
            (observe, tail),
            "[head-canonical] the presence read writes nothing"
        );

        // WholeBlob: a run's round commit, as a provisional tail candidate.
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            CheckpointerHoldingBuilder::new(DummyBuilder),
            4,
            Arc::new(MemoryStore::new()),
            runtime_store.clone(),
            memory_blob_store(),
        );
        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create_session should succeed");
        let id = created.session_id;
        let runtime_id =
            PersistentSessionService::<CheckpointerHoldingBuilder<DummyBuilder>>::runtime_id_for_session(&id);
        assert!(
            !service
                .provisional_tail_stands(&id)
                .await
                .expect("the presence read answers"),
            "[whole-blob] no tail stands before the round commit"
        );
        let checkpointer = service
            .live_checkpointers
            .lock()
            .await
            .get(&id)
            .cloned()
            .and_then(|checkpointer| checkpointer.upgrade())
            .expect("the created actor registers its checkpointer");
        let run_id = RunId::new();
        let mut round = service
            .inner
            .export_session(&id)
            .await
            .expect("the created actor exports its session");
        round.push(Message::User(UserMessage::text(
            "the run's prompt".to_string(),
        )));
        checkpointer
            .checkpoint_run(&mut round, &run_id, None)
            .await
            .expect("the round checkpoints")
            .expect("a durable session writes a provisional tail");
        let observe = runtime_store
            .load_session_resume_observation(&runtime_id)
            .await
            .expect("observe the resume authority");
        let tail = runtime_store
            .load_whole_blob_provisional_tail(&runtime_id)
            .await
            .expect("read the provisional tail")
            .map(|tail| (tail.authority().clone(), tail.candidate_bytes().to_vec()));
        assert!(
            tail.is_some(),
            "[whole-blob] the round commit records its tail"
        );
        assert!(
            service
                .provisional_tail_stands(&id)
                .await
                .expect("the presence read answers"),
            "[whole-blob] the round commit's tail stands"
        );
        assert_eq!(
            (
                runtime_store
                    .load_session_resume_observation(&runtime_id)
                    .await
                    .expect("observe the resume authority"),
                runtime_store
                    .load_whole_blob_provisional_tail(&runtime_id)
                    .await
                    .expect("read the provisional tail")
                    .map(|tail| (tail.authority().clone(), tail.candidate_bytes().to_vec())),
            ),
            (observe, tail),
            "[whole-blob] the presence read writes nothing"
        );
    }

    /// The child of a caller-turn fork holds exactly the committed snapshot:
    /// its rows and its build state, and nothing of the running turn.
    async fn assert_fork_child_is_the_committed_snapshot(
        service: &PersistentSessionService<DummyBuilder>,
        forked: &SessionForkResult,
        committed: &Session,
    ) {
        assert_eq!(
            forked.message_count,
            committed.messages().len(),
            "the branch ends at the committed snapshot, not inside the running turn"
        );
        let child = service
            .load_committed_runtime_session_for_body(&forked.session_id, "fork child")
            .await
            .unwrap()
            .expect("the committed child");
        assert_eq!(
            meerkat_core::transcript_messages_digest(child.messages()).unwrap(),
            meerkat_core::transcript_messages_digest(committed.messages()).unwrap(),
            "the child holds exactly the committed snapshot's rows"
        );
        assert!(
            child.try_run_cursor().unwrap().is_none(),
            "no run cursor of the running turn reaches the child"
        );
        assert_eq!(
            child
                .try_build_state()
                .unwrap()
                .and_then(|state| state.app_context),
            Some(serde_json::json!({"domain": "fork-source"})),
            "the child carries the snapshot's build state"
        );
    }

    /// `fork_off` runs inside the source's own turn. Once that turn has
    /// committed a round, the round's HeadCanonical provisional tail sits
    /// ahead of the committed snapshot and the committed read refuses the
    /// boundary with `TranscriptRevisionConflict`. The caller-turn fork reads
    /// the snapshot whole through the tail and branches there; it writes
    /// nothing to the source, and an explicit count past the committed end
    /// is still refused.
    #[tokio::test]
    async fn a_caller_turn_fork_branches_at_the_committed_snapshot_under_a_round_commit() {
        let (_directory, service, checkpointer, committed) =
            caller_turn_fork_source_fixture(false).await;
        let id = committed.id().clone();
        let run_id = RunId::new();
        let mut running = committed.clone();
        commit_running_turn_round(&checkpointer, &mut running, &run_id).await;
        assert!(
            PersistentSessionService::<DummyBuilder>::is_transcript_revision_conflict(
                &service.load_authoritative_session_base(&id).await
            ),
            "the committed read refuses the boundary while the round's tail is ahead of it"
        );

        let forked = service
            .fork_durable_session(&id, None, None, Some(caller_turn_fork_target()))
            .await
            .expect("a caller-turn fork branches at the committed snapshot under the round's tail");
        assert_fork_child_is_the_committed_snapshot(&service, &forked, &committed).await;
        assert!(
            PersistentSessionService::<DummyBuilder>::is_transcript_revision_conflict(
                &service.load_authoritative_session_base(&id).await
            ),
            "the fork wrote nothing to the source: the round's tail is still ahead"
        );

        let past = service
            .fork_durable_session(
                &id,
                Some(committed.messages().len() + 1),
                None,
                Some(caller_turn_fork_target()),
            )
            .await;
        assert!(
            matches!(
                past,
                Err(SessionError::Agent(AgentError::ConfigError(ref message)))
                    if message.contains("out of bounds")
            ),
            "a count past the committed end reaches into the running turn: {past:?}"
        );
    }

    /// A round that compacts rewrites rows the committed snapshot holds, so
    /// the round's tail keeps no prefix of the snapshot. The caller-turn fork
    /// still branches at the snapshot's own rows, read whole from the store,
    /// never at a prefix of the rewritten tail.
    #[tokio::test]
    async fn a_caller_turn_fork_after_a_compacting_round_branches_at_the_committed_snapshot() {
        let (_directory, service, checkpointer, committed) =
            caller_turn_fork_source_fixture(false).await;
        let id = committed.id().clone();
        let run_id = RunId::new();
        let mut running = committed.clone();
        compact_and_retire(
            &mut running,
            0,
            meerkat_core::TranscriptHistoryRetention::from_count(4).unwrap(),
        );
        commit_running_turn_round(&checkpointer, &mut running, &run_id).await;
        assert_eq!(
            physical_rewrite_count(&service, &id).await,
            1,
            "the round's tail carries the compaction"
        );
        assert_ne!(
            meerkat_core::transcript_messages_digest(
                &running.messages()[..committed.messages().len()]
            )
            .unwrap(),
            meerkat_core::transcript_messages_digest(committed.messages()).unwrap(),
            "the tail's leading rows are not the committed snapshot's"
        );

        let forked = service
            .fork_durable_session(&id, None, None, Some(caller_turn_fork_target()))
            .await
            .expect(
                "a caller-turn fork branches at the committed snapshot under a compacting round",
            );
        assert_fork_child_is_the_committed_snapshot(&service, &forked, &committed).await;
    }

    /// The compacting round again, on a service that projects events with
    /// the checkpointer's rewrite audit sink. A HeadCanonical round commit
    /// appends no rewrite audit receipt, so the replay the fork runs on the
    /// committed snapshot finds no newer rewrite to graft: the child is
    /// still exactly the snapshot.
    #[tokio::test]
    async fn a_caller_turn_fork_after_a_compacting_round_under_the_rewrite_audit_is_exact() {
        let (_directory, service, checkpointer, committed) =
            caller_turn_fork_source_fixture(true).await;
        let id = committed.id().clone();
        let run_id = RunId::new();
        let mut running = committed.clone();
        compact_and_retire(
            &mut running,
            0,
            meerkat_core::TranscriptHistoryRetention::from_count(4).unwrap(),
        );
        commit_running_turn_round(&checkpointer, &mut running, &run_id).await;
        assert_eq!(
            physical_rewrite_count(&service, &id).await,
            1,
            "the round's tail carries the compaction"
        );
        let rewrite_receipts = service
            .event_log_read_from(&id, 1)
            .await
            .unwrap()
            .unwrap_or_default()
            .into_iter()
            .filter(|stored| {
                matches!(
                    stored.event,
                    meerkat_core::event::AgentEvent::TranscriptRewriteAuditReceiptCommitted { .. }
                        | meerkat_core::event::AgentEvent::TranscriptRewriteCommitted { .. }
                )
            })
            .count();
        assert_eq!(
            rewrite_receipts, 0,
            "a HeadCanonical round commit appends no rewrite audit receipt"
        );

        let forked = service
            .fork_durable_session(&id, None, None, Some(caller_turn_fork_target()))
            .await
            .expect("a caller-turn fork branches at the committed snapshot under the audit");
        assert_fork_child_is_the_committed_snapshot(&service, &forked, &committed).await;
    }

    /// The committed snapshot the tolerant read serves: the snapshot's rows
    /// and build state, and nothing of the running turn.
    fn assert_served_the_committed_snapshot(served: &Session, committed: &Session) {
        assert_eq!(
            meerkat_core::transcript_messages_digest(served.messages()).unwrap(),
            meerkat_core::transcript_messages_digest(committed.messages()).unwrap(),
            "the read serves the committed snapshot's rows, nothing of the running turn"
        );
        assert!(
            served.try_run_cursor().unwrap().is_none(),
            "no run cursor of the running turn reaches the reader"
        );
        assert_eq!(
            served
                .try_build_state()
                .unwrap()
                .and_then(|state| state.app_context),
            Some(serde_json::json!({"domain": "fork-source"})),
            "the read carries the snapshot's build state"
        );
    }

    /// While the session's own run holds a round commit's provisional tail
    /// ahead of the committed snapshot, the strict read refuses the boundary
    /// and the tolerant read serves the snapshot, read through the tail. The
    /// read writes nothing: the strict read still refuses afterwards.
    #[tokio::test]
    async fn the_tolerant_read_serves_the_committed_snapshot_under_a_round_commit() {
        let (_directory, service, checkpointer, committed) =
            caller_turn_fork_source_fixture(false).await;
        let id = committed.id().clone();
        let run_id = RunId::new();
        let mut running = committed.clone();
        commit_running_turn_round(&checkpointer, &mut running, &run_id).await;
        assert!(
            PersistentSessionService::<DummyBuilder>::is_transcript_revision_conflict(
                &service.load_authoritative_session(&id).await
            ),
            "the strict read refuses the boundary while the round's tail is ahead of it"
        );

        let served = service
            .load_committed_session_tolerating_tail(&id)
            .await
            .expect("the tolerant read serves the committed snapshot under the round's tail")
            .expect("the session is committed");
        assert_served_the_committed_snapshot(&served, &committed);
        assert!(
            PersistentSessionService::<DummyBuilder>::is_transcript_revision_conflict(
                &service.load_authoritative_session(&id).await
            ),
            "the read wrote nothing: the round's tail still stands"
        );
    }

    /// The read-only body observation a mob member's status view reads serves
    /// the committed snapshot under the session's own round commit too, and
    /// writes nothing: the strict observation still refuses afterwards.
    #[tokio::test]
    async fn the_read_only_body_observation_serves_the_committed_snapshot_under_a_round_commit() {
        let (_directory, service, checkpointer, committed) =
            caller_turn_fork_source_fixture(false).await;
        let id = committed.id().clone();
        let run_id = RunId::new();
        let mut running = committed.clone();
        commit_running_turn_round(&checkpointer, &mut running, &run_id).await;
        assert!(
            PersistentSessionService::<DummyBuilder>::is_transcript_revision_conflict(
                &service.observe_authoritative_session_body(&id).await
            ),
            "the strict observation refuses the boundary while the round's tail is ahead of it"
        );

        let served = service
            .observe_authoritative_session_body_tolerating_tail(&id)
            .await
            .expect("the observation serves the committed snapshot under the round's tail")
            .expect("the session is committed");
        assert_served_the_committed_snapshot(&served, &committed);
        assert!(
            PersistentSessionService::<DummyBuilder>::is_transcript_revision_conflict(
                &service.observe_authoritative_session_body(&id).await
            ),
            "the observation wrote nothing: the round's tail still stands"
        );
    }

    /// A physical head moved past the boundary with no provisional tail the
    /// store issued is not the session's own run: the tolerant read serves
    /// nothing. It fails closed with the store's own refusal, which names the
    /// inconsistency, where the strict read answers the revision conflict.
    #[tokio::test]
    async fn the_tolerant_read_keeps_the_refusal_without_a_bound_tail() {
        let (_directory, service, _checkpointer, committed) =
            caller_turn_fork_source_fixture(false).await;
        let id = committed.id().clone();
        let incremental = service.incremental.as_ref().expect("an incremental store");
        let physical = incremental
            .load_head(&id)
            .await
            .expect("load the physical head")
            .expect("the physical head exists");
        let mut advanced = committed.clone();
        advanced.push(user_message("written past the boundary"));
        let mutation = meerkat_core::session_store::PreparedHeadCanonicalMutation::prepare(
            &advanced,
            Some(physical),
        )
        .expect("prepare a physical-only successor");
        incremental
            .apply_prepared_head_canonical_mutation(&mutation)
            .await
            .expect("advance the physical head past the boundary");
        assert!(
            PersistentSessionService::<DummyBuilder>::is_transcript_revision_conflict(
                &service.load_authoritative_session(&id).await
            ),
            "the strict read refuses the boundary"
        );

        let tolerant = service.load_committed_session_tolerating_tail(&id).await;
        assert!(
            matches!(
                &tolerant,
                Err(SessionError::Agent(AgentError::InternalError(message)))
                    if message.contains("no store-issued provisional authority")
            ),
            "the tolerant read fails closed with the store's refusal: {tolerant:?}"
        );
    }

    /// A round that compacts rewrites rows the committed snapshot holds. The
    /// tolerant read still serves the snapshot's own rows, read whole from the
    /// store, and verifies its rewrite audit as the strict read does.
    #[tokio::test]
    async fn the_tolerant_read_replays_the_rewrite_audit_after_a_compacting_round() {
        let (_directory, service, checkpointer, committed) =
            caller_turn_fork_source_fixture(false).await;
        let id = committed.id().clone();
        let run_id = RunId::new();
        let mut running = committed.clone();
        compact_and_retire(
            &mut running,
            0,
            meerkat_core::TranscriptHistoryRetention::from_count(4).unwrap(),
        );
        commit_running_turn_round(&checkpointer, &mut running, &run_id).await;
        assert_eq!(
            physical_rewrite_count(&service, &id).await,
            1,
            "the round's tail carries the compaction"
        );

        let served = service
            .load_committed_session_tolerating_tail(&id)
            .await
            .expect("the tolerant read serves the committed snapshot under a compacting round")
            .expect("the session is committed");
        assert_served_the_committed_snapshot(&served, &committed);
        assert!(
            served
                .validated_transcript_history_state()
                .unwrap()
                .is_none_or(|history| history.commits().next().is_none()),
            "the snapshot carries none of the round's rewrites"
        );
    }

    /// The fork-source snapshot committed on either profile, and the actor
    /// checkpointer that writes a running turn's round commits over it, with
    /// no actor hosted. On HeadCanonical the round's provisional tail moves
    /// the physical head past the committed snapshot, and the strict read
    /// refuses the boundary; on WholeBlob the tail is a separate row and the
    /// committed document stays the snapshot (the control).
    async fn committed_snapshot_with_a_round_checkpointer(
        head_canonical: bool,
    ) -> (
        Option<tempfile::TempDir>,
        PersistentSessionService<DummyBuilder>,
        StoreCheckpointer,
        Session,
    ) {
        if head_canonical {
            let (directory, service, checkpointer, committed) =
                caller_turn_fork_source_fixture(false).await;
            return (Some(directory), service, checkpointer, committed);
        }
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::new(MemoryStore::new()),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );
        let mut source = recoverable_store_row();
        source
            .set_build_state(meerkat_core::SessionBuildState {
                app_context: Some(serde_json::json!({"domain": "fork-source"})),
                ..meerkat_core::SessionBuildState::default()
            })
            .expect("seed the source build state");
        source.push(user_message("the previous turn's question"));
        source.push(Message::BlockAssistant(
            meerkat_core::BlockAssistantMessage::new(
                vec![meerkat_core::AssistantBlock::Text {
                    text: "the previous turn's answer".to_string(),
                    meta: None,
                }],
                StopReason::EndTurn,
            ),
        ));
        let committed = service
            .save_normalized_session(source)
            .await
            .expect("commit the snapshot");
        let authority = runtime_store
            .load_whole_blob_store_authority(&LogicalRuntimeId::for_session(committed.id()))
            .await
            .expect("load the committed authority")
            .expect("the committed authority exists");
        let checkpointer = StoreCheckpointer {
            runtime_store,
            incremental: None,
            blob_store: memory_blob_store(),
            gate: Arc::new(CheckpointerGate {
                cancelled: Mutex::new(false),
            }),
            whole_blob_base_authority: std::sync::Mutex::new(Some(authority)),
            latest_run_checkpoint_receipt: Mutex::new(None),
            latest_run_transcript_retirement: std::sync::Mutex::new(None),
            live_deferred_turn_state: std::sync::OnceLock::new(),
            unattached_deferred_checkpoint_warned: std::sync::atomic::AtomicBool::new(false),
            rebased_run: std::sync::Mutex::new(None),
            latest_run_checkpoint_cursor: std::sync::Mutex::new(None),
            rebase_outcome_unknown: std::sync::Mutex::new(None),
            rewrite_audit: None,
        };
        (None, service, checkpointer, committed)
    }

    /// The committed snapshot with a running turn's round committed over it.
    async fn committed_snapshot_under_a_round_commit(
        head_canonical: bool,
    ) -> (
        Option<tempfile::TempDir>,
        PersistentSessionService<DummyBuilder>,
        Session,
    ) {
        let (directory, service, checkpointer, committed) =
            committed_snapshot_with_a_round_checkpointer(head_canonical).await;
        let mut running = committed.clone();
        commit_running_turn_round(&checkpointer, &mut running, &RunId::new()).await;
        assert_eq!(
            PersistentSessionService::<DummyBuilder>::is_transcript_revision_conflict(
                &service.load_authoritative_session(committed.id()).await
            ),
            head_canonical,
            "the strict read refuses the boundary on HeadCanonical only"
        );
        (directory, service, committed)
    }

    fn messages_digest(messages: &[Message]) -> String {
        meerkat_core::transcript_messages_digest(messages).unwrap()
    }

    /// Session history, the current transcript revision, the revision list
    /// and the activation records of a session whose own run holds a round
    /// commit serve the committed snapshot, on both profiles.
    async fn history_reads_serve_the_committed_snapshot_under_a_round_commit(head_canonical: bool) {
        let (_directory, service, committed) =
            committed_snapshot_under_a_round_commit(head_canonical).await;
        let id = committed.id().clone();

        let history = service
            .read_history(&id, SessionHistoryQuery::default())
            .await
            .expect("the history reads the committed snapshot");
        assert_eq!(history.message_count, committed.messages().len());
        assert_eq!(
            messages_digest(&history.messages),
            messages_digest(committed.messages())
        );

        let head_revision = committed.transcript_revision().unwrap();
        let revision = service
            .read_transcript_revision(
                &id,
                SessionTranscriptRevisionQuery {
                    revision: "current".to_string(),
                    offset: 0,
                    limit: None,
                },
            )
            .await
            .expect("the current revision reads the committed snapshot");
        assert_eq!(revision.head_revision, head_revision);
        assert_eq!(
            messages_digest(&revision.messages),
            messages_digest(committed.messages())
        );

        let revisions = service
            .list_transcript_revisions(&id, SessionTranscriptRevisionListQuery::default())
            .await
            .expect("the revision list reads the committed snapshot");
        assert_eq!(revisions.head_revision, head_revision);
        assert!(revisions.entries.is_empty(), "the snapshot has no rewrites");

        let activations = service
            .read_instruction_activation_records(
                &id,
                meerkat_core::InstructionActivationReadQuery::default(),
            )
            .await
            .expect("the activation records read the committed snapshot");
        assert!(activations.records.is_empty());
    }

