    #[tokio::test]
    async fn test_persistent_fork_at_rejects_running_session() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let builder = BlockingRunBuilder::new();
        let service = Arc::new(PersistentSessionService::new(
            builder.clone(),
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        ));

        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create_session should succeed");
        let parent_id = created.session_id;

        let admission = service
            .reserve_runtime_turn_admission(&parent_id)
            .await
            .expect("runtime turn admission should be reserved");
        let turn_service = Arc::clone(&service);
        let turn_id = parent_id.clone();
        let active_turn = tokio::spawn(async move {
            turn_service
                .apply_runtime_turn_with_reserved_admission(
                    &turn_id,
                    RunId::new(),
                    runtime_content_turn_request("slow follow up"),
                    RunApplyBoundary::RunStart,
                    vec![InputId::new()],
                    admission,
                )
                .await
        });
        builder.wait_for_entered_runs(1).await;

        let rejected = service
            .fork_session_at(
                &parent_id,
                SessionForkAtRequest {
                    message_index: 1,
                    running_behavior: TranscriptEditRunningBehavior::Reject,
                    tool_access_policy: None,
                    inherited_instructions: None,
                },
            )
            .await;
        assert!(
            matches!(rejected, Err(SessionError::Busy { ref id }) if id == &parent_id),
            "fork_at should reject a running session: {rejected:?}"
        );

        builder.release_notify.add_permits(1);
        active_turn
            .await
            .expect("active turn task should join")
            .expect("active turn should complete after fork rejection");
    }

    #[tokio::test]
    async fn durable_fork_from_the_running_source_turn_branches_at_the_committed_boundary() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let builder = BlockingRunBuilder::new();
        let service = Arc::new(PersistentSessionService::new(
            builder.clone(),
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        ));
        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create_session should succeed");
        let parent_id = created.session_id;
        // A targeted durable fork copies canonical parent metadata onto the
        // child and derives its build state, so seed both the way the
        // runtime does at its first boundary.
        let parent = service
            .load_authoritative_session_base(&parent_id)
            .await
            .expect("load runtime-authoritative parent")
            .expect("parent exists");
        let parent = mutate_test_session(parent, "run boundary", |parent| {
            parent
                .set_session_metadata(meerkat_core::SessionMetadata {
                    model_fallback: None,
                    schema_version: meerkat_core::SESSION_METADATA_SCHEMA_VERSION,
                    model: "test".to_string(),
                    max_tokens: 1024,
                    structured_output_retries: 2,
                    provider: meerkat_core::Provider::Anthropic,
                    self_hosted_server_id: None,
                    provider_params: None,
                    tooling: meerkat_core::SessionTooling::default(),
                    keep_alive: false,
                    comms_name: None,
                    peer_meta: None,
                    realm_id: None,
                    instance_id: None,
                    backend: None,
                    config_generation: None,
                    auth_binding: None,
                    mob_member_binding: None,
                })
                .expect("seed canonical parent metadata");
            parent
                .set_build_state(meerkat_core::SessionBuildState::default())
                .expect("seed the parent build state");
        });
        runtime_store
            .commit_session_snapshot(
                &PersistentSessionService::<BlockingRunBuilder>::runtime_id_for_session(&parent_id),
                meerkat_runtime::store::SerializedSessionSnapshot {
                    session_snapshot: (serde_json::to_vec(&parent)
                        .expect("serialize parent metadata snapshot"))
                    .into(),
                },
            )
            .await
            .expect("commit parent metadata snapshot");
        let committed_len = service
            .read_history(&parent_id, SessionHistoryQuery::default())
            .await
            .expect("parent history before the running turn")
            .message_count;
        let admission = service
            .reserve_runtime_turn_admission(&parent_id)
            .await
            .expect("runtime turn admission should be reserved");
        let turn_service = Arc::clone(&service);
        let turn_id = parent_id.clone();
        let active_turn = tokio::spawn(async move {
            turn_service
                .apply_runtime_turn_with_reserved_admission(
                    &turn_id,
                    RunId::new(),
                    runtime_content_turn_request("slow follow up"),
                    RunApplyBoundary::RunStart,
                    vec![InputId::new()],
                    admission,
                )
                .await
        });
        builder.wait_for_entered_runs(1).await;
        let target = |source_admission| meerkat_core::DurableSessionForkTarget {
            member_binding: meerkat_core::MobMemberBinding {
                mob_id: "mob".to_string(),
                role: "role".to_string(),
                member: "child".to_string(),
            },
            cache_identity: None,
            source_admission,
            inherited_instructions: meerkat_core::ForkInstructionPolicy::default(),
            declared_instructions: meerkat_core::ForkInstructionPolicy::default(),
        };

        // An external fork of the running source is still refused.
        let rejected = service
            .fork_durable_session(
                &parent_id,
                None,
                None,
                Some(target(meerkat_core::DurableForkSourceAdmission::Quiescent)),
            )
            .await;
        assert!(
            matches!(rejected, Err(SessionError::Busy { ref id }) if id == &parent_id),
            "a quiescent-admission fork must refuse a running source: {rejected:?}"
        );

        // The source's own turn may branch its committed transcript.
        let forked = service
            .fork_durable_session(
                &parent_id,
                None,
                None,
                Some(target(meerkat_core::DurableForkSourceAdmission::CallerTurn)),
            )
            .await
            .expect("a caller-turn fork must succeed while the source turn is running");
        assert_ne!(forked.session_id, parent_id);
        assert_eq!(
            forked.message_count, committed_len,
            "the branch must end at the source's last committed boundary, not include the running turn"
        );
        let fork_history = service
            .read_history(&forked.session_id, SessionHistoryQuery::default())
            .await
            .expect("fork history should be persisted");
        assert_eq!(fork_history.message_count, committed_len);

        builder.release_notify.add_permits(1);
        active_turn
            .await
            .expect("active turn task should join")
            .expect("the running turn must complete after the caller-turn fork");
        let parent_history = service
            .read_history(&parent_id, SessionHistoryQuery::default())
            .await
            .expect("parent history after the turn");
        assert!(
            parent_history.message_count >= committed_len,
            "the caller-turn fork must not shrink or disturb the parent transcript"
        );
    }

    /// Seed a durable fork source the way the runtime does at its first
    /// boundary (canonical metadata and build state), with `extra` appended
    /// to its committed transcript.
    async fn seed_quiescent_fork_source(
        service: &PersistentSessionService<BlockingRunBuilder>,
        runtime_store: &Arc<dyn RuntimeStore>,
        extra: Vec<Message>,
    ) -> SessionId {
        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create_session should succeed");
        let parent_id = created.session_id;
        let parent = service
            .load_authoritative_session_base(&parent_id)
            .await
            .expect("load runtime-authoritative parent")
            .expect("parent exists");
        let parent = mutate_test_session(parent, "run boundary", |parent| {
            parent
                .set_session_metadata(meerkat_core::SessionMetadata {
                    model_fallback: None,
                    schema_version: meerkat_core::SESSION_METADATA_SCHEMA_VERSION,
                    model: "test".to_string(),
                    max_tokens: 1024,
                    structured_output_retries: 2,
                    provider: meerkat_core::Provider::Anthropic,
                    self_hosted_server_id: None,
                    provider_params: None,
                    tooling: meerkat_core::SessionTooling::default(),
                    keep_alive: false,
                    comms_name: None,
                    peer_meta: None,
                    realm_id: None,
                    instance_id: None,
                    backend: None,
                    config_generation: None,
                    auth_binding: None,
                    mob_member_binding: None,
                })
                .expect("seed canonical parent metadata");
            parent
                .set_build_state(meerkat_core::SessionBuildState::default())
                .expect("seed the parent build state");
            for message in extra {
                parent.push(message);
            }
        });
        runtime_store
            .commit_session_snapshot(
                &PersistentSessionService::<BlockingRunBuilder>::runtime_id_for_session(&parent_id),
                meerkat_runtime::store::SerializedSessionSnapshot {
                    session_snapshot: (serde_json::to_vec(&parent)
                        .expect("serialize parent metadata snapshot"))
                    .into(),
                },
            )
            .await
            .expect("commit parent metadata snapshot");
        parent_id
    }

    fn quiescent_fork_target(
        member: &str,
        source_admission: meerkat_core::DurableForkSourceAdmission,
    ) -> meerkat_core::DurableSessionForkTarget {
        meerkat_core::DurableSessionForkTarget {
            member_binding: meerkat_core::MobMemberBinding {
                mob_id: "mob".to_string(),
                role: "role".to_string(),
                member: member.to_string(),
            },
            cache_identity: None,
            source_admission,
            inherited_instructions: meerkat_core::ForkInstructionPolicy::default(),
            declared_instructions: meerkat_core::ForkInstructionPolicy::default(),
        }
    }

    fn answered_exchange(prompt: &str) -> Vec<Message> {
        vec![
            Message::User(UserMessage::text(prompt.to_string())),
            Message::BlockAssistant(meerkat_core::types::BlockAssistantMessage {
                blocks: vec![meerkat_core::types::AssistantBlock::Text {
                    text: "ok".to_string(),
                    meta: None,
                }],
                stop_reason: Some(meerkat_core::types::StopReason::EndTurn),
                identity: meerkat_core::types::TranscriptMessageIdentity::default(),
                created_at: meerkat_core::types::message_timestamp_now(),
                assistant_message_id: None,
            }),
        ]
    }

    /// Regression (#1190): the runtime loop holds the source's
    /// turn-finalization boundary for a whole lap, from dequeue through
    /// materialization to the provider call, before the turn holds any live
    /// admission. A `Quiescent` fork in that window used to queue on the
    /// boundary until the turn ended. It must answer `Busy` within its bound
    /// instead, and fork normally once the boundary is free.
    #[tokio::test]
    async fn quiescent_durable_fork_answers_busy_instead_of_queueing_on_a_held_turn_boundary() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let service = Arc::new(PersistentSessionService::new(
            BlockingRunBuilder::new(),
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        ));
        let parent_id =
            seed_quiescent_fork_source(&service, &runtime_store, answered_exchange("first")).await;

        // A lap that has dequeued the next input but not started its turn:
        // the boundary is held and no runtime admission is active yet.
        let lap = service
            .acquire_runtime_turn_finalization_guard(&parent_id)
            .await;
        let started = std::time::Instant::now();
        let refused = tokio::time::timeout(
            std::time::Duration::from_secs(10),
            service.fork_durable_session(
                &parent_id,
                None,
                None,
                Some(quiescent_fork_target(
                    "held",
                    meerkat_core::DurableForkSourceAdmission::Quiescent,
                )),
            ),
        )
        .await
        .expect("a quiescent fork must answer instead of queueing on the held boundary");
        assert!(
            matches!(refused, Err(SessionError::Busy { ref id }) if id == &parent_id),
            "a quiescent fork of a source whose boundary is held must be Busy: {refused:?}"
        );
        assert!(
            started.elapsed()
                < PersistentSessionService::<BlockingRunBuilder>::QUIESCENT_FORK_BOUNDARY_BOUND
                    + std::time::Duration::from_secs(2),
            "the refusal answers within the quiescent fork bound, took {:?}",
            started.elapsed()
        );

        drop(lap);
        let forked = service
            .fork_durable_session(
                &parent_id,
                None,
                None,
                Some(quiescent_fork_target(
                    "free",
                    meerkat_core::DurableForkSourceAdmission::Quiescent,
                )),
            )
            .await
            .expect("a quiescent fork of an idle source succeeds");
        assert_ne!(forked.session_id, parent_id);
    }

    /// Regression (#1190): a source whose committed end is an input it has
    /// not answered (for example a turn that died after committing its
    /// input) must not be branched at that end by a `Quiescent` fork, or the
    /// child inherits the unanswered input as its last message. An explicit
    /// shorter prefix and the source's own `CallerTurn` fork are unaffected.
    #[tokio::test]
    async fn quiescent_durable_fork_refuses_a_committed_end_that_is_an_unanswered_input() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let service = Arc::new(PersistentSessionService::new(
            BlockingRunBuilder::new(),
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        ));
        let mut transcript = answered_exchange("answered");
        transcript.push(Message::User(UserMessage::text("unanswered".to_string())));
        let parent_id = seed_quiescent_fork_source(&service, &runtime_store, transcript).await;
        let committed_len = service
            .read_history(&parent_id, SessionHistoryQuery::default())
            .await
            .expect("source history")
            .message_count;

        for message_count in [None, Some(committed_len)] {
            let refused = service
                .fork_durable_session(
                    &parent_id,
                    message_count,
                    None,
                    Some(quiescent_fork_target(
                        "torn",
                        meerkat_core::DurableForkSourceAdmission::Quiescent,
                    )),
                )
                .await;
            assert!(
                matches!(refused, Err(SessionError::Busy { ref id }) if id == &parent_id),
                "a quiescent fork of an unanswered committed end ({message_count:?}) must be \
                 Busy: {refused:?}"
            );
        }

        let prefix = service
            .fork_durable_session(
                &parent_id,
                Some(committed_len - 1),
                None,
                Some(quiescent_fork_target(
                    "prefix",
                    meerkat_core::DurableForkSourceAdmission::Quiescent,
                )),
            )
            .await
            .expect("an explicit prefix before the unanswered input is the caller's boundary");
        assert_eq!(prefix.message_count, committed_len - 1);

        let own_turn = service
            .fork_durable_session(
                &parent_id,
                None,
                None,
                Some(quiescent_fork_target(
                    "own-turn",
                    meerkat_core::DurableForkSourceAdmission::CallerTurn,
                )),
            )
            .await
            .expect("the source's own turn keeps its fork contract");
        assert_eq!(own_turn.message_count, committed_len);
    }

