    /// An authoritative load read and materialized EVERY transcript rewrite
    /// record in the append-only log, and each record carries two full
    /// transcript bodies, so resume cost grew as retained-revisions x
    /// transcript. A steady-state load folds nothing, so it must materialize
    /// nothing.
    ///
    /// Two deterministic measurements, because either alone permits a false
    /// green. Per-thread hashed bytes would stay flat even if every body were
    /// still JSON-parsed; exact rows returned by the store would stay flat if
    /// some other seam hashed the whole graph. Both are asserted, never the
    /// clock and never a process-global before/after counter.
    ///
    /// Wired to [`crate::event_store::FileEventStore`] because that is what
    /// production wires. A store that hands back typed `StoredEvent` clones
    /// runs neither the record decode nor the raw-row read, so it cannot
    /// observe either property — a green assertion over such a store would
    /// certify something the shipped path does not do.
    #[tokio::test]
    async fn test_authoritative_load_materializes_no_rewrite_record_bodies() {
        async fn load_cost(rewrites: usize) -> (u64, u64) {
            let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
            let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
            let dir = tempfile::tempdir().expect("temp dir");
            let event_store = Arc::new(ObservingEventStore::new(dir.path().join("events")));
            let service = PersistentSessionService::new(
                CapabilityBuilder,
                4,
                Arc::clone(&store),
                Arc::clone(&runtime_store),
                memory_blob_store(),
            )
            .with_event_projection(
                Arc::clone(&event_store) as Arc<dyn EventStore>,
                Arc::new(SessionProjector::new(dir.path().join(".rkat"))),
            );
            let created = service
                .create_session(create_request("seed", InitialTurnPolicy::Defer))
                .await
                .expect("create session");

            // Generation 0 grows the transcript so a per-record proof is
            // measurable; the rest are resume-shaped `[0, 1)` refreshes over
            // it, which is the production shape that accumulates revisions.
            for generation in 0..=rewrites {
                let parent = service
                    .export_realtime_refresh_session_snapshot(&created.session_id)
                    .await
                    .expect("read rewrite parent");
                let parent_revision = parent.transcript_revision().expect("parent revision");
                let (selection, replacement) = if generation == 0 {
                    (
                        TranscriptRewriteSelection::MessageRange { start: 0, end: 0 },
                        (0..12)
                            .map(|index| Message::User(UserMessage::text(format!("turn {index}"))))
                            .collect(),
                    )
                } else {
                    (
                        TranscriptRewriteSelection::MessageRange { start: 0, end: 1 },
                        vec![Message::User(UserMessage::text(format!(
                            "system prompt generation {generation}"
                        )))],
                    )
                };
                service
                    .rewrite_session_transcript(
                        &created.session_id,
                        SessionTranscriptRewriteRequest {
                            selection,
                            replacement,
                            reason: TranscriptRewriteReason::new("adversarial-rewrite-chain"),
                            actor: None,
                            expected_parent_revision: Some(parent_revision),
                            running_behavior: TranscriptEditRunningBehavior::Reject,
                        },
                    )
                    .await
                    .expect("rewrite commits");
            }
            service
                .discard_live_session(&created.session_id)
                .await
                .expect("force the durable load path");
            service
                .load_authoritative_session_base(&created.session_id)
                .await
                .expect("warm the per-shape decode memo");

            // WholeBlob ingress necessarily decodes the one current document.
            // Keep that O(document) work outside this audit-tail probe: this
            // regression is specifically about work proportional to retained
            // rewrite bodies after the current graph has already been proved.
            let session = service
                .load_committed_runtime_session_for_body(
                    &created.session_id,
                    "rewrite-body materialization probe",
                )
                .await
                .expect("load current runtime authority")
                .expect("session remains present");
            session
                .validate_transcript_history_state()
                .expect("prove current compact graph before audit-tail measurement");
            event_store.reset();
            let hashed_before = meerkat_core::session_content_digest_bytes();
            let replay = service
                .apply_transcript_rewrite_replay(&created.session_id, Some(session))
                .await
                .expect("measured rewrite-audit replay");
            service
                .verify_transcript_rewrite_audit_events(
                    replay.session.as_ref().expect("session remains present"),
                    &replay,
                )
                .await
                .expect("measured rewrite-audit verification");
            let rows = event_store.raw_reads();
            assert!(
                rows.iter().all(|(scope, _)| *scope == 2),
                "steady-state load must use only a store-authorized tail: {rows:?}"
            );
            (
                meerkat_core::session_content_digest_bytes() - hashed_before,
                rows.into_iter().map(|(_, rows)| rows as u64).sum(),
            )
        }

        let (few_hashed, few_rows) = load_cost(2).await;
        let (many_hashed, many_rows) = load_cost(8).await;
        println!(
            "authoritative load: 2 rewrites hashed {few_hashed} B / returned {few_rows} body rows, \
             8 rewrites hashed {many_hashed} B / returned {many_rows} body rows"
        );
        // Zero, not a bound: a load that folds nothing decides coverage from
        // commit identity, and a commit is read without its record's two
        // transcript bodies. One body materialized here would be N of them on
        // a session with N retained rewrites, which is the defect.
        assert_eq!(
            (few_rows, many_rows),
            (0, 0),
            "a steady-state authoritative load folds no rewrite, so it must \
             receive no rewrite record body: 2 rewrites returned \
             {few_rows}, 8 returned {many_rows}"
        );
        // Equality, not a bound: the residual is the ONE live-transcript digest
        // the coverage decision needs, and the defect is precisely that the
        // residual used to carry a per-retained-revision term as well.
        assert_eq!(
            few_hashed, many_hashed,
            "a steady-state authoritative load must re-prove nothing the loaded \
             session already proves, so its hashed bytes cannot grow with the \
             retained revision count: 2 rewrites hashed {few_hashed} bytes, 8 \
             hashed {many_hashed}"
        );
    }

    // ---------------------------------------------------------------
    // Store-owned rewrite audit
    // ---------------------------------------------------------------

    /// A [`crate::event_store::FileEventStore`] that records whether each
    /// combined audit read returned a store-authorized delta or a full
    /// reconciliation, plus the number of exact rewrite rows returned.
    struct ObservingEventStore {
        inner: crate::event_store::FileEventStore,
        reads: std::sync::Mutex<Vec<(u64, usize)>>,
        raw_reads: std::sync::Mutex<Vec<(u64, usize)>>,
    }

    impl ObservingEventStore {
        fn new(root: std::path::PathBuf) -> Self {
            Self {
                inner: crate::event_store::FileEventStore::new(root),
                reads: std::sync::Mutex::new(Vec::new()),
                raw_reads: std::sync::Mutex::new(Vec::new()),
            }
        }

        fn reset(&self) {
            self.reads.lock().expect("reads lock").clear();
            self.raw_reads.lock().expect("raw reads lock").clear();
        }

        /// `(scope, rows)` for every combined audit read since reset: scope 2
        /// is an authorized tail and scope 1 is full reconciliation.
        fn raw_reads(&self) -> Vec<(u64, usize)> {
            self.raw_reads.lock().expect("raw reads lock").clone()
        }

        /// `(from_seq, rows)` for every typed read since the last reset.
        fn typed_reads(&self) -> Vec<(u64, usize)> {
            self.reads.lock().expect("reads lock").clone()
        }

        fn rows_read(&self) -> usize {
            self.raw_reads()
                .into_iter()
                .chain(self.typed_reads())
                .map(|(_, rows)| rows)
                .sum()
        }
    }

    #[async_trait::async_trait]
    impl EventStore for ObservingEventStore {
        async fn append_envelopes(
            &self,
            session_id: &SessionId,
            envelopes: &[meerkat_core::event::EventEnvelope<AgentEvent>],
        ) -> Result<u64, EventStoreError> {
            self.inner.append_envelopes(session_id, envelopes).await
        }

        async fn append_transcript_rewrite_receipt_exact(
            &self,
            session_id: &SessionId,
            receipt: &meerkat_core::TranscriptRewriteAuditReceiptBatch,
            final_assistant_text: Option<&str>,
        ) -> Result<crate::event_store::ExactTranscriptRewriteReceiptAppend, EventStoreError>
        {
            self.inner
                .append_transcript_rewrite_receipt_exact(session_id, receipt, final_assistant_text)
                .await
        }

        async fn append_interaction_terminal_exact(
            &self,
            session_id: &SessionId,
            interaction_id: meerkat_core::interaction::InteractionId,
            envelope: &meerkat_core::event::EventEnvelope<AgentEvent>,
        ) -> Result<ExactInteractionAppend, EventStoreError> {
            self.inner
                .append_interaction_terminal_exact(session_id, interaction_id, envelope)
                .await
        }

        async fn record_projection_halt(
            &self,
            session_id: &SessionId,
            reason: &str,
        ) -> Result<(), EventStoreError> {
            self.inner.record_projection_halt(session_id, reason).await
        }

        async fn projection_halt(
            &self,
            session_id: &SessionId,
        ) -> Result<Option<crate::event_store::EventProjectionHaltMarker>, EventStoreError>
        {
            self.inner.projection_halt(session_id).await
        }

        async fn read_from(
            &self,
            session_id: &SessionId,
            from_seq: u64,
        ) -> Result<Vec<StoredEvent>, EventStoreError> {
            let rows = self.inner.read_from(session_id, from_seq).await?;
            self.reads
                .lock()
                .expect("reads lock")
                .push((from_seq, rows.len()));
            Ok(rows)
        }

        async fn read_raw_from(
            &self,
            session_id: &SessionId,
            from_seq: u64,
        ) -> Result<Option<Vec<crate::event_store::RawStoredEvent>>, EventStoreError> {
            let rows = self.inner.read_raw_from(session_id, from_seq).await?;
            if let Some(rows) = rows.as_ref() {
                self.raw_reads
                    .lock()
                    .expect("raw reads lock")
                    .push((from_seq, rows.len()));
            }
            Ok(rows)
        }

        async fn read_transcript_rewrite_audit(
            &self,
            session_id: &SessionId,
            expectation: crate::event_store::TranscriptRewriteAuditExpectation<'_>,
        ) -> Result<Option<crate::event_store::TranscriptRewriteAuditRead>, EventStoreError>
        {
            let read = self
                .inner
                .read_transcript_rewrite_audit(session_id, expectation)
                .await?;
            if let Some(read) = read.as_ref() {
                let (scope, rows) = match read {
                    crate::event_store::TranscriptRewriteAuditRead::AuthorizedTail(rows) => {
                        (2, rows.rewrite_rows().len())
                    }
                    crate::event_store::TranscriptRewriteAuditRead::FullReconciliation(rows) => {
                        (1, rows.rewrite_rows().len())
                    }
                };
                self.raw_reads
                    .lock()
                    .expect("raw reads lock")
                    .push((scope, rows));
            }
            Ok(read)
        }

        async fn finalize_transcript_rewrite_audit(
            &self,
            receipt: &crate::event_store::TranscriptRewritePrefixReceipt,
        ) -> Result<(), EventStoreError> {
            self.inner.finalize_transcript_rewrite_audit(receipt).await
        }

        async fn read_from_bounded(
            &self,
            session_id: &SessionId,
            from_seq: u64,
            max_rows: usize,
        ) -> Result<Vec<StoredEvent>, EventStoreError> {
            self.inner
                .read_from_bounded(session_id, from_seq, max_rows)
                .await
        }

        async fn last_seq(&self, session_id: &SessionId) -> Result<u64, EventStoreError> {
            self.inner.last_seq(session_id).await
        }
    }

    /// A session with `rewrites` resume-shaped refreshes over a real transcript,
    /// wired to an [`ObservingEventStore`], discarded so loads take the durable
    /// path.
    async fn audit_fixture(
        dir: &tempfile::TempDir,
        rewrites: usize,
    ) -> (
        PersistentSessionService<CapabilityBuilder>,
        Arc<ObservingEventStore>,
        SessionId,
    ) {
        let (service, event_store, id, _, _) = audit_fixture_with_stores(dir, rewrites).await;
        (service, event_store, id)
    }

    /// [`audit_fixture`] exposing the backing stores, for tests that freeze
    /// or doctor the durable copies underneath the service.
    async fn audit_fixture_with_stores(
        dir: &tempfile::TempDir,
        rewrites: usize,
    ) -> (
        PersistentSessionService<CapabilityBuilder>,
        Arc<ObservingEventStore>,
        SessionId,
        Arc<dyn SessionStore>,
        Arc<InMemoryRuntimeStore>,
    ) {
        let event_store = Arc::new(ObservingEventStore::new(dir.path().join("events")));
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            CapabilityBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        )
        .with_event_projection(
            Arc::clone(&event_store) as Arc<dyn EventStore>,
            Arc::new(SessionProjector::new(dir.path().join(".rkat"))),
        );
        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create session");
        commit_resume_shaped_rewrites(&service, &created.session_id, 0..=rewrites).await;
        service
            .discard_live_session(&created.session_id)
            .await
            .expect("force the durable load path");
        (
            service,
            event_store,
            created.session_id,
            store,
            runtime_store,
        )
    }

    /// Generation 0 grows the transcript so a per-record proof is measurable;
    /// the rest are adversarial `[0, 1)` rewrites over it, the production
    /// shape that accumulates revisions.
    async fn commit_resume_shaped_rewrites(
        service: &PersistentSessionService<CapabilityBuilder>,
        id: &SessionId,
        generations: std::ops::RangeInclusive<usize>,
    ) {
        for generation in generations {
            let parent = service
                .export_realtime_refresh_session_snapshot(id)
                .await
                .expect("read rewrite parent");
            let parent_revision = parent.transcript_revision().expect("parent revision");
            let (selection, replacement) = if generation == 0 {
                (
                    TranscriptRewriteSelection::MessageRange { start: 0, end: 0 },
                    (0..12)
                        .map(|index| Message::User(UserMessage::text(format!("turn {index}"))))
                        .collect(),
                )
            } else {
                (
                    TranscriptRewriteSelection::MessageRange { start: 0, end: 1 },
                    vec![Message::User(UserMessage::text(format!(
                        "system prompt generation {generation}"
                    )))],
                )
            };
            service
                .rewrite_session_transcript(
                    id,
                    SessionTranscriptRewriteRequest {
                        selection,
                        replacement,
                        reason: TranscriptRewriteReason::new("adversarial-rewrite-chain"),
                        actor: None,
                        expected_parent_revision: Some(parent_revision),
                        running_behavior: TranscriptEditRunningBehavior::Reject,
                    },
                )
                .await
                .expect("rewrite commits");
        }
    }

    /// A steady-state load must not read rewrite rows already folded into the
    /// checkpoint-bound graph, and its row count must not grow with history.
    ///
    /// Asserted on rows returned by the store, not on wall time and not on
    /// hashed bytes: a commit-only read hashes nothing and materializes nothing
    /// while still touching every byte of every row on its way to the last one,
    /// so only a row count can tell a flat read from a cheap-per-row one.
    #[tokio::test]
    async fn test_steady_state_load_reads_no_rewrite_rows_it_already_folded() {
        async fn rows_for(rewrites: usize) -> usize {
            let dir = tempfile::tempdir().expect("temp dir");
            // Each rewrite already goes through the authoritative load path,
            // updates the graph and EventStore head, then saves.
            let (service, event_store, id) = audit_fixture(&dir, rewrites).await;
            // WholeBlob materialization necessarily parses and validates the
            // retained compact graph. Keep that document-ingress work outside
            // this audit-tail measurement: the regression guarded here is
            // specifically that receipt authorization must compare the
            // already-proved prefix in O(1), not rebuild it from commits.
            let session = service
                .load_committed_runtime_session_for_body(&id, "rewrite-audit cost probe")
                .await
                .expect("load measured runtime authority")
                .expect("session is present");
            session
                .validate_transcript_history_state()
                .expect("prove current compact graph before audit-tail measurement");
            event_store.reset();
            let before = meerkat_core::rewrite_record_body_decodes();
            let replay = service
                .apply_transcript_rewrite_replay(&id, Some(session))
                .await
                .expect("measured rewrite-audit replay");
            service
                .verify_transcript_rewrite_audit_events(
                    replay.session.as_ref().expect("session remains present"),
                    &replay,
                )
                .await
                .expect("measured rewrite-audit verification");
            let decoded = meerkat_core::rewrite_record_body_decodes() - before;
            let reads = event_store.raw_reads();
            assert!(
                reads.iter().all(|(scope, _)| *scope == 2),
                "steady state must use only store-authorized tails: {reads:?}"
            );
            let log_rows = event_store.last_seq(&id).await.expect("log high-water");
            let rows = event_store.rows_read();
            println!(
                "{rewrites} rewrites: load read {rows} of {log_rows} log rows \
                 (from {reads:?}), materialized {decoded} record bodies"
            );
            rows
        }

        let few = rows_for(2).await;
        let many = rows_for(8).await;
        assert_eq!(
            few, many,
            "the rows an authoritative load reads must not grow with the retained \
             rewrite count: 2 rewrites read {few} rows, 8 read {many}"
        );
    }

    /// A chain of `count` resume-shaped rewrites over a fixed transcript.
    fn graph_test_rewrite_chain(count: usize) -> Vec<meerkat_core::TranscriptRewriteRecord> {
        let mut messages = (0..6)
            .map(|index| Message::User(UserMessage::text(format!("turn {index}"))))
            .collect::<Vec<_>>();
        let body = |messages: Vec<Message>, parent: Option<&str>| {
            let revision =
                meerkat_core::transcript_messages_digest(&messages).expect("digest body");
            meerkat_core::TranscriptRevisionBody {
                revision,
                parent_revision: parent.map(str::to_string),
                messages,
                created_at: meerkat_core::time_compat::SystemTime::UNIX_EPOCH,
            }
        };
        let mut records = Vec::with_capacity(count);
        for generation in 0..count {
            let parent_body = body(messages.clone(), None);
            messages[0] = Message::User(UserMessage::text(format!(
                "system prompt generation {generation}"
            )));
            let revision_body = body(messages.clone(), Some(&parent_body.revision));
            let commit = meerkat_core::TranscriptRewriteCommit {
                rewrite_generation: u64::try_from(generation)
                    .expect("test generation fits u64")
                    .checked_add(1)
                    .expect("test generation does not overflow"),
                parent_revision: parent_body.revision.clone(),
                revision: revision_body.revision.clone(),
                selection: TranscriptRewriteSelection::MessageRange { start: 0, end: 1 },
                original_span_digest: meerkat_core::transcript_messages_digest(
                    &parent_body.messages[..1],
                )
                .expect("digest original span"),
                replacement_digest: meerkat_core::transcript_messages_digest(
                    &revision_body.messages[..1],
                )
                .expect("digest replacement span"),
                messages_before: parent_body.messages.len(),
                messages_after: revision_body.messages.len(),
                reason: TranscriptRewriteReason::new("adversarial-rewrite-chain"),
                actor: None,
                committed_at: meerkat_core::time_compat::SystemTime::UNIX_EPOCH,
            };
            records.push(
                meerkat_core::TranscriptRewriteRecord::new(commit, parent_body, revision_body)
                    .expect("chain record is valid"),
            );
        }
        records
    }

    /// THE CONTRACT WE CHOSE, pinned so nobody later reads the absence of a
    /// check as an oversight and "fixes" it back into a full log read per load.
    ///
    /// A load that folds nothing materializes no record body, and a load that
    /// materializes no body cannot detect corruption in one. That is
    /// verify-on-use, and it is deliberate: an authoritative load owes an
    /// integrity check on the graph it serves and on any record it actually
    /// folds — not on historical log bodies it will never look at. Restoring a
    /// check here means reading every body on every load, which is exactly the
    /// `Theta(records x transcript)` cost this work removed.
    ///
    /// Corruption in an unfolded body is a matter for an explicit audit pass.
    #[tokio::test]
    async fn test_a_load_that_folds_nothing_materializes_no_bodies_and_so_checks_none() {
        let dir = tempfile::tempdir().expect("temp dir");
        let (service, event_store, id) = audit_fixture(&dir, 3).await;
        // Warm through one load so the next one has nothing left to fold.
        service
            .load_authoritative_session_base(&id)
            .await
            .expect("warming load")
            .expect("session is present");

        event_store.reset();
        let before = meerkat_core::rewrite_record_body_decodes();
        service
            .load_authoritative_session_base(&id)
            .await
            .expect("steady-state load succeeds")
            .expect("session is present");
        let decoded = meerkat_core::rewrite_record_body_decodes() - before;

        assert_eq!(
            decoded, 0,
            "a load with nothing to fold must not build a single record body; \
             it built {decoded}"
        );
        assert!(
            event_store.typed_reads().is_empty(),
            "and must not take the typed read at all: {:?}",
            event_store.typed_reads()
        );
    }

    #[tokio::test]
    async fn test_realtime_open_snapshot_rejects_repeated_images_over_cumulative_budget() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let blob_store = Arc::new(MemoryBlobStore::new());
        let service_blob_store: Arc<dyn BlobStore> = blob_store.clone();
        let service = PersistentSessionService::new(
            CapabilityBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            service_blob_store,
        );

        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create_session should succeed");
        let blob_ref = blob_store
            .put_image("image/png", "AQID")
            .await
            .expect("image fixture should persist");
        let durable = service
            .export_live_session(&created.session_id)
            .await
            .expect("initial live session should export");
        let durable = mutate_test_session(durable, "run boundary", |durable| {
            for _ in 0..3 {
                durable.push(Message::User(UserMessage::with_blocks(vec![
                    ContentBlock::Image {
                        media_type: "image/png".to_string(),
                        data: ImageData::Blob {
                            blob_id: blob_ref.blob_id.clone(),
                        },
                    },
                ])));
            }
        });
        runtime_store
            .commit_session_snapshot(
                &LogicalRuntimeId::for_session(&created.session_id),
                SerializedSessionSnapshot {
                    session_snapshot: (serde_json::to_vec(&durable)
                        .expect("serialize repeated-image session"))
                    .into(),
                },
            )
            .await
            .expect("commit durable runtime snapshot");

        let error = service
            .export_realtime_open_session_snapshot_with_image_budget(&created.session_id, 6)
            .await
            .expect_err("three repeated three-byte images must exceed a six-byte budget");
        assert!(
            matches!(
                error,
                SessionError::Agent(AgentError::InternalError(ref message))
                    if message.contains("exceeds the 6-byte cumulative decoded limit")
                        && message.contains("attempted 9 bytes")
            ),
            "unexpected cumulative image budget error: {error}"
        );

        let synced_live = service
            .export_live_session(&created.session_id)
            .await
            .expect("failed projection hydration must leave canonical live history intact");
        assert_eq!(synced_live.messages().len(), 3);
        assert!(synced_live.messages().iter().all(|message| matches!(
            message,
            Message::User(user)
                if matches!(
                    user.content.as_slice(),
                    [ContentBlock::Image {
                        data: ImageData::Blob { blob_id },
                        ..
                    }] if blob_id == &blob_ref.blob_id
                )
        )));
    }

    #[tokio::test]
    async fn test_runtime_turn_synchronizes_stale_live_transcript_authority() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            CapabilityBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );

        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create_session should succeed");
        let durable = service
            .export_live_session(&created.session_id)
            .await
            .expect("initial live session should export");
        let durable = mutate_test_session(durable, "run boundary", |durable| {
            durable.push(Message::User(UserMessage::text(
                "durable runtime turn seed".to_string(),
            )));
        });
        runtime_store
            .commit_session_snapshot(
                &LogicalRuntimeId::for_session(&created.session_id),
                SerializedSessionSnapshot {
                    session_snapshot: (serde_json::to_vec(&durable)
                        .expect("serialize durable session"))
                    .into(),
                },
            )
            .await
            .expect("commit durable runtime snapshot");
        store
            .save(&durable)
            .await
            .expect("align the durable projection with the committed runtime checkpoint");

        let output = service
            .apply_runtime_turn(
                &created.session_id,
                RunId::new(),
                runtime_content_turn_request("next turn"),
                RunApplyBoundary::RunStart,
                vec![InputId::new()],
            )
            .await
            .expect("runtime turn should synchronize live semantics instead of rebuilding");

        let output_session: Session = serde_json::from_slice(
            output
                .whole_blob_bytes()
                .expect("whole-blob runtime boundary should encode")
                .expect("runtime output should carry a session snapshot"),
        )
        .expect("runtime output session snapshot should deserialize");
        assert!(
            output_session.messages().iter().any(|message| matches!(
                message,
                Message::User(user) if user.text_content() == "durable runtime turn seed"
            )),
            "runtime output must start from durable semantic authority"
        );
        assert!(
            service
                .has_live_session(&created.session_id)
                .await
                .expect("live-session status should succeed"),
            "runtime turn sync must preserve the live handle"
        );
        assert!(
            service.comms_runtime(&created.session_id).await.is_some(),
            "runtime turn sync must preserve live comms mechanics"
        );
    }

    #[derive(Clone, Copy, Debug)]
    enum ArchiveHandoffProfile {
        WholeBlob,
        HeadCanonical,
    }

    impl ArchiveHandoffProfile {
        const ALL: [Self; 2] = [Self::WholeBlob, Self::HeadCanonical];
    }

    enum ArchiveHandoffFailureControl {
        WholeBlob(Arc<GatedSnapshotRuntimeStore>),
        HeadCanonical(Arc<FailingHeadCanonicalCommitRuntimeStore>),
    }

    impl ArchiveHandoffFailureControl {
        fn fail_lifecycle_commits(&self, fail: bool) {
            match self {
                Self::WholeBlob(store) => store.set_fail_machine_lifecycle_commits(fail),
                Self::HeadCanonical(store) => {
                    store.fail_lifecycle_commits.store(fail, Ordering::Release);
                }
            }
        }

        fn fail_next_document_commit(&self) {
            match self {
                Self::WholeBlob(store) => store.fail_snapshot_commit_in(1),
                Self::HeadCanonical(store) => {
                    store.fail_commits.store(true, Ordering::Release);
                }
            }
        }

        fn allow_document_commits(&self) {
            match self {
                Self::WholeBlob(store) => store.set_fail_snapshot_commits(false),
                Self::HeadCanonical(store) => {
                    store.fail_commits.store(false, Ordering::Release);
                }
            }
        }
    }

    struct ArchiveHandoffFixture {
        service: PersistentSessionService<DummyBuilder>,
        machine: Arc<MeerkatMachine>,
        session_store: Arc<dyn SessionStore>,
        runtime_store: Arc<dyn RuntimeStore>,
        blob_store: Arc<dyn BlobStore>,
        failures: ArchiveHandoffFailureControl,
        session_id: SessionId,
        _storage_dir: Option<tempfile::TempDir>,
    }

    impl ArchiveHandoffFixture {
        async fn new(profile: ArchiveHandoffProfile, session: Session) -> Self {
            let session_id = session.id().clone();
            let (session_store, runtime_store, failures, storage_dir): (
                Arc<dyn SessionStore>,
                Arc<dyn RuntimeStore>,
                ArchiveHandoffFailureControl,
                Option<tempfile::TempDir>,
            ) = match profile {
                ArchiveHandoffProfile::WholeBlob => {
                    let runtime_store = Arc::new(GatedSnapshotRuntimeStore::new());
                    (
                        Arc::new(MemoryStore::new()),
                        Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
                        ArchiveHandoffFailureControl::WholeBlob(runtime_store),
                        None,
                    )
                }
                ArchiveHandoffProfile::HeadCanonical => {
                    let storage_dir =
                        tempfile::tempdir_in(".").expect("head-canonical archive test directory");
                    let database_path = storage_dir.path().join("runtime.sqlite3");
                    let runtime_store = Arc::new(FailingHeadCanonicalCommitRuntimeStore::new(
                        meerkat_runtime::SqliteRuntimeStore::new_head_canonical(&database_path)
                            .expect("head-canonical runtime store"),
                    ));
                    let session_store: Arc<dyn SessionStore> = Arc::new(
                        meerkat_store::SqliteSessionStore::open(&database_path)
                            .expect("co-located head-canonical session store"),
                    );
                    (
                        session_store,
                        Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
                        ArchiveHandoffFailureControl::HeadCanonical(runtime_store),
                        Some(storage_dir),
                    )
                }
            };
            let blob_store = memory_blob_store();
            let service = PersistentSessionService::new(
                DummyBuilder,
                4,
                Arc::clone(&session_store),
                Arc::clone(&runtime_store),
                Arc::clone(&blob_store),
            );
            match profile {
                ArchiveHandoffProfile::WholeBlob => {
                    service
                        .save_normalized_session(session)
                        .await
                        .expect("seed committed WholeBlob handoff");
                }
                ArchiveHandoffProfile::HeadCanonical => {
                    service
                        .persist_detached_head_canonical_session(
                            session,
                            "archive handoff test seed",
                        )
                        .await
                        .expect("seed committed HeadCanonical handoff");
                }
            }
            let machine = Arc::new(
                MeerkatMachine::persistent(Arc::clone(&runtime_store), Arc::clone(&blob_store))
                    .expect("construct runtime authority"),
            );
            machine
                .register_session(session_id.clone())
                .await
                .expect("register archive handoff session without importing its request");
            Self {
                service,
                machine,
                session_store,
                runtime_store,
                blob_store,
                failures,
                session_id,
                _storage_dir: storage_dir,
            }
        }

        async fn archive(&self) -> Result<(), SessionError> {
            let _turn_boundary = self
                .service
                .acquire_runtime_turn_finalization_guard(&self.session_id)
                .await;
            self.service
                .archive_with_machine_protocol_under_runtime_turn_boundary_and_hook_before(
                    &self.session_id,
                    MachineSessionArchiveProtocol::from_machine(self.machine.as_ref()),
                    meerkat_core::time_compat::Instant::now() + std::time::Duration::from_secs(10),
                    None,
                )
                .await
        }

        async fn durable_body(&self) -> Session {
            self.service
                .load_persisted_session_for_archive(&self.session_id)
                .await
                .expect("load committed archive handoff body")
                .expect("archive handoff body remains present")
        }

        async fn seed_originating_boundary(&self, run_id: RunId) {
            let body = self.durable_body().await;
            let receipt = meerkat_core::RunBoundaryReceiptDraft {
                run_id: run_id.clone(),
                boundary: RunApplyBoundary::RunStart,
                contributing_input_ids: Vec::new(),
                conversation_digest: Some(
                    body.transcript_content_digest()
                        .expect("digest archive handoff fixture"),
                ),
                message_count: body.messages().len(),
            }
            .into_sequenced(0);
            self.runtime_store
                .commit_prepared_session_boundary(
                    &PersistentSessionService::<DummyBuilder>::runtime_id_for_session(
                        &self.session_id,
                    ),
                    meerkat_runtime::PreparedRuntimeSessionCommit::success(
                        None,
                        receipt,
                        Vec::new(),
                        Some(self.session_id.clone()),
                    ),
                )
                .await
                .expect("seed exact committed originating boundary");
            assert!(
                self.runtime_store
                    .load_boundary_receipt(
                        &PersistentSessionService::<DummyBuilder>::runtime_id_for_session(
                            &self.session_id,
                        ),
                        &run_id,
                        0,
                    )
                    .await
                    .expect("read originating boundary")
                    .is_some()
            );
        }
    }

    fn archive_handoff_intent(model: &str) -> meerkat_core::image_generation::SwitchTurnIntent {
        meerkat_core::image_generation::SwitchTurnIntent {
            target_model: meerkat_core::lifecycle::run_primitive::ModelId::new(model),
            duration: meerkat_core::image_generation::SwitchTurnDuration::UntilChanged,
            origin: meerkat_core::image_generation::SwitchTurnOrigin::Model {
                reason:
                    meerkat_core::image_generation::SwitchTurnReasonTextDisposition::NotProvided,
            },
        }
    }

    fn archive_handoff_requested(
        request_id: meerkat_core::image_generation::SwitchTurnRequestId,
        run_id: RunId,
        model: &str,
    ) -> SessionModelRoutingControlRecord {
        SessionModelRoutingControlRecord::request(request_id, run_id, archive_handoff_intent(model))
            .expect("archive fixture intent is a durable handoff")
    }

    fn new_archive_handoff_request_id() -> meerkat_core::image_generation::SwitchTurnRequestId {
        serde_json::from_value(
            serde_json::to_value(RunId::new()).expect("serialize request-id UUID source"),
        )
        .expect("deserialize request-id UUID")
    }

    fn session_with_requested_archive_handoff()
    -> (Session, meerkat_runtime::CommittedModelRoutingHandoff) {
        let mut session = Session::new();
        let handoff = meerkat_runtime::CommittedModelRoutingHandoff {
            request_id: new_archive_handoff_request_id(),
            originating_run_id: RunId::new(),
            intent: archive_handoff_intent("claude-opus-5"),
        };
        session
            .append_model_routing_control_record(
                SessionModelRoutingControlRecord::request(
                    handoff.request_id,
                    handoff.originating_run_id.clone(),
                    handoff.intent.clone(),
                )
                .expect("archive fixture request"),
            )
            .expect("append archive fixture request");
        (session, handoff)
    }

    fn assert_handoff_abandoned(
        session: &Session,
        handoff: &meerkat_runtime::CommittedModelRoutingHandoff,
    ) {
        assert_eq!(
            session
                .model_routing_control()
                .disposition_of(&handoff.request_id),
            Some(ModelRoutingIntentRecordDisposition::Abandoned)
        );
        assert!(
            session
                .model_routing_control()
                .awaiting_decision()
                .next()
                .is_none(),
            "an archived session must owe no model-routing decision"
        );
        assert_eq!(
            session.model_routing_control().records().len(),
            2,
            "the archive terminal extends the request exactly once"
        );
    }

    /// Which durable store the cancellation-safety tests run against. Both
    /// branches prepare the terminal on a detached candidate, then commit
    /// through their profile-owned persistence path.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum TerminalCommitProfile {
        WholeBlob,
        HeadCanonical,
    }

    impl TerminalCommitProfile {
        const ALL: [Self; 2] = [Self::WholeBlob, Self::HeadCanonical];
    }

    /// The deterministic pause point, whichever store is underneath.
    enum TerminalCommitGate {
        WholeBlob(Arc<GatedSnapshotRuntimeStore>),
        HeadCanonical(Arc<FailingHeadCanonicalCommitRuntimeStore>),
    }

    impl TerminalCommitGate {
        fn pause(&self) {
            match self {
                Self::WholeBlob(store) => store.set_pause_session_boundary_commit(true),
                Self::HeadCanonical(store) => store.set_pause_session_boundary_commit(true),
            }
        }

        async fn entered(&self) {
            match self {
                Self::WholeBlob(store) => store.await_session_boundary_commit_entered().await,
                Self::HeadCanonical(store) => store.await_session_boundary_commit_entered().await,
            }
        }

        fn release(&self) {
            match self {
                Self::WholeBlob(store) => store.release_session_boundary_commit(),
                Self::HeadCanonical(store) => store.release_session_boundary_commit(),
            }
        }

        fn fail_commits(&self, fail: bool) {
            match self {
                Self::WholeBlob(store) => store.set_fail_snapshot_commits(fail),
                Self::HeadCanonical(store) => store.fail_commits.store(fail, Ordering::Release),
            }
        }

        fn fail_after_commit_once(&self) {
            match self {
                Self::WholeBlob(store) => {
                    store
                        .fail_after_session_boundary_commit
                        .store(true, Ordering::Release);
                }
                Self::HeadCanonical(store) => {
                    store
                        .fail_after_session_boundary_commit
                        .store(true, Ordering::Release);
                }
            }
        }

        fn pause_after_commit(&self) {
            match self {
                Self::WholeBlob(store) => {
                    store.set_pause_after_session_boundary_commit(true);
                }
                Self::HeadCanonical(store) => {
                    store.set_pause_after_session_boundary_commit(true);
                }
            }
        }

        async fn entered_after_commit(&self) {
            match self {
                Self::WholeBlob(store) => {
                    store.await_after_session_boundary_commit_entered().await;
                }
                Self::HeadCanonical(store) => {
                    store.await_after_session_boundary_commit_entered().await;
                }
            }
        }

        fn release_after_commit(&self) {
            match self {
                Self::WholeBlob(store) => store.release_after_session_boundary_commit(),
                Self::HeadCanonical(store) => store.release_after_session_boundary_commit(),
            }
        }
    }

    /// A real `PersistentSessionService` whose durable session-boundary commit
    /// can be stopped after detached preparation but before durable authority
    /// advances.
    struct CancellableTerminalCommitFixture {
        service: Arc<PersistentSessionService<DummyBuilder>>,
        gate: TerminalCommitGate,
        runtime_store: Arc<dyn RuntimeStore>,
        session_id: SessionId,
        handoff: meerkat_runtime::CommittedModelRoutingHandoff,
        _storage_dir: Option<tempfile::TempDir>,
    }

    impl CancellableTerminalCommitFixture {
        async fn new(profile: TerminalCommitProfile) -> Self {
            let (session_store, runtime_store, gate, storage_dir): (
                Arc<dyn SessionStore>,
                Arc<dyn RuntimeStore>,
                TerminalCommitGate,
                Option<tempfile::TempDir>,
            ) = match profile {
                TerminalCommitProfile::WholeBlob => {
                    let store = Arc::new(GatedSnapshotRuntimeStore::new());
                    (
                        Arc::new(MemoryStore::new()),
                        Arc::clone(&store) as Arc<dyn RuntimeStore>,
                        TerminalCommitGate::WholeBlob(store),
                        None,
                    )
                }
                TerminalCommitProfile::HeadCanonical => {
                    let storage_dir = tempfile::tempdir_in(".")
                        .expect("head-canonical cancellation test directory");
                    let database_path = storage_dir.path().join("runtime.sqlite3");
                    let store = Arc::new(FailingHeadCanonicalCommitRuntimeStore::new(
                        meerkat_runtime::SqliteRuntimeStore::new_head_canonical(&database_path)
                            .expect("head-canonical runtime store"),
                    ));
                    let session_store: Arc<dyn SessionStore> = Arc::new(
                        meerkat_store::SqliteSessionStore::open(&database_path)
                            .expect("co-located head-canonical session store"),
                    );
                    (
                        session_store,
                        Arc::clone(&store) as Arc<dyn RuntimeStore>,
                        TerminalCommitGate::HeadCanonical(store),
                        Some(storage_dir),
                    )
                }
            };
            let blob_store = memory_blob_store();
            let service = Arc::new(PersistentSessionService::new(
                DummyBuilder,
                4,
                session_store,
                Arc::clone(&runtime_store),
                Arc::clone(&blob_store),
            ));
            let (session, handoff) = session_with_requested_archive_handoff();
            let created = service
                .create_session(resume_request(session))
                .await
                .expect("resume a session that already owes a routing request");
            let session_id = created.session_id;
            service
                .persist_live_session_now(&session_id)
                .await
                .expect("commit the owed request durably before the test begins");
            Self {
                service,
                gate,
                runtime_store,
                session_id,
                handoff,
                _storage_dir: storage_dir,
            }
        }

        fn realized_record(&self) -> SessionModelRoutingControlRecord {
            SessionModelRoutingControlRecord::ModelRoutingIntentRealized {
                request_id: self.handoff.request_id,
                originating_run_id: self.handoff.originating_run_id.clone(),
                intent: self.handoff.intent.clone(),
                applied_identity: Box::new(meerkat_core::SessionLlmIdentity {
                    model: "claude-opus-5".to_string(),
                    provider: meerkat_core::Provider::Anthropic,
                    self_hosted_server_id: None,
                    provider_params: None,
                    auth_binding: None,
                }),
            }
        }

        fn commit(
            &self,
        ) -> impl std::future::Future<Output = Result<(), SessionError>> + Send + use<> {
            let service = Arc::clone(&self.service);
            let session_id = self.session_id.clone();
            let record = self.realized_record();
            async move {
                service
                    .commit_model_routing_control_record_durable_first(&session_id, record)
                    .await
            }
        }

        async fn durable_body(&self) -> Session {
            self.service
                .load_committed_runtime_session_for_body(
                    &self.session_id,
                    "cancellation-safety durable read",
                )
                .await
                .expect("read committed body")
                .expect("committed body remains present")
        }

        /// The store-issued authority token for the last COMMITTED boundary.
        ///
        /// Used instead of a body read while a commit is mid-flight because it
        /// gives the same profile-independent proof for WholeBlob and
        /// HeadCanonical: the token moves if and only if the boundary committed.
        async fn durable_authority_token(&self) -> Option<String> {
            self.runtime_store
                .load_session_boundary_authority(
                    &PersistentSessionService::<DummyBuilder>::runtime_id_for_session(
                        &self.session_id,
                    ),
                )
                .await
                .expect("read committed session authority")
                .map(|authority| {
                    PreparedRuntimeBoundaryIdentity::from_runtime_authority(
                        &authority,
                        &self.session_id,
                    )
                    .expect("committed authority identifies this session")
                    .authority_token
                })
        }

        /// A body read that tolerates an in-flight durable tail, for polling.
        async fn try_durable_disposition(&self) -> Option<ModelRoutingIntentRecordDisposition> {
            self.service
                .load_committed_runtime_session_for_body(
                    &self.session_id,
                    "cancellation-safety durable poll",
                )
                .await
                .ok()
                .flatten()
                .and_then(|session| {
                    session
                        .model_routing_control()
                        .disposition_of(&self.handoff.request_id)
                })
        }

        /// What the next pre-dequeue would read: committed authority.
        async fn durable_disposition(&self) -> Option<ModelRoutingIntentRecordDisposition> {
            self.durable_body()
                .await
                .model_routing_control()
                .disposition_of(&self.handoff.request_id)
        }

        async fn live_disposition(&self) -> Option<ModelRoutingIntentRecordDisposition> {
            match self
                .service
                .export_session_with_labels(&self.session_id)
                .await
            {
                Ok(session) => session
                    .model_routing_control()
                    .disposition_of(&self.handoff.request_id),
                Err(SessionError::NotFound { .. }) => None,
                Err(error) => unreachable!("read live body: {error}"),
            }
        }

        /// The invariant the whole seam exists to hold: a resolution visible in
        /// live state must also be on disk. A live-only terminal would let the
        /// request stop being owed with nothing durable behind it.
        async fn assert_no_live_only_terminal(&self, at: &str) {
            if self.live_disposition().await == Some(ModelRoutingIntentRecordDisposition::Realized)
            {
                assert_eq!(
                    self.durable_disposition().await,
                    Some(ModelRoutingIntentRecordDisposition::Realized),
                    "{at}: live reported a realized handoff that durable authority never received"
                );
            }
        }

        async fn await_durable_realized(&self, why: &str) {
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
            while self.try_durable_disposition().await
                != Some(ModelRoutingIntentRecordDisposition::Realized)
            {
                assert!(std::time::Instant::now() < deadline, "{why}");
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
            }
        }

        async fn await_live_realized(&self, why: &str) {
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
            while self.live_disposition().await
                != Some(ModelRoutingIntentRecordDisposition::Realized)
            {
                assert!(std::time::Instant::now() < deadline, "{why}");
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
            }
        }
    }

    /// Dropping the caller BEFORE the transaction can even start leaves the
    /// request owed. Nothing is half-applied, and the debt is still visible to
    /// the next pre-dequeue.
    #[tokio::test]
    async fn model_routing_terminal_commit_cancelled_before_it_starts_leaves_the_request_owed() {
        for profile in TerminalCommitProfile::ALL {
            let fixture = CancellableTerminalCommitFixture::new(profile).await;

            // Hold the gate the commit must take first, so the future is
            // guaranteed to be suspended before it has done anything at all.
            let blocked_gate = fixture
                .service
                .recovery_gate_for_session(&fixture.session_id)
                .await
                .lock_owned()
                .await;

            let mut commit = Box::pin(fixture.commit());
            tokio::select! {
                biased;
                _ = &mut commit => {
                    unreachable!("{profile:?}: the commit cannot progress while its gate is held")
                }
                () = std::future::ready(()) => {}
            }
            drop(commit);
            drop(blocked_gate);
            tokio::task::yield_now().await;

            assert_eq!(
                fixture.durable_disposition().await,
                Some(ModelRoutingIntentRecordDisposition::Requested),
                "{profile:?}: a commit cancelled before it started must leave the request owed"
            );
            fixture
                .assert_no_live_only_terminal("cancelled before start")
                .await;
        }
    }

    /// Dropping the caller before the durable commit cannot interrupt the
    /// detached transaction, and the live actor remains on committed authority
    /// until that commit lands.
    #[tokio::test]
    async fn model_routing_terminal_commit_survives_cancellation_before_durable_commit() {
        for profile in TerminalCommitProfile::ALL {
            let fixture = CancellableTerminalCommitFixture::new(profile).await;
            let authority_before = fixture.durable_authority_token().await;
            fixture.gate.pause();

            let mut commit = Box::pin(fixture.commit());
            tokio::select! {
                outcome = &mut commit => unreachable!(
                    "{profile:?}: the commit cannot finish while its store is paused: {outcome:?}"
                ),
                () = fixture.gate.entered() => {}
            }

            // Durable-first means the actor is untouched while the document
            // commit is paused.
            assert_eq!(
                fixture.live_disposition().await,
                Some(ModelRoutingIntentRecordDisposition::Requested),
                "{profile:?}: the paused commit must not expose a live-only terminal"
            );
            assert_eq!(
                fixture.durable_authority_token().await,
                authority_before,
                "{profile:?}: the paused commit must not have reached durable authority yet"
            );

            // The caller goes away exactly here.
            drop(commit);
            fixture.gate.release();

            fixture
                .await_durable_realized(&format!(
                    "{profile:?}: the abandoned transaction never committed; cancelling the \
                     caller tore it in half"
                ))
                .await;
            assert_ne!(
                fixture.durable_authority_token().await,
                authority_before,
                "{profile:?}: the durable boundary must have advanced"
            );
            assert_eq!(
                fixture.durable_disposition().await,
                Some(ModelRoutingIntentRecordDisposition::Realized),
                "{profile:?}: committed authority must carry the exact terminal"
            );
            assert_eq!(
                fixture.live_disposition().await,
                Some(ModelRoutingIntentRecordDisposition::Realized),
                "{profile:?}: live and durable must agree once the transaction completes"
            );
            fixture
                .assert_no_live_only_terminal("after abandoned commit completed")
                .await;
        }
    }

    fn suppressed_docs_intent(
        session: &Session,
    ) -> Option<meerkat_core::McpAttachmentIntentDisposition> {
        session.build_state().and_then(|state| {
            state
                .mcp_attachment_intents
                .iter()
                .find(|intent| intent.descriptor.server_name == "docs")
                .map(|intent| intent.disposition)
        })
    }

    /// A queued MCP attachment intent change stays owned through its durable
    /// settlement when the caller is dropped mid-save: the live session never
    /// holds a change that durable authority lacks once the commit lands.
    #[tokio::test]
    async fn mcp_attachment_intent_change_settles_durably_after_caller_cancellation() {
        use meerkat_core::{
            McpAttachmentDescriptorIdentity, McpAttachmentIntentMutation, McpAttachmentTarget,
        };
        for profile in TerminalCommitProfile::ALL {
            let fixture = CancellableTerminalCommitFixture::new(profile).await;
            let update = |mutation: McpAttachmentIntentMutation| {
                let service = Arc::clone(&fixture.service);
                let session_id = fixture.session_id.clone();
                async move {
                    service
                        .update_session_mcp_attachment_intent_owned(&session_id, mutation)
                        .await
                }
            };
            update(McpAttachmentIntentMutation::Request {
                descriptor: McpAttachmentDescriptorIdentity {
                    server_name: "docs".to_string(),
                    target: McpAttachmentTarget::Http {
                        location: "https://docs.example/mcp".to_string(),
                        withheld: false,
                        binding: None,
                    },
                    oauth_account: None,
                    oauth_account_selection: None,
                    connector_account: None,
                },
            })
            .await
            .expect("record the request");
            assert_eq!(
                suppressed_docs_intent(&fixture.durable_body().await),
                Some(meerkat_core::McpAttachmentIntentDisposition::Requested),
                "{profile:?}: the request is durable before the test begins"
            );

            fixture.gate.pause();
            let mut suppress = Box::pin(update(McpAttachmentIntentMutation::SuppressByLogout {
                server_name: "docs".to_string(),
            }));
            tokio::select! {
                outcome = &mut suppress => unreachable!(
                    "{profile:?}: the change cannot settle while its save is paused: {outcome:?}"
                ),
                () = fixture.gate.entered() => {}
            }
            // The caller goes away while the save is in flight.
            drop(suppress);
            fixture.gate.release();

            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
            loop {
                let durable = fixture
                    .service
                    .load_committed_runtime_session_for_body(
                        &fixture.session_id,
                        "mcp intent cancellation poll",
                    )
                    .await
                    .ok()
                    .flatten();
                if durable.as_ref().and_then(suppressed_docs_intent)
                    == Some(meerkat_core::McpAttachmentIntentDisposition::SuppressedByLogout)
                {
                    break;
                }
                assert!(
                    std::time::Instant::now() < deadline,
                    "{profile:?}: the abandoned change was applied live but never settled durably"
                );
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
            }
            let live = fixture
                .service
                .export_session_with_labels(&fixture.session_id)
                .await
                .expect("live session stays");
            assert_eq!(
                suppressed_docs_intent(&live),
                suppressed_docs_intent(&fixture.durable_body().await),
                "{profile:?}: live and durable intents agree after settlement"
            );
        }
    }

    /// Dropping the caller after the durable commit but before actor sync cannot
    /// lose the terminal or admit a second identity rotation.
    #[tokio::test]
    async fn model_routing_terminal_commit_cancelled_after_durable_commit_still_reads_terminal() {
        for profile in TerminalCommitProfile::ALL {
            let fixture = CancellableTerminalCommitFixture::new(profile).await;
            fixture.gate.pause_after_commit();

            let mut commit = Box::pin(fixture.commit());
            tokio::select! {
                outcome = &mut commit => unreachable!(
                    "{profile:?}: the commit cannot finish while post-commit convergence is paused: {outcome:?}"
                ),
                () = fixture.gate.entered_after_commit() => {}
            }
            assert_eq!(
                fixture.durable_disposition().await,
                Some(ModelRoutingIntentRecordDisposition::Realized),
                "{profile:?}: durable authority must already carry the terminal"
            );
            assert_eq!(
                fixture.live_disposition().await,
                Some(ModelRoutingIntentRecordDisposition::Requested),
                "{profile:?}: the actor must still expose its committed predecessor before sync"
            );
            drop(commit);
            fixture.gate.release_after_commit();
            fixture
                .await_live_realized(&format!(
                    "{profile:?}: detached post-commit convergence did not update the actor"
                ))
                .await;

            assert_eq!(
                fixture.durable_disposition().await,
                Some(ModelRoutingIntentRecordDisposition::Realized),
                "{profile:?}: the next pre-dequeue must read the exact terminal, not a debt"
            );
            assert_eq!(
                fixture.live_disposition().await,
                Some(ModelRoutingIntentRecordDisposition::Realized),
            );

            // Converges instead of rotating a second time: the log carries
            // exactly one request and one terminal for it.
            let body = fixture.durable_body().await;
            assert_eq!(
                body.model_routing_control().records().len(),
                2,
                "{profile:?}: an unobserved commit must not be applied twice"
            );
            assert!(
                body.model_routing_control()
                    .awaiting_decision()
                    .next()
                    .is_none(),
                "{profile:?}: the realized request must no longer be owed"
            );
        }
    }

    /// A durable commit that fails must leave the request owed and must not
    /// expose the detached terminal through live state.
    #[tokio::test]
    async fn model_routing_terminal_commit_failure_leaves_the_request_owed_in_both_profiles() {
        for profile in TerminalCommitProfile::ALL {
            let fixture = CancellableTerminalCommitFixture::new(profile).await;
            fixture.gate.fail_commits(true);

            let error = fixture
                .commit()
                .await
                .expect_err("a failing durable commit must surface as an error");
            fixture.gate.fail_commits(false);

            assert_eq!(
                fixture.durable_disposition().await,
                Some(ModelRoutingIntentRecordDisposition::Requested),
                "{profile:?}: a failed commit must leave the request owed ({error})"
            );
            assert_ne!(
                fixture.live_disposition().await,
                Some(ModelRoutingIntentRecordDisposition::Realized),
                "{profile:?}: a failed commit must not strand the terminal in live state"
            );
            fixture
                .assert_no_live_only_terminal("after a failed commit")
                .await;
            assert_eq!(
                fixture
                    .durable_body()
                    .await
                    .model_routing_control()
                    .records()
                    .len(),
                1,
                "{profile:?}: a failed commit must not leave a partial terminal on disk"
            );
        }
    }

    /// Once the terminal is durable, an ordinary later persistence of the live
    /// session must not be able to roll it back. This is the regression the
    /// whole ordering exists to prevent: live is the thing that gets written,
    /// so if live could lag durable, the next boundary would erase the handoff.
    #[tokio::test]
    async fn a_committed_model_routing_terminal_cannot_be_regressed_by_a_later_persist() {
        for profile in TerminalCommitProfile::ALL {
            let fixture = CancellableTerminalCommitFixture::new(profile).await;
            if profile == TerminalCommitProfile::HeadCanonical {
                fixture
                    .service
                    .prepare_runtime_boundary(
                        &fixture.session_id,
                        "stale role-boundary regression seed",
                        None,
                    )
                    .await
                    .expect("prepare a predecessor HeadCanonical actor boundary");
            }
            fixture
                .commit()
                .await
                .unwrap_or_else(|error| unreachable!("{profile:?}: commit terminal: {error}"));
            assert_eq!(
                fixture.durable_disposition().await,
                Some(ModelRoutingIntentRecordDisposition::Realized)
            );

            // An ordinary full-session persistence, exactly like the one the
            // next turn boundary performs.
            fixture
                .service
                .persist_live_session_now(&fixture.session_id)
                .await
                .unwrap_or_else(|error| unreachable!("{profile:?}: ordinary persist: {error}"));

            assert_eq!(
                fixture.durable_disposition().await,
                Some(ModelRoutingIntentRecordDisposition::Realized),
                "{profile:?}: an ordinary persist regressed a committed handoff terminal"
            );
            assert_eq!(
                fixture
                    .durable_body()
                    .await
                    .model_routing_control()
                    .records()
                    .len(),
                2,
                "{profile:?}: an ordinary persist must not duplicate or drop handoff records"
            );
            let _ = &fixture.runtime_store;
        }
    }

