    /// A restarted process can have a durable non-terminal lifecycle row but no
    /// in-memory registration. Archive must reconstruct only as needed and
    /// converge the singular RuntimeStore lifecycle to Retired.
    #[tokio::test]
    async fn test_machine_authorized_archive_retires_cold_runtime_without_retaining_shell() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        );
        let session = Session::new();
        let id = session.id().clone();
        let runtime_id = PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&id);
        runtime_store
            .commit_session_snapshot(
                &runtime_id,
                SerializedSessionSnapshot {
                    session_snapshot: (serde_json::to_vec(&session)
                        .expect("serialize RuntimeStore body"))
                    .into(),
                },
            )
            .await
            .expect("seed RuntimeStore body");

        let before_restart = meerkat_runtime::MeerkatMachine::persistent(
            Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        )
        .expect("construct runtime authority");
        before_restart
            .prepare_bindings(id.clone())
            .await
            .expect("persist a live runtime binding before restart");
        let pre_restart_state =
            meerkat_runtime::store::load_runtime_state(runtime_store.as_ref(), &runtime_id)
                .await
                .expect("load pre-restart runtime lifecycle")
                .expect("binding preparation must persist runtime lifecycle authority");
        assert_ne!(pre_restart_state, meerkat_runtime::RuntimeState::Retired);
        drop(before_restart);

        let after_restart = meerkat_runtime::MeerkatMachine::persistent(
            Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        )
        .expect("construct runtime authority");
        assert!(
            !after_restart.contains_session(&id).await,
            "restart fixture must begin without a live runtime registration"
        );
        service
            .archive_with_machine_protocol(
                &id,
                MachineSessionArchiveProtocol::from_machine(&after_restart),
            )
            .await
            .expect("archive must converge the stored-only observation");

        assert_eq!(
            meerkat_runtime::store::load_runtime_state(runtime_store.as_ref(), &runtime_id)
                .await
                .expect("load post-archive runtime state"),
            Some(meerkat_runtime::RuntimeState::Retired),
            "archive must commit the singular RuntimeStore terminal"
        );
        assert!(
            !after_restart.contains_session(&id).await,
            "archive must not retain a process-local registration reconstructed from dead state"
        );
        assert!(
            store
                .load(&id)
                .await
                .expect("SessionStore probe should succeed")
                .is_none(),
            "archive must not persist a SessionStore terminal"
        );
    }

    /// A restarted runtime may carry a durable directed-terminal outbox but no
    /// live session task/executor. Archive must drain that exact outbox through
    /// its stored-only EventStore publisher before lifecycle retirement, and a
    /// failed append must retry without duplicating the interaction terminal.
    #[tokio::test]
    async fn test_machine_archive_drains_stored_only_pending_terminal_exactly_once() {
        struct InvalidReceiptArchiveTerminalPublisher;

        #[async_trait::async_trait]
        impl CoreExecutorPublicationHandle for InvalidReceiptArchiveTerminalPublisher {
            async fn publish_interaction_terminals(
                &self,
                _events: &[AgentEvent],
            ) -> Result<
                Vec<CoreInteractionTerminalPublicationReceipt>,
                meerkat_core::lifecycle::CoreExecutorError,
            > {
                // Terminalization has already committed the durable outbox.
                // Return a corrupt receipt set so convergence fails closed
                // without an unbounded retry, modeling a process cut with the
                // unpublished carrier left for restart recovery.
                Ok(Vec::new())
            }
        }

        struct ArchiveFixtureExecutor {
            publisher: Arc<InvalidReceiptArchiveTerminalPublisher>,
        }

        #[async_trait::async_trait]
        impl meerkat_core::lifecycle::CoreExecutor for ArchiveFixtureExecutor {
            fn publication_handle(&self) -> Option<Arc<dyn CoreExecutorPublicationHandle>> {
                Some(Arc::clone(&self.publisher) as Arc<_>)
            }

            async fn apply(
                &mut self,
                _run_id: RunId,
                _primitive: meerkat_core::lifecycle::run_primitive::RunPrimitive,
            ) -> Result<
                meerkat_core::lifecycle::core_executor::CoreApplyOutput,
                meerkat_core::lifecycle::CoreExecutorError,
            > {
                Err(meerkat_core::lifecycle::CoreExecutorError::Internal(
                    "archive fixture input must remain queued until stop".to_string(),
                ))
            }

            async fn cancel_after_boundary(
                &mut self,
                _reason: String,
            ) -> Result<(), meerkat_core::lifecycle::CoreExecutorError> {
                Ok(())
            }

            async fn stop_runtime_executor(
                &mut self,
                _reason: String,
            ) -> Result<(), meerkat_core::lifecycle::CoreExecutorError> {
                Ok(())
            }
        }

        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let event_store = Arc::new(RecordingEventStore::default());
        let event_store_trait: Arc<dyn EventStore> = event_store.clone();
        let projection_dir = tempfile::tempdir().expect("projection tempdir");
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        )
        .with_event_projection(
            event_store_trait,
            Arc::new(SessionProjector::new(projection_dir.path().join(".rkat"))),
        );
        let session = Session::new();
        let id = session.id().clone();
        let runtime_id = PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&id);
        let body_bytes = serde_json::to_vec(&session).expect("serialize RuntimeStore body");
        runtime_store
            .commit_session_snapshot(
                &runtime_id,
                SerializedSessionSnapshot {
                    session_snapshot: body_bytes.clone().into(),
                },
            )
            .await
            .expect("seed RuntimeStore body");

        let before_restart = Arc::new(
            meerkat_runtime::MeerkatMachine::persistent(
                Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
                memory_blob_store(),
            )
            .expect("construct runtime authority"),
        );
        before_restart
            .prepare_bindings(id.clone())
            .await
            .expect("prepare durable runtime authority");
        before_restart
            .ensure_session_with_executor(
                id.clone(),
                Box::new(ArchiveFixtureExecutor {
                    publisher: Arc::new(InvalidReceiptArchiveTerminalPublisher),
                }),
            )
            .await
            .expect("attach exact publication capability before directed admission");
        let stable_input_id = InputId::new().0;
        let directed = meerkat_runtime::mob_adapter::create_tracked_flow_step_input(
            "archive-terminal-step",
            ContentInput::Text("pending directed archive work".to_string()),
            "archive-terminal-flow",
            None,
            &stable_input_id.to_string(),
        )
        .expect("build tracked directed input");
        let accepted = before_restart
            .accept_input_without_wake(&id, directed)
            .await
            .expect("admit the directed input");
        assert!(accepted.is_accepted(), "directed input should be queued");
        let stop_error = before_restart
            .stop_runtime_executor(&id, "archive fixture stop")
            .await
            .expect_err("invalid exact receipts must leave the durable outbox pending");
        assert!(
            stop_error
                .to_string()
                .contains("publication receipts did not exactly match finalized outbox batch"),
            "unexpected stop failure: {stop_error}"
        );
        drop(before_restart);

        let after_restart = meerkat_runtime::MeerkatMachine::persistent(
            Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        )
        .expect("construct runtime authority");
        event_store.fail_appends();
        let first_archive_error = service
            .archive_with_machine_protocol(
                &id,
                MachineSessionArchiveProtocol::from_machine(&after_restart),
            )
            .await
            .expect_err("failed exact append must fail archive before lifecycle retirement");
        assert!(
            matches!(
                first_archive_error,
                SessionError::FailedWithData { ref data, .. }
                    if data.get("kind").and_then(serde_json::Value::as_str)
                        == Some("runtime_retirement_in_progress")
                        && data.get("stage").and_then(serde_json::Value::as_str)
                            == Some("terminal_publication")
                        && data.get("retryable").and_then(serde_json::Value::as_bool)
                            == Some(true)
                        && data.get("authority_retained").and_then(serde_json::Value::as_bool)
                            == Some(true)
            ),
            "unexpected first archive error: {first_archive_error}"
        );
        let still_active = runtime_store
            .load_session_snapshot(&runtime_id)
            .await
            .expect("load body after failed archive")
            .expect("RuntimeStore body remains present");
        assert_eq!(
            still_active.as_slice(),
            body_bytes.as_slice(),
            "pending-terminal publication failure must preserve body authority"
        );
        assert_eq!(
            meerkat_runtime::store::load_runtime_state(runtime_store.as_ref(), &runtime_id)
                .await
                .expect("load committed lifecycle after failed drain"),
            Some(RuntimeState::Retired),
            "the original stop transaction must retain its committed Retired authority while terminal publication remains pending"
        );

        event_store.allow_appends();
        let converged_retry = service
            .archive_with_machine_protocol(
                &id,
                MachineSessionArchiveProtocol::from_machine(&after_restart),
            )
            .await;
        assert!(
            matches!(converged_retry, Err(SessionError::NotFound { id: ref missing }) if missing == &id),
            "after stored-only publication converges, the already-Retired runtime must keep the duplicate-archive NotFound contract: {converged_retry:?}"
        );
        assert_eq!(
            meerkat_runtime::store::load_runtime_state(runtime_store.as_ref(), &runtime_id)
                .await
                .expect("load lifecycle after successful drain"),
            Some(RuntimeState::Retired),
            "successful archive retry must commit the RuntimeStore lifecycle terminal"
        );

        let rows = event_store
            .read_from(&id, 1)
            .await
            .expect("read exact terminal rows");
        let interaction_id = meerkat_core::interaction::InteractionId(stable_input_id);
        let exact_rows: Vec<_> = rows
            .iter()
            .filter(|row| {
                matches!(
                    row.source,
                    meerkat_core::event::EventSourceIdentity::Interaction {
                        interaction_id: source_id
                    } if source_id == interaction_id
                )
            })
            .collect();
        assert_eq!(
            exact_rows.len(),
            1,
            "archive retry must append exactly once"
        );
        assert!(matches!(
            &exact_rows[0].event,
            AgentEvent::InteractionFailed {
                interaction_id: emitted_id,
                reason: meerkat_core::event::InteractionFailureReason::Abandoned { detail },
            } if *emitted_id == interaction_id && detail == "runtime stopped"
        ));

        let duplicate = service
            .archive_with_machine_protocol(
                &id,
                MachineSessionArchiveProtocol::from_machine(&after_restart),
            )
            .await;
        assert!(
            matches!(duplicate, Err(SessionError::NotFound { .. })),
            "fully converged duplicate archive keeps the NotFound contract: {duplicate:?}"
        );
        assert_eq!(
            event_store
                .read_from(&id, 1)
                .await
                .expect("read rows after duplicate archive")
                .iter()
                .filter(|row| {
                    matches!(
                        row.source,
                        meerkat_core::event::EventSourceIdentity::Interaction {
                            interaction_id: source_id
                        } if source_id == interaction_id
                    )
                })
                .count(),
            1,
            "duplicate archive must not duplicate the exact interaction terminal"
        );
    }

    /// Live Destroyed is already a quiescent RuntimeStore terminal. Duplicate
