    #[tokio::test]
    async fn exact_terminal_batch_sequences_once_broadcasts_inserts_and_silences_replay() {
        use futures::StreamExt;
        use meerkat_core::event::InteractionFailureReason;

        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let event_store = Arc::new(RecordingEventStore::default());
        let event_store_trait: Arc<dyn EventStore> = event_store.clone();
        let dir = tempfile::tempdir().expect("tempdir");
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        )
        .with_event_projection(
            event_store_trait,
            Arc::new(SessionProjector::new(dir.path().join(".rkat"))),
        );
        let created = service
            .create_session(create_request_with_metadata(
                "hello",
                InitialTurnPolicy::Defer,
            ))
            .await
            .expect("create session");
        let session_id = created.session_id;
        let actor_witness = service
            .live_session_actor_witness(&session_id)
            .await
            .expect("exact terminal actor remains live");
        let mut stream = service
            .subscribe_session_events(&session_id)
            .await
            .expect("subscribe exact terminal stream");
        let ids = [
            meerkat_core::interaction::InteractionId(meerkat_core::time_compat::new_uuid_v7()),
            meerkat_core::interaction::InteractionId(meerkat_core::time_compat::new_uuid_v7()),
            meerkat_core::interaction::InteractionId(meerkat_core::time_compat::new_uuid_v7()),
        ];
        let terminals = vec![
            AgentEvent::InteractionComplete {
                interaction_id: ids[0],
                result: "done".to_string(),
                structured_output: None,
            },
            AgentEvent::InteractionCallbackPending {
                interaction_id: ids[1],
                tool_name: "external".to_string(),
                args: serde_json::json!({"value": 1}),
                pending_tool_calls: Vec::new(),
            },
            AgentEvent::InteractionFailed {
                interaction_id: ids[2],
                reason: InteractionFailureReason::Cancelled,
            },
        ];

        let first_receipts = service
            .publish_interaction_terminals_exact_batch_for_actor(&actor_witness, &terminals)
            .await
            .expect("publish exact terminal batch");
        assert_eq!(
            first_receipts
                .iter()
                .map(|receipt| receipt.interaction_id())
                .collect::<Vec<_>>(),
            ids
        );
        let mut published = Vec::new();
        for _ in 0..terminals.len() {
            published.push(
                tokio::time::timeout(std::time::Duration::from_secs(2), stream.next())
                    .await
                    .expect("exact terminal broadcast timeout")
                    .expect("exact terminal stream closed"),
            );
        }
        assert_eq!(
            published
                .iter()
                .map(|envelope| match &envelope.payload {
                    AgentEvent::InteractionComplete { interaction_id, .. }
                    | AgentEvent::InteractionCallbackPending { interaction_id, .. }
                    | AgentEvent::InteractionFailed { interaction_id, .. } => *interaction_id,
                    other => panic!("unexpected batch broadcast: {other:?}"),
                })
                .collect::<Vec<_>>(),
            ids
        );
        assert_eq!(published[1].seq, published[0].seq + 1);
        assert_eq!(published[2].seq, published[1].seq + 1);

        let replay_receipts = service
            .publish_interaction_terminals_exact_batch_for_actor(&actor_witness, &terminals)
            .await
            .expect("replay exact terminal batch");
        assert_eq!(replay_receipts, first_receipts);
        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(100), stream.next())
                .await
                .is_err(),
            "canonical replay must not rebroadcast already-published terminals"
        );

        let next_id =
            meerkat_core::interaction::InteractionId(meerkat_core::time_compat::new_uuid_v7());
        let next_terminal = [AgentEvent::InteractionComplete {
            interaction_id: next_id,
            result: "next".to_string(),
            structured_output: None,
        }];
        service
            .publish_interaction_terminals_exact_batch_for_actor(&actor_witness, &next_terminal)
            .await
            .expect("publish terminal after replay");
        let next = tokio::time::timeout(std::time::Duration::from_secs(2), stream.next())
            .await
            .expect("next terminal broadcast timeout")
            .expect("exact terminal stream closed");
        assert_eq!(next.seq, published[2].seq + 1);
        assert!(matches!(
            next.payload,
            AgentEvent::InteractionComplete { interaction_id, .. } if interaction_id == next_id
        ));

        let rows = event_store
            .read_from(&session_id, 0)
            .await
            .expect("read exact terminal rows");
        let interaction_rows = rows
            .iter()
            .filter(|row| {
                matches!(
                    row.event,
                    AgentEvent::InteractionComplete { .. }
                        | AgentEvent::InteractionCallbackPending { .. }
                        | AgentEvent::InteractionFailed { .. }
                )
            })
            .count();
        assert_eq!(
            interaction_rows, 4,
            "replay must not duplicate durable rows"
        );
    }

    #[tokio::test]
    async fn stored_only_archive_publisher_refuses_a_live_successor_actor() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let event_store = Arc::new(RecordingEventStore::default());
        let event_store_trait: Arc<dyn EventStore> = event_store.clone();
        let dir = tempfile::tempdir().expect("tempdir");
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        )
        .with_event_projection(
            event_store_trait,
            Arc::new(SessionProjector::new(dir.path().join(".rkat"))),
        );
        let created = service
            .create_session(create_request_with_metadata(
                "live successor",
                InitialTurnPolicy::Defer,
            ))
            .await
            .expect("create live successor actor");
        let session_id = created.session_id;
        let recovery_gate = service.recovery_gate_for_session(&session_id).await;
        let publisher = StoredOnlyTerminalPublisher {
            inner: Arc::clone(&service.inner),
            session_id: session_id.clone(),
            recovery_gate,
            event_store: service.event_store.clone(),
            event_projection_faults: Arc::clone(&service.event_projection_faults),
            event_projection_drains: Arc::clone(&service.event_projection_drains),
        };
        let interaction_id =
            meerkat_core::interaction::InteractionId(meerkat_core::time_compat::new_uuid_v7());
        let event = AgentEvent::InteractionComplete {
            interaction_id,
            result: "must not cross into the successor actor".to_string(),
            structured_output: None,
        };

        let error = publisher
            .publish_interaction_terminals(std::slice::from_ref(&event))
            .await
            .expect_err("stored-only publisher must reject a live successor actor");
        assert!(
            error
                .to_string()
                .contains("stored-only terminal publisher refused live session"),
            "unexpected stored-only successor refusal: {error:?}"
        );
        let rows = event_store
            .read_from(&session_id, 0)
            .await
            .expect("read event rows after stored-only refusal");
        assert!(
            rows.iter().all(|row| {
                !matches!(
                    row.source,
                    meerkat_core::event::EventSourceIdentity::Interaction {
                        interaction_id: source_id
                    } if source_id == interaction_id
                )
            }),
            "stored-only predecessor publication must not append into a live successor actor"
        );
    }

    /// A stored-only publisher in a service where an earlier actor of the
    /// session left numbers on the session's event line that it allocated
    /// but never published: the publisher reconciles the line with the
    /// durable tail, reserves its batch from the line and appends above every
    /// number the line holds, the line ends at that row, and the next
    /// allocation in the same service (a later actor's) lands strictly beyond
    /// it. A replay of the same publication inserts nothing, and the line
    /// neither regresses nor moves past the canonical rows.
    #[tokio::test]
    async fn stored_only_publication_allocates_from_the_services_event_line() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let event_store = Arc::new(RecordingEventStore::default());
        let event_store_trait: Arc<dyn EventStore> = event_store.clone();
        let dir = tempfile::tempdir().expect("tempdir");
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        )
        .with_event_projection(
            Arc::clone(&event_store_trait),
            Arc::new(SessionProjector::new(dir.path().join(".rkat"))),
        );
        let created = service
            .create_session(create_request_with_metadata(
                "earlier actor",
                InitialTurnPolicy::Defer,
            ))
            .await
            .expect("create the earlier actor");
        let session_id = created.session_id;
        let actor_witness = service
            .live_session_actor_witness(&session_id)
            .await
            .expect("the earlier actor is live");
        let live_terminal = [AgentEvent::InteractionComplete {
            interaction_id: meerkat_core::interaction::InteractionId(
                meerkat_core::time_compat::new_uuid_v7(),
            ),
            result: "published by the earlier actor".to_string(),
            structured_output: None,
        }];
        service
            .publish_interaction_terminals_exact_batch_for_actor(&actor_witness, &live_terminal)
            .await
            .expect("the earlier actor publishes");
        // The earlier actor allocated numbers it never published.
        const UNUSED: u64 = 5;
        let line = service
            .inner
            .stored_only_event_line(&session_id, None)
            .await;
        let allocated_before = line.reserve(UNUSED) + UNUSED;
        assert_eq!(line.allocated(), allocated_before);
        service
            .discard_live_session(&session_id)
            .await
            .expect("the earlier actor is removed");

        let publisher = StoredOnlyTerminalPublisher {
            inner: Arc::clone(&service.inner),
            session_id: session_id.clone(),
            recovery_gate: service.recovery_gate_for_session(&session_id).await,
            event_store: service.event_store.clone(),
            event_projection_faults: Arc::clone(&service.event_projection_faults),
            event_projection_drains: Arc::clone(&service.event_projection_drains),
        };
        let stored_only_id =
            meerkat_core::interaction::InteractionId(meerkat_core::time_compat::new_uuid_v7());
        let stored_only = [AgentEvent::InteractionFailed {
            interaction_id: stored_only_id,
            reason: meerkat_core::event::InteractionFailureReason::Cancelled,
        }];
        let receipts = publisher
            .publish_interaction_terminals(&stored_only)
            .await
            .expect("the stored-only terminal publishes");
        let stored_row = |rows: &[StoredEvent]| {
            rows.iter()
                .find(|row| {
                    matches!(
                        row.source,
                        meerkat_core::event::EventSourceIdentity::Interaction { interaction_id }
                            if interaction_id == stored_only_id
                    )
                })
                .map(|row| row.stream_seq)
                .expect("the stored-only row")
        };
        let rows = event_store
            .read_from(&session_id, 0)
            .await
            .expect("read the event log");
        let stored_seq = stored_row(&rows);
        assert_eq!(
            stored_seq,
            allocated_before + 1,
            "the stored-only row lands above every number the line holds"
        );
        assert!(
            rows.iter()
                .filter(|row| row.stream_seq != stored_seq)
                .all(|row| row.stream_seq < stored_seq),
            "the stored-only row is above every durable row"
        );
        assert_eq!(
            line.allocated(),
            stored_seq,
            "the line ends at the stored row"
        );

        let replayed = publisher
            .publish_interaction_terminals(&stored_only)
            .await
            .expect("the same publication replays");
        assert_eq!(replayed, receipts);
        let rows_after_replay = event_store
            .read_from(&session_id, 0)
            .await
            .expect("read the event log again");
        assert_eq!(
            rows_after_replay.len(),
            rows.len(),
            "a replay inserts nothing"
        );
        assert_eq!(
            line.allocated(),
            stored_seq,
            "a replay neither regresses the line nor moves it past the canonical rows"
        );

        // The next allocation in this service (a later actor of the session
        // allocates from the same line) lands strictly beyond the stored row.
        let next = line.reserve(1) + 1;
        assert!(next > stored_seq);
    }

    /// A fresh service over the same stores creates the session's event line
    /// from the durable stream tail, which already covers the stored-only
    /// rows: its first allocation lands strictly beyond them.
    #[tokio::test]
    async fn a_fresh_service_starts_the_event_line_above_stored_only_rows() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let event_store = Arc::new(RecordingEventStore::default());
        let event_store_trait: Arc<dyn EventStore> = event_store.clone();
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let dir = tempfile::tempdir().expect("tempdir");
        let service = |label: &str| {
            PersistentSessionService::new(
                DummyBuilder,
                4,
                Arc::clone(&store),
                runtime_store.clone(),
                memory_blob_store(),
            )
            .with_event_projection(
                Arc::clone(&event_store_trait),
                Arc::new(SessionProjector::new(dir.path().join(label))),
            )
        };
        let first = service("first");
        let created = first
            .create_session(create_request_with_metadata(
                "stored-only rows",
                InitialTurnPolicy::Defer,
            ))
            .await
            .expect("create the session");
        let session_id = created.session_id;
        first
            .discard_live_session(&session_id)
            .await
            .expect("no actor is hosted");
        let publisher = StoredOnlyTerminalPublisher {
            inner: Arc::clone(&first.inner),
            session_id: session_id.clone(),
            recovery_gate: first.recovery_gate_for_session(&session_id).await,
            event_store: first.event_store.clone(),
            event_projection_faults: Arc::clone(&first.event_projection_faults),
            event_projection_drains: Arc::clone(&first.event_projection_drains),
        };
        let terminals = [
            AgentEvent::InteractionComplete {
                interaction_id: meerkat_core::interaction::InteractionId(
                    meerkat_core::time_compat::new_uuid_v7(),
                ),
                result: String::new(),
                structured_output: None,
            },
            AgentEvent::InteractionFailed {
                interaction_id: meerkat_core::interaction::InteractionId(
                    meerkat_core::time_compat::new_uuid_v7(),
                ),
                reason: meerkat_core::event::InteractionFailureReason::Cancelled,
            },
        ];
        publisher
            .publish_interaction_terminals(&terminals)
            .await
            .expect("the stored-only rows publish");
        let durable_tail = event_store
            .read_from(&session_id, 0)
            .await
            .expect("read the event log")
            .iter()
            .map(|row| row.stream_seq)
            .max()
            .expect("the stored-only rows are durable");

        let fresh = service("fresh");
        let line = fresh.inner.stored_only_event_line(&session_id, None).await;
        assert_eq!(
            line.allocated(),
            durable_tail,
            "the fresh service's line starts at the durable tail"
        );
        let next = line.reserve(1) + 1;
        assert!(next > durable_tail);
    }

    /// The non-waiting turn boundary lease and controller pin: while the
    /// boundary is held (as a running turn holds it) both answer at once that
    /// it is held and ask nothing of the actor; once it is free the lease is
    /// taken for the exact actor and the pin reaches it; an actor that is no
    /// longer current gets no lease.
    #[tokio::test]
    async fn try_lease_answers_busy_while_the_turn_boundary_is_held_and_leases_when_free() {
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::new(MemoryStore::new()),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        );
        let actor_slot = LiveSessionActorWitnessSlot::default();
        let admission = service
            .reserve_create_session_admission()
            .await
            .expect("reserve admission");
        let session_id = service
            .create_session_with_reserved_admission_and_actor_witness(
                create_request_with_metadata("member", InitialTurnPolicy::Defer),
                admission,
                &actor_slot,
            )
            .await
            .expect("create member")
            .session_id;
        let actor = actor_slot.witness().expect("exact witness");

        let held = service
            .acquire_runtime_turn_finalization_guard(&session_id)
            .await;
        let busy = tokio::time::timeout(
            std::time::Duration::from_secs(2),
            service.try_acquire_live_session_actor_turn_boundary_lease_exact(&actor),
        )
        .await
        .expect("a held boundary is never waited for");
        assert!(matches!(busy, Err(crate::TurnBoundaryHeld)));
        let pin = tokio::time::timeout(
            std::time::Duration::from_secs(2),
            service.try_pin_controller_client_for_actor(&actor),
        )
        .await
        .expect("a held boundary is never waited for");
        assert!(matches!(
            pin,
            Err(crate::TryPinControllerError::TurnBoundaryHeld)
        ));
        drop(held);

        let lease = service
            .try_acquire_live_session_actor_turn_boundary_lease_exact(&actor)
            .await
            .expect("a free boundary is taken")
            .expect("the exact current actor");
        assert!(lease.witness() == &actor);
        drop(lease);
        let pin = tokio::time::timeout(
            std::time::Duration::from_secs(2),
            service.try_pin_controller_client_for_actor(&actor),
        )
        .await
        .expect("a free boundary is never waited for");
        assert!(
            !matches!(pin, Err(crate::TryPinControllerError::TurnBoundaryHeld)),
            "a free boundary reaches the actor"
        );

        let lease = service
            .acquire_live_session_actor_turn_boundary_lease(&session_id)
            .await
            .expect("hold the boundary to discard");
        assert!(
            service
                .discard_live_session_actor(&lease)
                .await
                .expect("discard the exact actor")
        );
        drop(lease);
        assert!(
            service
                .try_acquire_live_session_actor_turn_boundary_lease_exact(&actor)
                .await
                .expect("a free boundary is taken")
                .is_none(),
            "an actor that is no longer current gets no lease"
        );
    }

    /// The live MCP attachment entry reaches only the exact current actor:
    /// the current actor's own agent answers (this dummy agent has no live
    /// attachment surface); a member whose turn boundary is held refuses a
    /// lease-free call at once as Busy instead of waiting on itself; and the
    /// lease of an actor discarded meanwhile refuses as not current.
    #[tokio::test]
    async fn live_mcp_attachment_reaches_only_the_exact_actor_and_never_waits_on_itself() {
        use meerkat_core::mcp_attachment::{
            LiveMcpAttachError, LiveMcpAttachment, McpAttachmentAuthority, McpAttachmentRefusal,
        };
        use meerkat_core::mcp_config::{McpScope, McpServerConfig};

        struct Control(McpServerConfig);
        impl McpAttachmentAuthority for Control {
            fn server(&self) -> &McpServerConfig {
                &self.0
            }
            fn authorize_apply(&self) -> Result<(), McpAttachmentRefusal> {
                Ok(())
            }
            fn authorize_persist(&self, _: McpScope) -> Result<(), McpAttachmentRefusal> {
                Err(McpAttachmentRefusal::Denied)
            }
        }
        let attachment = || {
            let server = McpServerConfig::stdio(
                "first",
                "true",
                Vec::new(),
                std::collections::HashMap::new(),
            );
            LiveMcpAttachment {
                control: Arc::new(Control(server.clone())),
                server,
                persist: None,
            }
        };

        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::new(MemoryStore::new()),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        );
        let actor_slot = LiveSessionActorWitnessSlot::default();
        let admission = service
            .reserve_create_session_admission()
            .await
            .expect("reserve admission");
        let session_id = service
            .create_session_with_reserved_admission_and_actor_witness(
                create_request_with_metadata("member", InitialTurnPolicy::Defer),
                admission,
                &actor_slot,
            )
            .await
            .expect("create member")
            .session_id;
        let actor = actor_slot.witness().expect("exact witness");

        let lease = service
            .acquire_live_session_actor_turn_boundary_lease_exact(&actor)
            .await
            .expect("boundary")
            .expect("exact actor");
        assert_eq!(
            service
                .attach_live_mcp_server(lease, attachment())
                .await
                .map(|receipt| receipt.outcome),
            Err(LiveMcpAttachError::Unsupported),
            "the exact current actor's own agent answered"
        );

        let held = service
            .acquire_live_session_actor_turn_boundary_lease(&session_id)
            .await
            .expect("hold the turn boundary");
        let busy = tokio::time::timeout(
            std::time::Duration::from_secs(2),
            service.try_attach_live_mcp_server(&session_id, attachment()),
        )
        .await
        .expect("a lease-free call never waits on a held boundary");
        assert_eq!(
            busy.map(|receipt| receipt.outcome),
            Err(LiveMcpAttachError::Busy)
        );

        assert!(
            service
                .discard_live_session_actor(&held)
                .await
                .expect("discard the exact actor")
        );
        assert_eq!(
            service
                .attach_live_mcp_server(held, attachment())
                .await
                .map(|receipt| receipt.outcome),
            Err(LiveMcpAttachError::Refused(
                McpAttachmentRefusal::NotCurrent
            )),
            "a discarded actor's lease reaches nothing"
        );
    }

    fn live_mcp_race_attachment() -> meerkat_core::mcp_attachment::LiveMcpAttachment {
        use meerkat_core::mcp_attachment::{McpAttachmentAuthority, McpAttachmentRefusal};
        use meerkat_core::mcp_config::{McpScope, McpServerConfig};

        struct Control(McpServerConfig);
        impl McpAttachmentAuthority for Control {
            fn server(&self) -> &McpServerConfig {
                &self.0
            }
            fn authorize_apply(&self) -> Result<(), McpAttachmentRefusal> {
                Ok(())
            }
            fn authorize_persist(&self, _: McpScope) -> Result<(), McpAttachmentRefusal> {
                Err(McpAttachmentRefusal::Denied)
            }
        }
        let server = McpServerConfig::stdio(
            "raced",
            "true",
            Vec::new(),
            std::collections::HashMap::new(),
        );
        meerkat_core::mcp_attachment::LiveMcpAttachment {
            control: Arc::new(Control(server.clone())),
            server,
            persist: None,
        }
    }

    async fn live_mcp_race_member(
        service: &PersistentSessionService<DummyBuilder>,
    ) -> (SessionId, LiveSessionActorWitness) {
        let slot = LiveSessionActorWitnessSlot::default();
        let admission = service
            .reserve_create_session_admission()
            .await
            .expect("reserve admission");
        let session_id = service
            .create_session_with_reserved_admission_and_actor_witness(
                create_request_with_metadata("member", InitialTurnPolicy::Defer),
                admission,
                &slot,
            )
            .await
            .expect("create member")
            .session_id;
        (session_id, slot.witness().expect("exact witness"))
    }

    fn live_mcp_race_service() -> Arc<PersistentSessionService<DummyBuilder>> {
        Arc::new(PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::new(MemoryStore::new()),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        ))
    }

    /// Effect entry: while the member's agent is inside the attachment
    /// effect, the consumed turn boundary and the recovery gate are both
    /// held, so a lease-free attach is Busy and no recovery can interleave;
    /// both are released only when the effect settles.
    #[tokio::test]
    async fn live_mcp_attachment_holds_boundary_and_recovery_through_the_effect() {
        use meerkat_core::mcp_attachment::{LiveMcpAttachError, McpAttachmentOutcome};
        let service = live_mcp_race_service();
        let (session_id, actor) = live_mcp_race_member(&service).await;
        let probe = probe_attach(&session_id, true);

        let lease = service
            .acquire_live_session_actor_turn_boundary_lease_exact(&actor)
            .await
            .expect("boundary")
            .expect("exact actor");
        let attaching = tokio::spawn({
            let service = Arc::clone(&service);
            async move {
                service
                    .attach_live_mcp_server(lease, live_mcp_race_attachment())
                    .await
            }
        });
        probe.entered.acquire().await.expect("entered").forget();

        assert_eq!(
            service
                .try_attach_live_mcp_server(&session_id, live_mcp_race_attachment())
                .await
                .map(|receipt| receipt.outcome),
            Err(LiveMcpAttachError::Busy),
            "the effect still holds the turn boundary"
        );
        assert!(
            service
                .recovery_gate_for_session(&session_id)
                .await
                .try_lock()
                .is_err(),
            "the effect still holds the recovery gate"
        );

        probe.release.add_permits(1);
        assert_eq!(
            attaching
                .await
                .expect("attach task")
                .map(|receipt| receipt.outcome),
            Ok(McpAttachmentOutcome {
                persisted: false,
                staged: true,
            })
        );
        assert!(
            service
                .recovery_gate_for_session(&session_id)
                .await
                .try_lock()
                .is_ok(),
            "the recovery gate is free once the effect settled"
        );
        probe.gated.store(false, Ordering::SeqCst);
        assert!(
            service
                .try_attach_live_mcp_server(&session_id, live_mcp_race_attachment())
                .await
                .is_ok(),
            "the boundary is free again"
        );
    }

    /// Waiter cancel: a caller that goes away while the effect runs does not
    /// release the boundary or the recovery gate early; the effect runs to
    /// its end under them, exactly once, and only then are they released.
    #[tokio::test]
    async fn a_cancelled_attach_waiter_keeps_custody_until_the_effect_settles() {
        use meerkat_core::mcp_attachment::LiveMcpAttachError;
        let service = live_mcp_race_service();
        let (session_id, actor) = live_mcp_race_member(&service).await;
        let probe = probe_attach(&session_id, true);

        let lease = service
            .acquire_live_session_actor_turn_boundary_lease_exact(&actor)
            .await
            .expect("boundary")
            .expect("exact actor");
        let waiter = tokio::spawn({
            let service = Arc::clone(&service);
            async move {
                service
                    .attach_live_mcp_server(lease, live_mcp_race_attachment())
                    .await
            }
        });
        probe.entered.acquire().await.expect("entered").forget();
        waiter.abort();
        assert!(waiter.await.is_err(), "the waiter is gone");

        assert_eq!(
            service
                .try_attach_live_mcp_server(&session_id, live_mcp_race_attachment())
                .await
                .map(|receipt| receipt.outcome),
            Err(LiveMcpAttachError::Busy),
            "the boundary stays held after the waiter left"
        );
        assert!(
            service
                .recovery_gate_for_session(&session_id)
                .await
                .try_lock()
                .is_err(),
            "the recovery gate stays held after the waiter left"
        );
        assert_eq!(probe.completed.load(Ordering::SeqCst), 0);

        probe.release.add_permits(1);
        tokio::time::timeout(std::time::Duration::from_secs(10), async {
            loop {
                if probe.completed.load(Ordering::SeqCst) == 1
                    && service
                        .recovery_gate_for_session(&session_id)
                        .await
                        .try_lock()
                        .is_ok()
                {
                    break;
                }
                tokio::time::sleep(std::time::Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("the effect settles once and releases its custody");
        assert_eq!(probe.completed.load(Ordering::SeqCst), 1, "exactly once");
    }

    /// Discard and redrive: a discard of the attaching actor waits behind
    /// the running effect instead of interleaving with it; after the discard
    /// and a redrive of the same session, the predecessor's witness reaches
    /// nothing and a new attachment reaches only the successor.
    ///
    /// Abnormal loss is distinct and not exercised here: losing the detached
    /// effect task's channel answers `Refused(Unavailable)`, while losing the
    /// inner actor's reply (or a command buffered at shutdown) answers
    /// `Refused(NotCurrent)`.
    #[tokio::test]
    async fn a_discard_waits_for_the_attachment_and_a_redrive_admits_only_the_successor() {
        use meerkat_core::mcp_attachment::McpAttachmentOutcome;
        let service = live_mcp_race_service();
        let (session_id, actor_a) = live_mcp_race_member(&service).await;
        let probe = probe_attach(&session_id, true);
        let session = service
            .export_live_session(&session_id)
            .await
            .expect("export for the redrive");

        let lease = service
            .acquire_live_session_actor_turn_boundary_lease_exact(&actor_a)
            .await
            .expect("boundary")
            .expect("exact actor");
        let attaching = tokio::spawn({
            let service = Arc::clone(&service);
            async move {
                service
                    .attach_live_mcp_server(lease, live_mcp_race_attachment())
                    .await
            }
        });
        probe.entered.acquire().await.expect("entered").forget();

        // The discard's own boundary acquisition is actually polled, and is
        // still pending after repeated polls while the effect is held: an
        // acknowledgement from the acquisition itself, not an inference from
        // an unscheduled task.
        let (polled_tx, polled_rx) = tokio::sync::oneshot::channel();
        let discarding = tokio::spawn({
            let service = Arc::clone(&service);
            let actor_a = actor_a.clone();
            async move {
                let acquire =
                    service.acquire_live_session_actor_turn_boundary_lease_exact(&actor_a);
                tokio::pin!(acquire);
                let mut pending_polls = 0usize;
                let acquired = loop {
                    match futures::poll!(acquire.as_mut()) {
                        std::task::Poll::Ready(acquired) => break Some(acquired),
                        std::task::Poll::Pending if pending_polls == 50 => break None,
                        std::task::Poll::Pending => {
                            pending_polls += 1;
                            tokio::task::yield_now().await;
                        }
                    }
                };
                let _ = polled_tx.send(acquired.is_none());
                let acquired = match acquired {
                    Some(acquired) => acquired,
                    None => acquire.await,
                };
                let boundary = acquired
                    .expect("boundary")
                    .expect("actor A is still current when the effect settles");
                service
                    .discard_live_session_actor(&boundary)
                    .await
                    .expect("discard actor A")
            }
        });
        assert!(
            polled_rx
                .await
                .expect("the discard reported its acquisition"),
            "the discard's boundary acquisition stays pending behind the running effect"
        );
        assert_eq!(probe.completed.load(Ordering::SeqCst), 0);

        probe.release.add_permits(1);
        assert_eq!(
            attaching
                .await
                .expect("attach task")
                .map(|receipt| receipt.outcome),
            Ok(McpAttachmentOutcome {
                persisted: false,
                staged: true,
            }),
            "the effect settled on actor A before the discard"
        );
        assert!(discarding.await.expect("discard task"), "actor A discarded");

        let slot = LiveSessionActorWitnessSlot::default();
        let admission = service
            .reserve_create_session_admission()
            .await
            .expect("reserve redrive admission");
        service
            .create_session_with_reserved_admission_and_actor_witness(
                resume_request(session),
                admission,
                &slot,
            )
            .await
            .expect("redrive the same session");
        let actor_b = slot.witness().expect("successor witness");
        assert_ne!(actor_a, actor_b);

        assert!(
            service
                .acquire_live_session_actor_turn_boundary_lease_exact(&actor_a)
                .await
                .expect("boundary")
                .is_none(),
            "the predecessor's witness reaches no actor"
        );
        probe.gated.store(false, Ordering::SeqCst);
        let lease_b = service
            .acquire_live_session_actor_turn_boundary_lease_exact(&actor_b)
            .await
            .expect("boundary")
            .expect("successor is exact");
        assert!(
            service
                .attach_live_mcp_server(lease_b, live_mcp_race_attachment())
                .await
                .is_ok(),
            "the successor's own agent attaches"
        );
        assert_eq!(probe.completed.load(Ordering::SeqCst), 2);
    }

    #[tokio::test]
    async fn exact_terminal_batch_rejects_predecessor_actor_and_publishes_through_successor() {
        use futures::StreamExt;

        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let event_store = Arc::new(RecordingEventStore::default());
        let event_store_trait: Arc<dyn EventStore> = event_store;
        let dir = tempfile::tempdir().expect("tempdir");
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        )
        .with_event_projection(
            event_store_trait,
            Arc::new(SessionProjector::new(dir.path().join(".rkat"))),
        );

        let actor_a_slot = LiveSessionActorWitnessSlot::default();
        let actor_a_admission = service
            .reserve_create_session_admission()
            .await
            .expect("reserve actor A admission");
        let created = service
            .create_session_with_reserved_admission_and_actor_witness(
                create_request_with_metadata("actor A", InitialTurnPolicy::Defer),
                actor_a_admission,
                &actor_a_slot,
            )
            .await
            .expect("create actor A");
        let session_id = created.session_id;
        let actor_a = actor_a_slot.witness().expect("actor A exact witness");
        let session = service
            .export_live_session(&session_id)
            .await
            .expect("export actor A session for exact recreation");
        let actor_a_boundary = service
            .acquire_live_session_actor_turn_boundary_lease_exact(&actor_a)
            .await
            .expect("acquire actor A boundary")
            .expect("actor A remains exact");
        assert!(
            service
                .discard_live_session_actor(&actor_a_boundary)
                .await
                .expect("discard exact actor A")
        );
        drop(actor_a_boundary);

        let actor_b_slot = LiveSessionActorWitnessSlot::default();
        let actor_b_admission = service
            .reserve_create_session_admission()
            .await
            .expect("reserve actor B admission");
        service
            .create_session_with_reserved_admission_and_actor_witness(
                resume_request(session),
                actor_b_admission,
                &actor_b_slot,
            )
            .await
            .expect("recreate actor B with the same logical session id");
        let actor_b = actor_b_slot.witness().expect("actor B exact witness");
        assert_ne!(actor_a, actor_b);
        let mut successor_stream = service
            .subscribe_session_events(&session_id)
            .await
            .expect("subscribe successor actor stream");

        let predecessor_event = AgentEvent::InteractionComplete {
            interaction_id: meerkat_core::interaction::InteractionId(
                meerkat_core::time_compat::new_uuid_v7(),
            ),
            result: "must stay fenced to actor A".to_string(),
            structured_output: None,
        };
        let predecessor_error = service
            .publish_interaction_terminals_exact_batch_for_actor(
                &actor_a,
                std::slice::from_ref(&predecessor_event),
            )
            .await
            .expect_err("revoked actor A publication must fail closed");
        assert!(matches!(predecessor_error, SessionError::NotFound { .. }));
        assert!(
            tokio::time::timeout(
                std::time::Duration::from_millis(100),
                successor_stream.next(),
            )
            .await
            .is_err(),
            "a delayed predecessor handle must not mutate or broadcast into actor B"
        );

        let successor_interaction_id =
            meerkat_core::interaction::InteractionId(meerkat_core::time_compat::new_uuid_v7());
        let successor_event = AgentEvent::InteractionComplete {
            interaction_id: successor_interaction_id,
            result: "published by actor B".to_string(),
            structured_output: None,
        };
        let receipts = service
            .publish_interaction_terminals_exact_batch_for_actor(
                &actor_b,
                std::slice::from_ref(&successor_event),
            )
            .await
            .expect("actor B exact publication must converge");
        assert_eq!(receipts.len(), 1);
        let published =
            tokio::time::timeout(std::time::Duration::from_secs(2), successor_stream.next())
                .await
                .expect("actor B terminal broadcast timeout")
                .expect("actor B stream closed");
        assert!(matches!(
            published.payload,
            AgentEvent::InteractionComplete { interaction_id, ref result, structured_output: None }
                if interaction_id == successor_interaction_id && result == "published by actor B"
        ));
    }

    #[tokio::test]
    async fn boundary_discard_publication_uses_exact_actor_and_original_run() {
        use futures::StreamExt;
        use meerkat_core::event::BoundaryAppendsDiscarded;

        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::new(MemoryStore::new()),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        );
        let created = service
            .create_session(create_request_with_metadata(
                "actor A",
                InitialTurnPolicy::Defer,
            ))
            .await
            .expect("create actor A");
        let session_id = created.session_id;
        let actor_a = service
            .live_session_actor_witness(&session_id)
            .await
            .unwrap();
        let before = service
            .inner
            .observe_session_transcript_authority(&session_id)
            .await
            .unwrap();
        let mut events = service.subscribe_session_events(&session_id).await.unwrap();
        let first = BoundaryAppendsDiscarded {
            session_id: session_id.clone(),
            run_id: meerkat_core::lifecycle::RunId::new(),
            input_ids: vec![
                meerkat_core::lifecycle::InputId::new(),
                meerkat_core::lifecycle::InputId::new(),
            ],
        };
        service
            .publish_boundary_appends_discarded_for_actor(&actor_a, &first)
            .await
            .unwrap();
        let published = tokio::time::timeout(std::time::Duration::from_secs(2), events.next())
            .await
            .unwrap()
            .unwrap();
        assert_eq!(published.source_session_id(), Some(&session_id));
        assert!(matches!(&published.payload,
            AgentEvent::BoundaryAppendsDiscarded(discarded) if discarded == &first));
        assert!(published.seq > 0);
        let mut mismatch = first.clone();
        mismatch.session_id = SessionId::new();
        assert!(
            service
                .publish_boundary_appends_discarded_for_actor(&actor_a, &mismatch)
                .await
                .is_err()
        );
        service
            .publish_boundary_appends_discarded_for_actor(&actor_a, &first)
            .await
            .unwrap();
        let second = tokio::time::timeout(std::time::Duration::from_secs(2), events.next())
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            second.seq,
            published.seq + 1,
            "one ordinary session sequencer owns publication"
        );
        assert_eq!(second.source, published.source);
        let after = service
            .inner
            .observe_session_transcript_authority(&session_id)
            .await
            .unwrap();
        assert_eq!(after.transcript_revision(), before.transcript_revision());
        assert_eq!(after.message_count(), before.message_count());
        assert_eq!(
            after.mutation_generation(),
            before.mutation_generation(),
            "discard publication does not mutate the current transcript image"
        );

        let session = service.export_live_session(&session_id).await.unwrap();
        let lease = service
            .acquire_live_session_actor_turn_boundary_lease_exact(&actor_a)
            .await
            .unwrap()
            .unwrap();
        assert!(service.discard_live_session_actor(&lease).await.unwrap());
        drop(lease);
        let slot = LiveSessionActorWitnessSlot::default();
        let admission = service.reserve_create_session_admission().await.unwrap();
        service
            .create_session_with_reserved_admission_and_actor_witness(
                resume_request(session),
                admission,
                &slot,
            )
            .await
            .unwrap();
        let actor_b = slot.witness().unwrap();
        assert_ne!(actor_a, actor_b);
        let mut successor = service.subscribe_session_events(&session_id).await.unwrap();
        assert!(matches!(
            service
                .publish_boundary_appends_discarded_for_actor(&actor_a, &first)
                .await,
            Err(SessionError::NotFound { .. })
        ));
        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(100), successor.next())
                .await
                .is_err(),
            "predecessor cannot publish through successor"
        );
        let next = BoundaryAppendsDiscarded {
            run_id: meerkat_core::lifecycle::RunId::new(),
            ..first
        };
        service
            .publish_boundary_appends_discarded_for_actor(&actor_b, &next)
            .await
            .unwrap();
        let published = tokio::time::timeout(std::time::Duration::from_secs(2), successor.next())
            .await
            .unwrap()
            .unwrap();
        assert_eq!(published.source_session_id(), Some(&session_id));
        assert!(matches!(published.payload,
            AgentEvent::BoundaryAppendsDiscarded(discarded) if discarded == next));
    }

